/* 平成25年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h25.committeeSessions.push(...[{"id":"h25-20130304-3","meetingId":"h25-c-budget","date":"2013年3月4日","dateIso":"2013-03-04","committee":"予算特別委員会","time":"午前１０時００分～午後６時００分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を174件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"鶴副委員長","kind":"質問・要望","question":"第１項、理事および理事会の設置についてです。閉会予定時間は、区役所の執務時間と同じく、午後５時１５分をめどといたします。１人当たりの質問時間は、答弁時間も含めて１０分、１５分、２０分のいずれかとし、会派で割り振ることとしております。終了時間のお知らせにつきましては、残り時間がなくなった時点で振鈴を２回鳴らしますので、質問の途中でありましても、直ちに取りやめていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":4,"id":"exchange-001"},{"speaker":"大沢委員","kind":"質問・要望","question":"お願いいたします。この三つに入る前に、ちょっと企画財政課長にお聞きしたいんですけれども、予算書、これは補正予算書ということで、予算書がまさに初日で上がってくるんですが、５ページに平成２５年２月２０日提出と記載をしてあります。これはお決まりということで、毎年書いてあるわけですけど、この意味合いについて教えていただきたいんですけど。","respondent":"本城企画財政課長","answer":"２月２０日の意味です。２月２０日につきましては、予算議案につきましては、議案として提出していますが、本会議の初日に予算の議案を上程する、その日です。","voiceIndex":9,"id":"exchange-002"},{"speaker":"大沢委員","kind":"質問","question":"そこのところで、どういうものが、法にしばられながら運用しているわけですから、そこのところはどういうようなところの法にのっとって、ここはあくまでも記載してあることすべて、ここのところの職員の給与の話、書いてある予算のところ、繰越明許、すべてが記載をすべく法にのっとってやっているわけですけど、ここのところの２月２０日というのは何なんですかという話を聞きたい。","respondent":"本城企画財政課長","answer":"この法令上の根拠ですが、地方自治法に基づきまして、市長が議会のほうに議案として提出するということで規定されているものです。２月２０日はその議案を上程した日という形です。","voiceIndex":11,"id":"exchange-003"},{"speaker":"大沢委員","kind":"質問","question":"伺います。法令上の、自治法になります。何条でしょうか。","respondent":"本城企画財政課長","answer":"今確認しています。ちょっとお時間をいただけますでしょうか。","voiceIndex":13,"id":"exchange-004"},{"speaker":"大沢委員","kind":"質問・要望","question":"はい、結構です。第２１１条に規定されていると思いますけれども、確認は後でしていただきたいと思うんですが、国あるいは政令都市にあっては、３０日、区はそこの記載はないですけど、市町村については２０日ということで記載がされているんですけど、私はそこのところでここが来ていると思うんですけれども、そこのところは正しいのか、正しくないのか教えてください。","respondent":"本城企画財政課長","answer":"自治法上は委員ご指摘がございましたように、そのときまでということで、最終期日の意味合いで指定されていまして、それを踏まえて品川区の区議会に対しましては、それ以上の前の日にちとして２月２０日ということで仕切っているところです。","voiceIndex":15,"id":"exchange-005"},{"speaker":"大沢委員","kind":"質問・要望","question":"はい、わかりました。この予算、個別のさっき６５ページと８５ページというお話をさせていただきましたけれども、まずこの予算についてちょっとお伺いしたいんですけれども、そもそも補正予算、これはどのような考えに基づき補正予算が編成をされるのか、ご説明いただきたい。","respondent":"本城企画財政課長","answer":"こちらにつきましては、補正予算全般の考え方ですが、平成２４年度、当初予算が成立した以降、事業をこの間執行していたところですが、その後に事情変更がございまして。","voiceIndex":17,"id":"exchange-006"},{"speaker":"大沢委員","kind":"質問・要望","question":"そのやむを得ない事情の中には、３・１１以降になる、いわゆる緊急性、３・１１あるいはリーマンショック、経済的なもの、それと災害的なもの、緊急性を要するとやむを得ない事情の中には、緊急性はもちろん入ると思うんですけど、そこのところ、予算を立てる側から、すみません、やむを得ない事情の中には、緊急性というものが入るのか、もう一回説明していただきたいと思います。","respondent":"本城企画財政課長","answer":"緊急的なものも含めて、事情の変更があったものについて、今回補正予算という形で上程しています。そして、緊急性の中には、種々ありますが、例えば国の補助金が急遽ついたとか、そういうことも含めた事情変更による緊急対応も含めて提案しています。","voiceIndex":19,"id":"exchange-007"},{"speaker":"大沢委員","kind":"質問・要望","question":"そうすると、緊急というところで、今課長からお話をいただきましたけれども、緊急に対する補正予算、そもそも補正予算ですから、やむを得ない事情、あるいは今おっしゃっていたような緊急性ということであるわけなので、ここのところで減額補正が多分に出ておりますけれども、本来補正であれば使い切るのが筋というか、使い切るのが理想というか、そう思うんですけど。","respondent":"本城企画財政課長","answer":"基本的に使い切るという関係で今ご意見があったところですが、必要なものはきちんと使いつつ、きちんとそのような契約落差等を含めて合理的な理由があって額が少なくなったものについては減額補正という形で対応しています。","voiceIndex":21,"id":"exchange-008"},{"speaker":"大沢委員","kind":"質問","question":"契約落差ということで、それは合理的な理由の一つ。では、伺います。契約落差を含めない合理的な理由というのは何でしょうか。","respondent":"本城企画財政課長","answer":"契約落差は今一つの例としてご説明させていただきましたが、そのほか、今回ももろもろ出ておりますが、事業の進捗状況で、最後まで事業を計画する中で、見込みとして少ない見込みが立っていたものとか。","voiceIndex":23,"id":"exchange-009"},{"speaker":"大沢委員","kind":"質問","question":"今の実績見合いということですので、実績に見合う部分ということで、そこのところをはじく場合にしっかりと検証されながら補正予算を立てていらっしゃるんじゃないか、実績見合いということですが、実績というのは既に前からのデータが出ているわけなので、そこら辺の補正の正確性というか、減額補正にならないようなしっかりとした予算の立て方というのが必要だと思うんですけど。","respondent":"本城企画財政課長","answer":"今委員がご指摘いただいたとおりだと私も認識しています。実績見合いと一括してお話しいたしましたが、積み重なった実績をもとに、これ以降の見込みもきちんと適切に立てた上で、実績に基づいたきちんとした査定をしています。","voiceIndex":25,"id":"exchange-010"},{"speaker":"大沢委員","kind":"質問","question":"そうしますと、実績見合いということ、先ほど実績見合いじゃなくて、やむを得ない事情の中からこのお話をいただいたわけですけれども、緊急性という部分、我が党でも過日の一般質問で石田秀男委員が発言いたしましたけれども、この緊急性の中で、緊急であるから、いわゆる防災対策もしかり、経済対策もしかりなんですけど、緊急であるからといいながら、どこまで予算の措置が許されるのか。","respondent":"本城企画財政課長","answer":"今回につきましても、先ほども例に挙げさせていただいた国の緊急経済対策ということで、急遽出てきたところなんかにつきましても、それについて区として国からの財源を特定財源として効果的に使うという。","voiceIndex":27,"id":"exchange-011"},{"speaker":"大沢委員","kind":"意見","question":"緊急はどこまで許されるのか。緊急が何回も、年度に応じてやると緊急が緊急でなくなるわけですけれども、そこら辺の考え方、どういうふうにお考えになりますか。","respondent":"本城企画財政課長","answer":"緊急ということにつきましては、補正予算、今年も年４回ほど組んでいるところですが、それぞれ事業の必要性についてよく吟味しまして、その時点でやるべきものにつきましては、当初予算後の事情変化ということで対応する必要があると考えているところです。","voiceIndex":29,"id":"exchange-012"},{"speaker":"大沢委員","kind":"質問","question":"この事業の中で、補正予算を組まれている中で、既にこのぐらい出るのではなかろうかという当初予算の見積もりの中で、なぜわかりきっているものに関しては補正の予算として計上されるのか、そこらあたりの考え方も伺いたいと思います。","respondent":"日下部企画部長","answer":"私ども先ほど来ご答弁申し上げていますように、当初予算を策定する時点で、それなりの見込みがしっかりしているものについては、もちろん先ほど来ご指摘をいただいておりますように当初予算にしっかりと計上していると、これが基本です。","voiceIndex":31,"id":"exchange-013"},{"speaker":"大沢委員","kind":"質問","question":"８ページ、繰入金ということで、補正額２１億円、出ていますよね。この２１億円が、補正の予算というものを、予算を立てるに当たって、２１億円という減額の補正、金額についての感覚といいますか、この２１億円に対するご意見、考えをちょっと伺いたいと思います。","respondent":"本城企画財政課長","answer":"これにつきましては、基金の繰入金の関係ですが、これは当初予定していた以上に国等からの特定財源という形でお金が入ってきたものが結構多かったものですから、その分、特定財源で流用すれば一般財源はその分使わなくて済んだと、そのような経緯です。","voiceIndex":33,"id":"exchange-014"},{"speaker":"大沢委員","kind":"質問","question":"時間がないので、予備費云々との関連もいろいろとあると僕自身はちょっと勉強した中で思いますので、５３秒しかないので、これで質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-015"},{"speaker":"阿久津委員","kind":"質問・要望","question":"それと、６８ページ、民生費から児童福祉費、家庭的保育事業、そして時間があれば少し戻りまして、６６ページ、障害者福祉費、介護人派遣事業についてお伺いをしたいと思います。今回２校をあわせて４,０００万円余が補正予算に計上されているわけですけれども、どの学校を選ぶのかとか、そういう申請の計画とかスケジュール等について簡単に教えていただきたいと思います。","respondent":"齋藤庶務課長","answer":"来年度につきましては、２校人工芝を予定している学校がございまして、小学校では立会小学校、中学校では荏原第五中学校です。","voiceIndex":37,"id":"exchange-016"},{"speaker":"阿久津委員","kind":"質問","question":"その条件、選ばれる条件には校庭を地域に開放しているということと、土壌ですか、そこの地域的な事情もあるというような今お話をいただきました。このスポーツ振興くじ助成金なんですが、ちょっと前置きが長くなって申しわけないんですが、平成１４年度からスタートして１０年たっておりますが、区内において学校のグラウンドの人工芝生化をした実績というのは何校なのか教えてください。","respondent":"齋藤庶務課長","answer":"実績ですが、戸越台中学校、第三日野小学校、今年度になりまして、荏原第六中学校と第二延山小学校の４校です。","voiceIndex":39,"id":"exchange-017"},{"speaker":"阿久津委員","kind":"質問","question":"これは素人考えなのかもしれませんけれども、できるだけ広くという形で、例えば１校１,５００万円ぐらいで３校申請とか、こういったことはできないんでしょうか。","respondent":"齋藤庶務課長","answer":"どの学校をどう選んでどう申請するかにつきましては、サッカーくじのスポーツ振興センターとの採択の関係もございまして、過去何年か分の地域開放の実績ですとか、そういったものの見合いで提出する関係もございまして、本年度につきましては２校を選んだです。","voiceIndex":41,"id":"exchange-018"},{"speaker":"阿久津委員","kind":"質問・要望","question":"やはり先ほどありました土壌が悪いとか、風が吹けば砂が飛ぶと、これはいろんなところでいろんな苦情がありますし、要望があると思います。こういったところは本当に子どもを集めるのに、入学者を集めるのに今大変な苦労をしています。このサッカーくじを使わなくても公立学校の国の施設整備費、こういったものも活用していただきたいと思いますけれども、この辺のご見解をお聞かせください。","respondent":"齋藤庶務課長","answer":"サッカーくじの活用、小規模校ということにつきましては、各学校の事情もあります。地域に砂ぼこりでご迷惑をかけている学校もありますので、各学校の事情、学校と相談しながら検討してまいります。","voiceIndex":43,"id":"exchange-019"},{"speaker":"阿久津委員","kind":"質問・要望","question":"ぜひ進めていっていただきたいと思います。続きまして、６８ページ、民生費、児童福祉費から、家庭的保育事業について伺います。家庭的保育事業、これはマイナス４,４３４万８,０００円となっておりますが、この理由について教えてください。","respondent":"伊崎待機児童対策担当課長","answer":"在宅型と事業所型、在宅型３カ所の予定で当初予算を組んでおりましたが、１カ所の開設、事業所型につきましては、３カ所の予定が２カ所の年度内開設で、１カ所は今度の４月に開設するということで、開設数の減と時期の遅れです。","voiceIndex":45,"id":"exchange-020"},{"speaker":"阿久津委員","kind":"質問","question":"保育ママになる方を募集するこのホームページのページだと、３人定員で保育をした場合に、年収４００万円以上の収入となると、このようにうたわれておりますけれども、実際保育ママは補完的な事業ということもありまして、年度が随分進んでから３人の定員が埋まると、こういう状況にあると思いますが、本当に４００万円の収入が、私も知り合いの保育ママの方がいらっしゃるものですから、ここら辺。","respondent":"伊崎待機児童対策担当課長","answer":"ただ、こちらにつきましては、開設のご相談を受ける時点で、こういった事業の補助形態だということをご理解いただいた上で取り組んでいただいているです。","voiceIndex":47,"id":"exchange-021"},{"speaker":"阿久津委員","kind":"確認","question":"それに関連して、先日から杉並区、足立区で認可保育所の一次申し込みで不承諾となったお母様、保護者の方から異議申し立ての問題が起きておりますけれども、品川区の状況についてお伺いします。２月２６日付の東京新聞では、品川区では認可保育所受入枠に対し、３２％の子どもが入れず、６８５人の児童が入れなくなっているとされていますが、この数字の確認をさせてください。","respondent":"伊崎待機児童対策担当課長","answer":"東京新聞の記事ですが、こちら、新聞社からの質問内容は、申込者数と一次の入園枠として当初提示した数字ということでございましたので、そのようにお答えいたしましたところ、こういった記事が出されたということでございまして。","voiceIndex":49,"id":"exchange-022"},{"speaker":"阿久津委員","kind":"質問","question":"ただ、これは放っておくわけにはいきませんので、待機児童対策といたしまして、先ほどの杉並区の区長は猪瀬東京都知事にお会いに行かれて、新年度予算に東京都が整備費を計上したスマート保育、この活用をしてくださいと、このようなことを言われたとありますけれども、これはちょっとお母さんたちは認可保育園といっていて、ちょっとギャップがあるとは思うんですが、品川区ではスマート保育の活用。","respondent":"伊崎待機児童対策担当課長","answer":"小規模保育、スマート保育というのは小規模保育のことですけれども、小規模保育につきましても、今後制度の内容をよく精査しまして、採用の必要が出てくれば対応していきたいと考えておりますが、現時点では事業所型保育ママでそのニーズは一定満たせると考えております。","voiceIndex":51,"id":"exchange-023"},{"speaker":"阿久津委員","kind":"質問・要望","question":"もう時間もないのであれですけれども、先ほど事業所型の保育ママで小規模保育、そのニーズに応えていきたいというご答弁があったと思うんですけれども、その意味も含めて、保育ママ制度、しっかりこれを区民に周知をしていただきたい、ぜひ入りたいと思わせるような、そういった周知の仕方を考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-024"},{"speaker":"藤原委員","kind":"質問","question":"４０ページの特別区民税、５４ページ、基金繰入金、５９ページ、基金積立金追加分、１００ページ、繰越明許費。区民税なんですけど、補正は３.１％増ですよね。ここを少しちょっと矛盾に感じるんですけれども、補正でいわば大きく増、当初では減というあたりということは、経済状況をどういうふうに判断して、この税収を見込んだのか、まずお伺いします。","respondent":"高森税務課長","answer":"これにつきましては、毎年そうなんですけども、前年度の収入に対して課税をさせていただいているわけですけれども、実は納税義務者数が見込みよりも多くなっている状況にございまして、またなおかつ、この中身なんですけども。","voiceIndex":55,"id":"exchange-025"},{"speaker":"藤原委員","kind":"意見","question":"見込みどおりになればいいんですけど、企画財政課は、この経済状況といいますか、この件に関してどう考えていますか。","respondent":"本城企画財政課長","answer":"それの影響もあって、よくなる方向の兆しは確かに見てとることができると思いますが、ただ海外の経済状況とか輸出環境に及ぼす影響等不透明感がありますので、税収の見込みに当たっては財源を確かに見込まなければいけないということがありますので。","voiceIndex":57,"id":"exchange-026"},{"speaker":"藤原委員","kind":"確認","question":"逆に総務費の追加分が２８億円余、教育費の追加分が５億円余という形で出ていますけど、平成２４年度当初予算から見ると、結局５５億円弱いわゆる余計だったということでいいんでしょうかという確認と、それとこうなった理由と、またこういうふうにならざるを得なかった理由についてお伺いしたいのと、あといつも伺うんですけど、この基金について品川区としては目標額を設定していかないのかということと。","respondent":"本城企画財政課長","answer":"基金に関するものですが、今回新たに基金を積み増している部分があります。それについては、基本的に一番大きい要因といたしましては、財調の交付金につきまして、予定よりも約２８億円ほど改めて増額の算定をされたものがあります。","voiceIndex":59,"id":"exchange-027"},{"speaker":"藤原委員","kind":"意見","question":"ちょっと繰越明許費についてよくわからないんですけれども、そこを、もっと見込みをちゃんとやっていくのが企画財政課の仕事だと思うんですね。そういう答弁になっちゃうと、すべてがそれで済まされちゃうような気がするんですけれども、その辺について、もっときっちりもう少しやっていったほうがいいんじゃないかなと思うんですけれども、その辺について、もう一回答弁していただけますか。","respondent":"本城企画財政課長","answer":"種々の事情変更とか、あるいは今回は特別に国の補正の関係等ございましたが、事業調整の中で可能な限り調節すること、あとやむを得ないものについては、必要に応じてやむを得ず繰越明許にしていくと、そのような形で対応しています。","voiceIndex":61,"id":"exchange-028"},{"speaker":"木村委員","kind":"質問・要望","question":"番号は２３の重症心身障害者通所事業運営費補助金、７７６万６,０００円からの質問ですが、元都立府中療育センターの院長でありました大島博士が、副院長時代に発表した重症心身障害児の区分けですが、これを大島分類というそうですが、当センターでは、この１から４に当てはまる重症心身障害者で、また都知事が入所の必要があると認める方を入所対象としているそうですが、これを医学的診断名ではなく。","respondent":"永尾障害者福祉課長","answer":"重症心身障害者通所事業につきましては、平成２４年６月に八潮の８号棟の１階に開設をいたしました。１８歳以上の方の通所施設で、今委員のご説明のとおり大島分類では１から４の範囲をおおむね利用者の対象としている事業です。","voiceIndex":66,"id":"exchange-029"},{"speaker":"木村委員","kind":"意見","question":"今度５６ページの下から３番目、番号は２７になりますけど、障害者自立支援給付金、５６２万円余とありますけれども、今の通所事業運営費補助金と何か関係をしているのか、関係していると思いますが、もし関係していれば、こちらのほうもご説明を願いたいと思います。それから東京都国民健康保険団体連合会と説明欄に記載されていますが、何をする団体なのか、これもご説明を願いたいと思います。","respondent":"永尾障害者福祉課長","answer":"重症心身障害者の通所事業につきましては、これまで東京都の事業でございました。平成２４年４月から障害者自立支援法の改正によりまして法内化をされています。そのときに、国は障害者自立支援法の生活介護と位置づけることになっています。","voiceIndex":68,"id":"exchange-030"},{"speaker":"木村委員","kind":"意見","question":"区が国と直接交渉するのではなく、障害者自立支援法が変わった平成２４年４月からの助成金が変わるために市区町村、窓口となって一括して交渉するという解釈でいいかと思いますが、自立支援法が改正され、東京都の補助金で運営されていたと思いますけれども、そこに国が関与してくる、関与というか、入ってきたということですけれども、東京都と区が負担している予算、国が入ることによって２分の１。","respondent":"永尾障害者福祉課長","answer":"現在、重症心身障害者の通所事業は、八潮１カ所になっております。そのほかの重症の方につきましては、城南分園等をご利用したりしているところです。","voiceIndex":70,"id":"exchange-031"},{"speaker":"木村委員","kind":"質問","question":"今度は６７ページの下にありますけれども、重症心身障害者通所施設運営費に対する都支出金および諸収入の交付に伴いとありますけれども、この都支出金７７６万６,０００円は都からですけれども、諸収入の２３０万円はどこからの諸収入でしょうか、お答えください。","respondent":"永尾障害者福祉課長","answer":"諸収入の障害者自立支援給付費につきましては、先ほどちょっとご説明いたしましたとおり国のほうの報酬ということになりますので、国２分の１、都４分の１、区４分の１の分ですけれども、この重症心身障害者の通所事業につきましては、もともと東京都がやっておりまして。","voiceIndex":72,"id":"exchange-032"},{"speaker":"木村委員","kind":"質問","question":"障害者手帳の１級、２級、また愛の手帳１度、２度の合計人数は、品川区で何人ぐらいになりますか。そして、区内の重症者で若い方がだんだん増えていると聞きます。１０年後、２０年後、品川区の重症者数はどのように推移するとお考えでしょうか、お答えください。","respondent":"永尾障害者福祉課長","answer":"ですので、これを考えますと、１８歳以上になったときには、もっと増えているんじゃないかなというふうに予測できます。","voiceIndex":74,"id":"exchange-033"},{"speaker":"木村委員","kind":"質問","question":"１２５名ぐらいだろうということでありますけれども、全員がこのような作業所や別の施設に通っているのでしょうけれども、通所作業所、先ほども言いましたけれども、八潮にあるということでありますが、大体事業所には何人ぐらいが通所して、１週間に何回通所するのでしょうか。それをお世話いただく方はどれぐらいいらっしゃるのか、お答えください。","respondent":"永尾障害者福祉課長","answer":"職員体制につきましては、サービス管理責任者、常勤の方１名、あと児童指導員の方１名、看護師の方が２名、あと非常勤で理学療法士の方が１名、あと嘱託医の方が月に１回から２回程度いらっしゃるという状況になっております。","voiceIndex":76,"id":"exchange-034"},{"speaker":"中塚委員","kind":"質問","question":"介護保険特別会計につきまして、１７６ページの基金積み増しの理由と、今後どこに充てていくのかということを中心に伺いたいと思います。今回の最終補正では、基金積立金１億６,４００万円余を新たに積み増すわけですけれども、この関係でどんな影響が生まれてくるのか、介護サービスの利用料や、介護保険料、またこの基金取り崩し額や残高についての影響、現状と見通しについて伺いたいと思います。","respondent":"原高齢者福祉課長","answer":"一つは介護給付費準備基金、こちらのほうを１０億円余、それから介護財政安定化基金、こちらのほうを２億２,０００万円ほど繰り入れて、１２億９,０００万円の予定をしています。","voiceIndex":79,"id":"exchange-035"},{"speaker":"中塚委員","kind":"質問","question":"当初では準備基金の残高は幾らだったのか、改めて伺いたいと思います。要するに、東京都からの財政安定化基金の支出金の話がありましたけれども、当初予定していなかったものが入ってきたという関係にあるのでしょうか。要するに、今後どれぐらい東京都から入ってくるのか、その全額といいますか、第五期ではどれぐらいを見込んでいるのか、見通しを伺いたいと思います。","respondent":"原高齢者福祉課長","answer":"そういった意味では、こちらのほうを当初２億２,０００万円と予定しておりましたので、ほぼ基金の繰り入れとしては同額の繰り入れということで考えたところです。","voiceIndex":81,"id":"exchange-036"},{"speaker":"中塚委員","kind":"質問","question":"当初１０億円を取り崩して８億円余にしようかということですけども、今日の補正予算でも、平成２４年度末基金見込みは１８億円になっているわけですよね。私はやはり、もともと介護保険料ですから、保険料の引き下げや介護サービスの利用料減免の拡充、こうしたところに充てていくことが必要ではないかと思いますけれども、見通しや考え方を伺いたいと思います。","respondent":"原高齢者福祉課長","answer":"ただ、３年にわたって入ってくるのが１年で入ってきたということで、補正をさせてもらっているということで、当初から見込んでいた数字とほぼ同額です。","voiceIndex":83,"id":"exchange-037"},{"speaker":"中塚委員","kind":"質問","question":"要するに３年間かかって来るものが、１年間になったわけで、そこを初めから見込んでいたとのご説明でありますが、今回の最終補正でも１８億円となっているわけですから、そこを活用しての保険料の引き下げ、あとサービス利用料の減免の拡充、ここを行っていくべきだと思うんですけども、どのような検討がされているんでしょうか。","respondent":"原高齢者福祉課長","answer":"基金については３カ年で経過をしておりますので、まだ初年度ということで、この給付費を見ましても、平成２３年から平成２４年で約９％弱の給付費の伸びを見込んです。","voiceIndex":85,"id":"exchange-038"},{"speaker":"中塚委員","kind":"質問・要望","question":"今ご説明があった２３区の区長会で国に求めているとのご説明、その内容について、もう少しご説明いただきたいと思います。","respondent":"原高齢者福祉課長","answer":"国におきましても、社会保障と税との一体改革、こういったところの今後の介護保険の制度の維持に向けて、さまざまな形で検討に入っているというところで、こういった動きを区としても注意深く見守っていきたいというふうに考えているところです。","voiceIndex":87,"id":"exchange-039"},{"speaker":"中塚委員","kind":"質問・要望","question":"ちょっとこの２３区が国に求めているものが何かよくわからないんですけれども、要するに各区で制度をつくっているわけですけれども、２３区が統一して国にどんな減免を求めているのか、どんな利用料の設定を求めているのか、そこを改めて伺いたいと思います。要するに保険料あって、サービスなしと、こういう状況の改善が必要だと思いますので、中身をもう一度伺いたいと思います。","respondent":"原高齢者福祉課長","answer":"そういった中で、利用料の減免は、各自治体がそれぞれ考えるのではなく、国の制度としてこういった軽減策については統一した考え方を持ってほしいと、こういったところを要望しています。","voiceIndex":89,"id":"exchange-040"},{"speaker":"塚本委員","kind":"質問","question":"公共施設整備基金積立金１５億円、義務教育施設整備基金積立金５億円ということで、多くの金額が積立金のほうに回っていると、こんな印象を受けているんですけれども、いわゆる年度内の増収分について、積立金としていくのかと、あるいは各事業のほうで予算をつけて事業をより一層拡充していくのか、こういったところの一つの考え方の基準ですね。","respondent":"本城企画財政課長","answer":"増収分の今度の一つの大きなものが、今委員ご指摘がございました財調の再調整ということで、約２８億円の増を見込んでおります。","voiceIndex":92,"id":"exchange-041"},{"speaker":"塚本委員","kind":"質問","question":"今１個１個の事業を精査してというようなお話でありましたけれども、こういった財調とかで大きな増収が見込めるというふうになったときに、各事業部とか各課に対して、いわゆる概算要求みたいなもの、集めるというか、要求を受けたりとかということをすることがあるのかないのか、もしあるとすれば、どのような形でこういう年度内の増収について予算の執行をしたいんだというような要求を。","respondent":"本城企画財政課長","answer":"予算の編成、補正予算の時期になりましたら、事業の過不足分等について報告して、補正予算が必要な部分はどの部分なのか、全体を吟味した上で補正予算を組み立てていくという考え方です。","voiceIndex":94,"id":"exchange-042"},{"speaker":"塚本委員","kind":"質問","question":"もうちょっと詳しくお聞きしたいんですけども、そこら辺のところで、各事業部との企画財政課とのやりとりというのは、どういうふうなやりとりがあるのかというのをお伺いしたい。","respondent":"本城企画財政課長","answer":"すみません、言葉足らずで申しわけありません。","voiceIndex":96,"id":"exchange-043"},{"speaker":"塚本委員","kind":"質問","question":"こういった、私のこれは考えなんですけれども、いわゆる振興費というようなまちのにぎわいとか、あるいは活性化とか、こういったものにつながるような予算というのは、こういった国とか都から来たので、結果的には拡充はしているのかもしれませんけれども、一般財源のほうを減額とかをするのではなくて、全部使い切るというような思いで。","respondent":"本城企画財政課長、安藤文化スポーツ振興課長","answer":"先ほど補正の関係で、幾つかのタイミングの補正がありますが、９月補正と年度途中の補正の場合は、新たな事業を立ち上げるという意味も結構出てくるんですが、最終補正の場合は、最終補正が本当に年度末の補正ですので。私のほうから、まず４９ページの都の支出金の歳入ですが、これは国民体育大会の経費として、これは追加として１０月あたりに東京都のほうから補助金の対象事業の拡充のためということで急遽参りました。","voiceIndex":98,"id":"exchange-044"},{"speaker":"塚本委員","kind":"質問・要望","question":"続きまして、６６ページの社会福祉施設費のところで、これも先ほどちょっとお話があったかと思うんですけれども、当初予算から自立支援法改正等の影響によって国・都の支出金がありまして、いわゆる一般財源をそういった支出金のほうに更正減額という形をしているですけれども、こういった支出金というのは、当初予算ではなかなか予測ができないものというようなことで捉えてよろしいのでしょうか。","respondent":"永尾障害者福祉課長","answer":"この制度につきましては、平成２４年４月からの法改正ということで、負担金の支払いの仕方が変更になりました。","voiceIndex":101,"id":"exchange-045"},{"speaker":"塚本委員","kind":"質問・要望","question":"ピッコロでのレスパイト事業なんかにつきましても、未就学児童ということになっておりますけれども、就学児童においても利用可能にしてもらいたいと、さまざまなこんな要望が寄せられているかというふうに思いますけれども、今後この自立支援法によってさまざまな補助金等で予算もつくという中で、こういった事業について今後拡充をしていくご予定等、補助金等をしっかり目配りしながら。","respondent":"永尾障害者福祉課長","answer":"実際に重度の方の親御さんなんかに聞いたところ、やはり小学生ぐらいまでやってくださるとありがたいというお話がございましたので、平成２５年４月から小学生まで拡大しようかということで検討を進めているところです。","voiceIndex":103,"id":"exchange-046"},{"speaker":"大倉委員","kind":"質問","question":"私からは、９３ページの学校改築推進経費更正減額に関連してちょっと伺いたいのと、７０ページ、７１ページの生活保護費について少しお伺いできればと思います。理由としては、使用していた体育館の床がささくれたり、ひび割れたりしたということなんですが、これが事実かどうかお知らせいただくのと、その工事に関する張り替えの費用等々を教えていただければと思います。","respondent":"齋藤庶務課長","answer":"その費用につきましては、体育館を建設して間もなくささくれ立つという現象が生じましたので、私のほうで施工業者、建材会社、設計会社を呼んで、施工者の負担で改修するようにということでお話をして、現在も１週間に１回施工会社が点検に来まして、不具合があったら直す。","voiceIndex":107,"id":"exchange-047"},{"speaker":"大倉委員","kind":"質問","question":"一部張り替えということなんですが、どの程度の大きさ、部分というか、面積なのか教えていただければと思います。その費用に関しても、もう一度ご発言いただければと思います。","respondent":"小林施設整備課長","answer":"どのくらいの範囲というのは、部分的な補修をしまして、主に伸縮の問題で、ささくれが起きましたので、部分的な補修、そこの一つのピースを取り替えるという形でやっております。費用については、全て業者の責任においてやっております。","voiceIndex":109,"id":"exchange-048"},{"speaker":"大倉委員","kind":"質問・要望","question":"費用は業者でやっているということなんですが、そうすると、業者側の責任があって、伸縮とかという部分を計算できていなかったとか、そういうことでいいのかお知らせいただきたいのと、夏休み期間、学校がない期間で張り替えたりされたんだと思うんですが、それだけで１カ月かかるということは、やっぱり大規模な張り替えだったのかなと思っているんですが。","respondent":"小林施設整備課長","answer":"夏休みの１カ月というのは、部分的にピースを取り替え、それでなおかつ全面研磨をしまして、塗装し直したです。原因については、今、週１回のデータどりをして様子を見て、現在理由を調べている最中です。","voiceIndex":111,"id":"exchange-049"},{"speaker":"大倉委員","kind":"質問・要望","question":"小学生でも、今その学校では体育が、武道で剣道をやられていると思うんですが、そういった部分でもけがとかという心配があるので、ぜひともしっかり対応していただきたいということはあるんですが、業者側が全額持ってやっていて、原因がわからないというのは、伸縮性と先ほどおっしゃっていた部分とほかにも何か考えられる原因があるのかどうか教えてください。","respondent":"小林施設整備課長","answer":"体育館の床が木材ということで、伸縮の問題で一番取り上げられるのは、湿度の関係だと思います。それで、今現在、週１回の現場調査をしまして、湿度と温度と全てのデータどりをして検討をしている最中です。","voiceIndex":113,"id":"exchange-050"},{"speaker":"大倉委員","kind":"質問","question":"今も話を伺うと、張り替えて研磨したけども、今もまた隙間ができたりささくれができたりということが起きているというのを聞いています。その間の期間、８月分とかそういった体育館を使用している例えば地域の方々、スポクラとかスポレクとかの利用者の方々の対応というのはどうされたのか、お聞かせいただければと思います。","respondent":"小林施設整備課長","answer":"施設整備課のほうでは、施設を管理している学校長と綿密な打ち合わせをしまして、工事に入る前は当然今委員がおっしゃったとおり団体関係につきましても、中止になりますので、各所管の課と打ち合わせをしまして、日程を調整いたしました。","voiceIndex":115,"id":"exchange-051"},{"speaker":"大倉委員","kind":"質問・要望","question":"それは要望しておきます。それで、そういった工事がそういう業者で起きるときの、今品川区の現在の新しい建物とかをつくる際の、工事期間中に業者がやっている工事についての調査とか、どういった工事をしているのかということを確認されていると思うんですが、どういう確認をされているか、教えていただきたい。","respondent":"小林施設整備課長","answer":"今お話ししました１週間に１回現場に行きまして、まず床の状況関係を確認したりとか、そういうのをしております。それについては、全てどういう状況だったのかというのが、逐次施設整備課のほうに報告に入っております。","voiceIndex":117,"id":"exchange-052"},{"speaker":"大倉委員","kind":"質問・要望","question":"次はちょっと時間がないので、ちょっと概要だけ聞かせていただければと思います。７１ページなんですが、生活保護費の医療扶助費のマイナス６億１,０００万円余の理由と、住宅等その他扶助費と書いてありますが、住宅等その他扶助費と書いてある理由、全体的に書いていないのはどうしてなのかというのを教えていただきたい。","respondent":"竹田生活福祉課長","answer":"医療費のほうですが、はっきりした原因はまだ特定できていないんですけれども、考えられる要因といたしましては、ジェネリック等の普及と、それから高額の医療にかかる方が今年度においては非常に減っているという状況で、減額補正を考えているところです。","voiceIndex":119,"id":"exchange-053"},{"speaker":"原委員","kind":"質問","question":"私のほうは、ページ数でいきますと、６８ページ、７０ページ、それから６４ページ、時間があれば補正全体について、午前中もあったんですけど、お聞きできればと思います。６４ページの民生費のうちの児童福祉費について、もう少し細かいご説明をいただければと思います。よろしくお願いしたします。","respondent":"竹田生活福祉課長、梶青少年育成課長、堀越人事課長、安井子育て支援課長","answer":"最終的には年度末には４％まで世帯が増えることを見込みまして、最終的に１２１億３,０００万円余と見込んでいるため。私のほうは児童福祉総務費の補正の内容ですけれども、私のほうでやってありますのが、そちらの福祉総務費の医療費助成事業。その後の人事異動等によって給与単価等が変わってまいりますので、今回補正という形でお願いをしているというものです。私のほうの児童福祉総務費のひとり親家庭支援事業ですが、自立支援助成事業、こちらは母子家庭の高等技能訓練促進費の実績減といいますか。","voiceIndex":122,"id":"exchange-054"},{"speaker":"原委員","kind":"質問","question":"児童福祉費についてはわかりました。それから、総務費なんですけれども、平成２３年１０月ということで、これは了解いたします。ですから、私は逆に一概に全部減らせと、何でもかんでも減らせというのでは、これはやっぱりモチベーションの問題もあるので、今後においてどういうふうに考えられているか、それをちょっとお聞かせいただければと思います。","respondent":"竹田生活福祉課長、堀越人事課長","answer":"生活保護費の今後の見通しというお話ですが、ちょっと過去の推移のほうからご説明します。平成２１年度、平成２２年度におきましては、対前年同月比が１０％前後の増加で、世帯数は増加しておりました。職員給与費です。こちらは監査委員の事務局費の職員の給与費でございまして、この増額の部分につきましては、先ほどご説明をさせていただいたとおりです。","voiceIndex":127,"id":"exchange-055"},{"speaker":"原委員","kind":"質問・要望","question":"これは初めのほうはわかりましたけど、監査委員の、これは傾向的には区以外、都道府県ですとか、その辺の全体の動きを見ていただいて、もう少し大きい動きがいろいろ出てこようかと思いますので、その辺を研究いただければと、これは要望です。","respondent":"本城企画財政課長","answer":"使い切るということに関して申し上げれば、当初組んだ予算については、当初の計画がありますから、その予定どおりにいくのがベストという面はありますが、ただ、何らかの理由で事情の変化によって不必要なものが出てきた場合も当然想定されます。","voiceIndex":130,"id":"exchange-056"},{"speaker":"原委員","kind":"意見","question":"補正に関しては、全体のボリュームですとか、先ほど午前中からよく出ているように緊急性とか、そういった面がいろいろあろうかと思うんですけれども、やはりいつも区長がおっしゃっているスピードなんだよと、いろんな施策、政策をやっておられる中では、全体的なバランスもありますけれども、それが臨機応変に対応したスピード感をもって対処したときに、初めて効果が発生するんだと私も思っておりますので。","respondent":"本城企画財政課長","answer":"予算を作成した後にもろもろの事情が出てくる場合もあります。そういう場合については、補正を組むという形とともに、予算を当初組んだ趣旨を見合う形で流用等の対応も含めて臨機に対応して、区民のニーズに迅速的確に応えていくというのが大切なことだと考えているところです。","voiceIndex":132,"id":"exchange-057"},{"speaker":"山内委員","kind":"質問","question":"７６ページ、土木費、土木総務費の自転車に関することをちょっと伺いたいと思います。部長に伺います。前任の都市環境事業部長は、この委員会等で自転車の利用を抑制してもらいたいといったことをおっしゃっておられましたけれども、その考えは今の部長も同じなのか、そういったところからこの自転車の問題といったものもやはりいろいろと考えていかなきゃいけないので、そのあたりをまず伺います。","respondent":"松代防災まちづくり事業部長","answer":"そういったことをきちんと守っていただければ、自転車というのは非常に効用があるものと、このように考えているところです。","voiceIndex":135,"id":"exchange-058"},{"speaker":"山内委員","kind":"質問","question":"自転車は私も利用することがありますけれども、非常に便利なんですよ。それで、一つ伺いたいのは使用料、この更正減額がありますけれども、これは文面で使用料および諸収入の増額等に伴い、同額一般財源を更正減額するといったことで記載されておりますけれども、ちょっとわからないんですが、教えてください。","respondent":"谷口交通安全担当課長","answer":"今委員ご質問の自転車料金が上がったのか、使用者が増えたのかです。これは使用者が増えたということで、使用料収入が増えたということで、諸収入の増額に伴いまして一般財源を減額したです。","voiceIndex":137,"id":"exchange-059"},{"speaker":"山内委員","kind":"質問","question":"そうしますと、使用者は増えているけれども、しっかりと駐輪場を整備しているといった形のお示しといった形で理解をしますけれども、その中で、「等」と書いてありますよね。「増額等」と書いてありますけど、この「等」の意味は何なんでしょうか。これをまず教えてください。","respondent":"本城企画財政課長","answer":"これについては、増額のほかに減額も含まれて、それを差し引いてという意味です。","voiceIndex":139,"id":"exchange-060"},{"speaker":"山内委員","kind":"質問","question":"わかりました。自転車は今後も私は増えていくと思うんですよ。今電動アシストつき自転車ですか、これが非常に増えています。","respondent":"谷口交通安全担当課長","answer":"今ご質問の民間の参入ですけれども、平成２５年になって再度調査しましたところ、民間だけで１９カ所、民間のベースですね、駐輪場が増えてあります。区のほうは２３カ所で増えていないんですけど、どんどん民間の参入があるということで、民間の利益につながっているです。","voiceIndex":141,"id":"exchange-061"},{"speaker":"山内委員","kind":"質問・要望","question":"わかりました。駐輪場は今後も増えていくのかなという期待もしつつ、これはちょっと指摘をさせていただきたいと思います。品川は、いろいろと駐輪に関するいわゆるチェックが非常に充実をしていると思うんですね。それから、そういった対応、対策を今後していくという考えは今庁内でお話をされているのか、そういったところを伺いたいと思います。","respondent":"谷口交通安全担当課長","answer":"ただ、あとうちの区としてやっていくこととしまして、ちょっと一部放置禁止区域指定が漏れている箇所もありますので、そちらは区としても前向きに指定、禁止に向けて取り組んでいくことで検討しています。","voiceIndex":143,"id":"exchange-062"},{"speaker":"山元委員","kind":"質問・要望","question":"私は７２ページの保健衛生費の中の不妊治療助成事業追加分について、９６７万５,０００円ですかね、このことについてお聞きをしたいと思います。","respondent":"江部健康課長","answer":"これにつきまして、具体的な調査をしているということではございませんけれども、申請からあらわれる件数の増加について、治療のニーズは高くなっているものと認識しております。","voiceIndex":146,"id":"exchange-063"},{"speaker":"山元委員","kind":"質問","question":"ある意味、不妊治療を知られたくないという方もおいででしょうし、また逆にこの情報を得たいという方もおいでかと思いますが、実際問題、品川区として不妊治療の助成といいますか、品川区として、平成１８年から助成制度を行っているわけですけども、実際この不妊治療に対してのお知らせというか、周知といいましょうか、そういうのは品川区としてどのようにしていらっしゃるのか、実際。","respondent":"江部健康課長","answer":"２点目の予測といいますか、目標ということにつきましては、これは立てられるものではないのかなというふうに思っておりまして、申請件数の増加、それから申請される方の年齢が少しずつ上がっているという実態は把握しておりますけれども。","voiceIndex":148,"id":"exchange-064"},{"speaker":"山元委員","kind":"質問・要望","question":"毎年少しずつ件数が増えているということでありますけれども、実際内容というんですかね、年代別というんでしょうか、どういう方たちが助成制度を受けていらっしゃるのか。実際受けていらっしゃる方たちというのは、仕事を持っていらっしゃる方が多いのか、それとも専業主婦というんでしょうかね、そういう方たちが多いのか、その辺、もしおわかりになれば教えていただきたいと思います。","respondent":"江部健康課長","answer":"２点ございました。年代別申請件数割合ですが、５歳刻みで申しまして、一番多いのが３５歳から３９歳の方が４３％です。次に多いのが３０歳から３４歳が２９％、その次が４０歳から４４歳で２２％、これで９割を超えるという状況にあります。","voiceIndex":150,"id":"exchange-065"},{"speaker":"山元委員","kind":"質問・要望","question":"そういう意味で、品川区も平成１８年から年間で１０万円、トータルすると５０万円、自己負担２分の１ということで、１０万円負担をしてくださるということなんですけれども、現実、もし把握していればの話なんですが、実際不妊治療の金額的なものというんでしょうか、いろいろ聞くと何十万円とかと聞きますけれども、実際どのぐらい、人によってはもちろん受けるものが違うから多少はあると思いますが。","respondent":"江部健康課長","answer":"１回当たりの金額というのは千差万別で、もろもろですが、１人当たり１年間治療をまとめて申請していただいた２分の１を支給しておりますが、その単価は４万５,０００円です。そうしますと、９万円程度お一人当たり平均でかかっているです。","voiceIndex":152,"id":"exchange-066"},{"speaker":"山元委員","kind":"質問","question":"実際、本当にもちろん東京都から補助を受けていると、そういう意味では、実際体外とか顕微受精ですかね、４０万円、５０万円かかる中、そういう補助というのはやっぱり負担がかかっているなと思うんですけれども、実際港区なんかは１世帯に当たりますけども、最大１５０万円の助成があり、また世田谷区は１００万円、そして千代田区では７５万円という助成があるというふうに聞いております。","respondent":"江部健康課長","answer":"私どもは、そこまで至らない一般的な不妊治療の助成を、裾野を広げてやっているということでございまして、その高額につきましては、東京都のほうでの助成に委ねているという考え方ですので、他区と一概に比較するものではないという認識をしております。","voiceIndex":154,"id":"exchange-067"},{"speaker":"山元委員","kind":"質問・要望","question":"実際、本当に毎年件数が補助を受けている方が多いというのが現実だと思うんですけれども、区としてはこれから予算等いろいろ入ってくると思うんですが、どのような、目標は立てられないとおっしゃっておりましたけれども、実際これからどのように不妊治療に対して拡大していこうとか、何かそういう思いがあるんであれば、お聞かせいただきたいと思います。","respondent":"江部健康課長","answer":"これにつきましては、時期的に割と急に来たという部分がありますので、そのあたりの分析、年齢を含めた分析をしながら、次の段階での施策のあり方は考えていく必要があるというふうに認識しております。","voiceIndex":156,"id":"exchange-068"},{"speaker":"南委員","kind":"質問・要望","question":"５４ページの基金繰入金について伺いたいと思います。平成２４年度当初予算のプレス発表では、基金残高は５４３億円としてありましたけれども、今年度末は６５２億円になっていると、こういうふうに思います。この相差が１０９億円になっております。何で年度末になると基金残高がこんなに増えるのか、そのあたりをちょっと教えていただきたいと思います。","respondent":"本城企画財政課長","answer":"それで、なぜそういう理由が出てくるかですが、それにつきましては、今回積み立てにつきましては、基本的には財調で２８億円ほどの再調整の結果、財源が出てきたこと、それから区民税についても、１０億円強のものが出てきたこと、それを原資としまして。","voiceIndex":159,"id":"exchange-069"},{"speaker":"南委員","kind":"質問・要望","question":"それで、２８億円の中身について再調整をした形でということと、区民税が上がったと。それでもなおかつ足りない部分、区民との要求との関係で必要な部分をもっと当て込んでいくために、特定財源から充てるということもあると思いますけれども、基本的にどこの立場で予算を組むのかという、まずそこの区の考え方について教えていただきたいと思います。","respondent":"本城企画財政課長","answer":"ただ、今回補正予算も今度組んでおりますけども、実際今は見込みということで立てております。ただ、その後、５月末までが出納閉鎖ということで、最終的な整理をすることになります。","voiceIndex":161,"id":"exchange-070"},{"speaker":"南委員","kind":"質問","question":"一つ一つの削減をした、精査をした事務事業について見てみると、やっぱり区民生活の厳しいところにも幾つか、ここまで削るのかというふうに見られるところがあるわけです。したがって、この問題について質問をしているわけですけれども、区民生活の関係で、予算を組むときに、どういうふうにそのあたりも考慮して予算化しているのか、計上しているのかということもあわせて伺いたいと思います。","respondent":"本城企画財政課長","answer":"区民生活に対する保障を行政サービスでしているわけですが、それについては現在の区民生活とあわせて、将来にわたって区民生活を円滑に計画的に支えていくということで、これから将来にわたっていろんな需要が出てきたり、あるいは経済変動もありますが。","voiceIndex":163,"id":"exchange-071"},{"speaker":"南委員","kind":"質問・要望","question":"今、本当に長期にわたる不況の中で、セーフティーネットということで生活保護を受けておられるそういう方々の、法外援護ですから品川区の独自財源ということになると思うんですけれども、しかし、これがかなり厳しいところであって、なかなかその辺がやっぱりきちんと削減じゃなくて、支えていく、それこそ支えるべき部分であろうというふうに思っています。","respondent":"本城企画財政課長、柏原行財政改革担当課長","answer":"先ほどの財調の再算定の部分ですが、もう少し詳しくご説明しますと、当初財調の算定ということで、調整三税、いわゆる調整三税を見込みで算定することになります。その中で拡充しなければいけないものは拡充するといったところで、そういったバランスを捉えながらやっているものですので、一概に不必要なものはなくしていこうとかということではなく、そういった整理をしているといったところですし。","voiceIndex":165,"id":"exchange-072"},{"speaker":"南委員","kind":"質問・要望","question":"今、行財政改革担当課長のご答弁があったんですけども、私はそういうふうには見えません。もっとしっかりと区民の要求を対峙していただいて、検討していただきたいということをお願いしておきたいと思います。しかし、１７４億円も平成２２年度は余らせた、そういう状況をつくった、取り崩さなくても済んだ、そこのところは何だったのかということを聞きたかったんです。","respondent":"本城企画財政課長","answer":"繰り返しのご答弁になりますが、平成２４年度につきましても、取り崩さなくて済んだものについては、基本的に事業の進捗に応じて、そこまで取り崩さなくてよくなった分とか、あるいは国等のものについてプラスに来たもので、その反映です。","voiceIndex":168,"id":"exchange-073"},{"speaker":"南委員","kind":"質問・要望","question":"私はやっぱり区民生活や区民要望のそこの角度からしっかりと財政をつけて、必要な事業は確保していただく、このことを強くお願いして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":170,"id":"exchange-074"},{"speaker":"向委員","kind":"質問","question":"よろしくお願いします。私からは７２ページ、７３ページで、乳がん検診と妊婦健康診査、不妊治療助成金なんですが、順番が逆になるかもしれませんが、まず乳がん検診のところからお尋ねします。補正予算で、３,８９４万円ほど更正減額になっていますが、この主な理由をお聞きしたいと思います。","respondent":"江部健康課長","answer":"マンモグラフィをずっとやられていたということで、超音波になじみがなかったということだと思いますが、その２点が大きくございまして、合計で４,２００件の見込みとの差がありました。","voiceIndex":172,"id":"exchange-075"},{"speaker":"向委員","kind":"質問・要望","question":"わかりました。周囲の声を聞いていても、そういう声があったので、そうかなと思うんですが。今年度対象者数、平成２４年の当初予算のときは、１万４,５００件、検診数があったと思うんですよね。実際の受診率は、結局今年度見込みになると思うんですけど、３０％は超したんでしょうか。","respondent":"江部健康課長","answer":"受診率につきましては、昨年１９.４％でございまして９,６０６件、今年度は１万件を超えるだろうと見込んでおりますので、若干上向きをする予定でおりますが、３０％というのはちょっと至らないという認識をしております。","voiceIndex":174,"id":"exchange-076"},{"speaker":"向委員","kind":"質問","question":"わかりました。仕事の時間が遅かったりすると。やっぱり、電子申請とか、そういうことで予約ができると、仕事で時間がまちまちな方も利用者からすると、本当にありがたい仕組みだなと思うんですけど、今乳がん検診を受診できる病院というのは、日曜日に受診可能な病院というのはあるんでしょうか。","respondent":"江部健康課長","answer":"乳がん検診の検診実施医療機関数についてですけれども、現在１３医療機関があります。これにつきましては、基本的には各診療機関の受診時間でのお願いということで、今のところこちらから特別なお願いをしてはおりません。","voiceIndex":176,"id":"exchange-077"},{"speaker":"向委員","kind":"質問・要望","question":"申請をするときに、一般不妊治療の申請の中にチェックする欄、一般不妊治療が終了したからというところにチェックする欄があって、ここに妊娠に至ったから終了したというのと、特定不妊治療にステップアップをしたからとチェックするところがあると思うんですけど、特定不妊治療に進んでチェックを書いた方と、年齢の関係というのは何か傾向というのはあるのかなというのをちょっとお尋ねしたいんですが。","respondent":"江部健康課長","answer":"これについて、どういう場合だとか、年齢とか、そういったことは把握してございません。","voiceIndex":178,"id":"exchange-078"},{"speaker":"渡部委員","kind":"質問・要望","question":"１３５ページなんですけど、特定健康診査のことで少し伺いたいと思います。平成２４年のこの補正予算で、大分マイナスで減額をされております。３８％、対象者は約４０歳から７４歳の国保対象者が６万５,０００人と考えて、おおむね３８％ですから、２万５,０００人ぐらいなのかな。実は予算書を見てみますと、当初の予算は３万３,０００人で立てているんですね。そこまでとりあえず教えてください。","respondent":"榎本高齢者医療担当課長","answer":"その間、数パーセントずつ受診率が増え、特別区の中では４年間で最も上昇率が高かったんですけれども、ずっと取り組みの結果は一定程度出ておりまして、今年度は地域との共同、企業との共同というところも力を入れてまいります。","voiceIndex":181,"id":"exchange-079"},{"speaker":"渡部委員","kind":"質問","question":"健診票を持っていかなければ、数字には反映しないんですよね。一つ、ちょっと、すみません、不勉強で教えてもらうだけでいいんですけれども、たしか基本健診のときというのは、何月生まれの人は何月に送るよと、たしかタイムラグがあったと思うんですけど、あれは今でもあるんですか。みんな健診票というのは同時に６万何千人分送られて、５月から１２月まで受けられる仕組みでしたか。","respondent":"榎本高齢者医療担当課長","answer":"１点目、行かなかった方に対してのペナルティーというのは、なかなかちょっと難しいかなと思っているところです。","voiceIndex":183,"id":"exchange-080"},{"speaker":"渡部委員","kind":"質問","question":"一番はやっぱり受けやすさがどうなるかというところだと思うんですね。４分ありますので、もう一つ質問します。全体的な質問をしたいと思います。職員給与費です。もう時間がないので内容はいいです。これというのは、決算になるとだーっと当然予算のときと違う金額が出てくるであろうものだと思うんですが、なぜ出てくる所管の部分と出てこない所管の部分があるのか、ちょっと教えていただけますか。","respondent":"堀越人事課長","answer":"その中でこのような形で出していまして、その差について、一定の今までの実績等を含めた形で、このような形で補正をお願いしているところでございまして、この後のいろいろな例えば超過勤務の実績の見込みですとか、そういったものも見込みに入れながら。","voiceIndex":185,"id":"exchange-081"},{"speaker":"渡部委員","kind":"質問","question":"平成２５年の３月で大体この部署で何人はやめるよ。それ以上に普通退職といいましょうか、そういうのが多ければまたいろいろしていかなければならないと思うんですけれども、意外と５０億円全体の予算の中で、あっ、保育です。７０何ページだったでしょうかね。これというのは、平成２３年の１０月の段階でわかっていることなんじゃないのかなという気がしたんですが、その辺を教えてください。","respondent":"堀越人事課長","answer":"当初予算ぎりぎりの編成をする作業と並行して決まってきますので、ある程度１０月１日という形で数字を見込んでいく必要があるです。それから、給与改定等もありますので、どうしても補正対応という形にならざるを得ないというふうに認識しております。","voiceIndex":187,"id":"exchange-082"},{"speaker":"浅野委員","kind":"質問","question":"最初にきゅりあんの更正減額、計画修繕費が特にでありますけれども、平成２３年度の補正で約１.４億円の更正減額をやったかと思います。空調工事の中止とか、あと契約落差というふうに聞いておりますが、今年度２,０００万円強の４割に当たりますけれども、８５０万円ほど減額になっていますけれども、この理由について改めてお伺いします。","respondent":"安藤文化スポーツ振興課長","answer":"それの契約の落差です。当初見積もった額は２,０７７万円でございました。予算はそうです。しかし、決算の見込みで１,２２２万５,０００円ということになってあります。","voiceIndex":190,"id":"exchange-083"},{"speaker":"浅野委員","kind":"質問","question":"契約落差ということで、引き続き平成２４年度もこういう形になったんですけれども、平成２５年度も約４,０００万円ぐらいの予算を立てているわけですけれども、ここでまた大きく契約落差なんてないようにしてもらいたいなと、そのように考えるものですけれども、この契約落差というのは、そもそもどういう形で出るのか。","respondent":"小林施設整備課長","answer":"今回の落差額ですが、１９カ所の和式の大便器、これを洋式の大便器にかえました。設備の業者で、例えばメーカーと直の代理店とか、そういうところの業者がいますと、大便器の１個当たりの入ってくる金額がかなり減額されて入ってくる部分があります。","voiceIndex":192,"id":"exchange-084"},{"speaker":"浅野委員","kind":"質問","question":"これだけの金額の差が出るということは、当初、平成２４年度計画していた事業で、あるかどうかは別として、落とされてしまうんでしょうかね。それが品川区で行われているかどうかはまた別途お伺いしたいんですけれども、当初予算で、やはり精度を上げていくということは、これから区としてもしっかりとやっていかなければならないことだと私は考えているんですが、これについての考え方を教えてください。","respondent":"小林施設整備課長","answer":"業者のほうも、今言いました代理店の業者と一般の工事業者といろいろな業者がいますので、一律に今言った落差の大きい、そういうのを見込んで低減を図って予算化すべきじゃないかというお話もありますけれども、一般の業者もいますので。","voiceIndex":194,"id":"exchange-085"},{"speaker":"浅野委員","kind":"質問","question":"当初予算に盛り込めなかったようなものが実際発生をしているのかどうかということについて教えてください。","respondent":"小林施設整備課長","answer":"基本的にはございません。ただ、見えない、例えば天井改修だとか、そういうところで、天井をはがして中が見えなかったところに障害があるとか、そういうところでプラスということはありますけれども、基本的にはないということで考えております。","voiceIndex":196,"id":"exchange-086"},{"speaker":"浅野委員","kind":"質問","question":"全体的な話としてお伺いしたかったんですけれども、もし企画財政課長等でそういう考え方があるのであれば、この後教えてください。時間もないので次にいきます。","respondent":"久保田地域活動課長","answer":"光林荘につきましては、部屋タイプが二つありますけれども、それをあわせた稼働率ですが、６.１％、定員に対します利用率は４.８％ということでございまして、現在のところ、平成２４年度につきましては、このような数値で推移していくものと見込んでいるところです。","voiceIndex":198,"id":"exchange-087"},{"speaker":"浅野委員","kind":"質問","question":"こちらのほうにつきましては、運営業者があるということと、区のほうも宿泊費の助成をしているということで、まず運営業者のほうの採算分岐点というんでしょうか、どのぐらいの方が宿泊をすると、利用されるということで、どのぐらいの分岐点を考えられているのか、そしてまた、区のほうにも採算分岐点というのがあるのであれば教えていただければと思います。","respondent":"久保田地域活動課長","answer":"私ども区のほうとしましては、平成２２年度の実績、区民利用が大体１万人ぐらいあったというふうに見込んでございまして、それの２０％増しで今回予算立てをしたところですけども、見込みとしては、そこまでも行かなかったと。そこまでは乖離があるです。","voiceIndex":202,"id":"exchange-088"},{"speaker":"浅野委員","kind":"質問・要望","question":"ただ、業者のほうがこれでは成り立たないよということで、さよならということにならないように、これはしっかりと区のほうからもフォローしていただいて、どのようにしたら区民の方にもっと利用していただける、そういう保養所になるのかどうか、これも検討していってもらいたいと、このように要望しておきますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":204,"id":"exchange-089"},{"speaker":"高橋委員","kind":"質問・要望","question":"よろしくお願いします。そこで、積極的な財政運営という観点でお尋ねしたいと思います。事業費は３５万円という少額なものから、多くて７,０００万円と非常に多岐にわたっています。私は積極的な財政運営という観点からすると、この経済効果は区内の事業者の方にかなり反映されていると思うんですが、そのような区のほうの事業者に反映されているかということについてのお考えはいかがでしょうか。","respondent":"本城企画財政課長、平澤経理課長、松代防災まちづくり事業部長","answer":"それらを含めて区内の事業者に早期に仕事が行くことによって、経済的な効果を生んでいると考えているところです。それぞれの工事につきまして、完了の時期というのが決まってありますので、基本的には完了後支払いになるわけですが。一つの事例ですけれども、道路工事の例で申し上げますと、２０年ほど前は４月に新年度予算が決まって設計をし、起工し、契約をし。","voiceIndex":206,"id":"exchange-090"},{"speaker":"高橋委員","kind":"質問・要望","question":"つまり、債務負担行為の３８件というのを、ここで３８件にしているというのは、もっと多くてもいいという気もするし、どの基準で３８件、昨年度は３５件で５億５,０００万円、ほぼ似たような金額なんですけれども、そのあたりの基準というのがもしあれば教えていただきたいんですけど。","respondent":"本城企画財政課長","answer":"緊急経済対策の一環としてやっておりますので、区が発注する事業について予算編成の過程で、どのような事業があるか、こちらの企画財政課のほうも把握する中で、できる限り早期発注が可能なものについてやっていくと、そのような姿勢でやった結果。","voiceIndex":210,"id":"exchange-091"},{"speaker":"高橋委員","kind":"質問","question":"そうすると、予算には今お話が出てきたんですが、単年度の会計、独立しておりますので、その例外として債務負担行為というのがあります。毎年常連として、今ちょっと緊急経済というお話もあったんですが、路面改良とか側溝改良、雨水流出抑制などの事業は毎年最終補正に債務負担行為として出てきています。ですから、それをもうちょっと恒久対策の一環として考えていくお考えはないでしょうか。","respondent":"本城企画財政課長","answer":"今の位置づけとしては緊急経済対策としてやっておりますけども、今後年度当初から早期に発注するという意味はプラスの意味がありますので、今後どのあたりまでやっていくか、課題として検討していきたいと考えているところです。","voiceIndex":212,"id":"exchange-092"},{"speaker":"高橋委員","kind":"質問","question":"３５万円という非常に小さな事業もあって、区内の事業者の方に大変行き渡る、そういった仕事がたくさんあると思います。ですから、どうしても地方の財政は単年度の原則があるんですけれども、柔軟性に欠けているところを、やはり今お話がずっと出ている債務負担行為で、行政需要に対する品川区の区政の工夫の一つとして、私は前向きに捉えていって、ぜひどんどん進めていってもらいたいと思います。","respondent":"本城企画財政課長","answer":"そういう意味で、委員ご指摘のとおり予算の単年度主義という枠を越える中で、債務負担行為等のそういう財政的な技術もきちんと使いながら考えていきたいと考えているところです。","voiceIndex":214,"id":"exchange-093"},{"speaker":"高橋委員","kind":"質問","question":"次の義務教育施設整備基金積立金追加分についてお尋ねします。基金についてはいろいろ他の委員からご指摘があったんですが、ここでは義務教育施設整備基金積立金追加分についてお尋ねします。一般財源として繰り越して、平成２５年度の繰り入れを減額しておくという方法もあるんですが、あえて基金で出し入れをしているというのは、何か特別の意味があるんでしょうか。","respondent":"本城企画財政課長","answer":"一つは基金に積み立てるという形をとりまして計画的に施設を整備するということで、単年度で全部執行ということではなくて、いろんな財源を基金という形で置くことによって、計画的な整備ができるという意味で基金を活用すると考えております。","voiceIndex":216,"id":"exchange-094"},{"speaker":"高橋委員","kind":"質問","question":"使っちゃうとかではなくて、一般財源として繰り越せばいいという方法もあるんではないでしょうかということなんですね。そうすれば、平成２５年度の繰り入れを減らせますよね。それで、あえて、だから基金に出し入れするというのは、今の側面もあるとは思うんですが、もう少しお財布を使って出し入れをする、いわゆる予算編成上のいろんな状況もあるのかもしれませんが、何か特別な意味があるんでしょうか。","respondent":"本城企画財政課長","answer":"ちょっと繰り返しになってしまうところがあるかもしれませんが、年度末に財源の見通しを立てまして、その段階で財源余力等が確認できたものについては、基本的に将来に備えた財源として基金に積み立てるということで対応しているものです。","voiceIndex":218,"id":"exchange-095"},{"speaker":"高橋委員","kind":"質問・要望","question":"年度の中である程度の資金というか、そういった余裕が出たのを補正で処理したり、さまざまな予算を計上していくという形ですか。すみません、この点について、また後日別なときにお尋ねしたいと思います。御殿山小学校の改築だけではなく、さまざまな予定というか、お考えがあるんではないかと思いますので、よろしくお願いします。","respondent":"齋藤庶務課長","answer":"一貫校の６校構想は終了をいたしました。改築校につきましても、現段階では計画はございませんので、御殿山小学校が終了すれば、当面の改築の予定はございません。","voiceIndex":222,"id":"exchange-096"},{"speaker":"高橋委員","kind":"質問・要望","question":"そうすると、一貫校では大変児童・生徒が過ごしやすい校舎になり、それから耐震化も各小中学校で進んでいると。このような教育環境に差が出ていると。校舎の老朽化を改善していく。今改築の話が出ましたが、進めていく見込みといいますか、今後の建築計画、当面ないというお話だったんですが、こういった状況を解消するために、この基金をぜひ活用していただきたいと思うんですが、いかがでしょうか。","respondent":"齋藤庶務課長","answer":"この基金、平成２５年度はちょっと款が違いますけども、来年は校舎等の整備３億円、校庭整備でも１億２,０００万円ほど活用しますので、この基金を活用しながら、学校環境、施設整備については取り組んでまいります。","voiceIndex":224,"id":"exchange-097"},{"speaker":"井上委員","kind":"質問","question":"私は６７ページの民生費、社会福祉費の地域密着型サービス施設整備助成と、６９ページの児童福祉費の認証保育所運営費等助成、それから１０２ページの繰越明許費について、それとあと６７ページの重症心身障害者通所施設についてお伺いをいたします。","respondent":"本城企画財政課長","answer":"今のお尋ねですが、基本的には今回のこの国のほうの交付金が出たことによって、当初平成２５年度で計画していた事業をこの交付金を有効活用するという意味で、平成２４年度に前倒しして補正を組んだと、そういう経緯です。","voiceIndex":227,"id":"exchange-098"},{"speaker":"井上委員","kind":"質問","question":"繰越明許費としてそういうことが、本来あったものが事情によって繰り越すというものを、補助金があってそういうこと、有効利用するという意味合いはわかりますけれども、そういうものを通常行うものなんでしょうか。","respondent":"本城企画財政課長","answer":"今回、国のほうとの関係で言えば、平成２４年度で受け入れることによって財源を確保できるという経緯がございましたが、あと繰越明許一般につきましても、その他の今回も繰越明許は大体個別事情で調整になかなか時間がかかったとか。","voiceIndex":229,"id":"exchange-099"},{"speaker":"井上委員","kind":"質問","question":"平成２５年度予定で緊急的に非常に重要だということでこれを使っていくんだというふうに理解したいかなというふうに思います。使われなかったということに対してどういうふうな理由があるのかということで、受け入れのスタッフ側の問題なのか、送迎がないというところの課題なのか、その辺を行政としてはどのように捉えているんでしょうか。","respondent":"永尾障害者福祉課長","answer":"未就学のレスパイト事業ですけれども、先ほどもちょっと申し上げたとおり、理由としてはご希望もございましたし、ご説明をしたときの反応もよかったんですけれども、やっぱり具体的にそういう状況になったときに、お子さんの具合が悪くなったとか、入院したとか。","voiceIndex":231,"id":"exchange-100"},{"speaker":"井上委員","kind":"質問・要望","question":"区単独事業ということなので、法内ではないのでなかなか区としても積極的に事業を遂行しようというところにちょっと力が足りないのかなというふうに残念に思うんですが、せっかく小学生就学後の方々の対応もしてくださるということなので、枠があっても利用ができないということでは大変区単独でつくっていただいた施策なので、そこは何とかしていただきたいというふうに思う中で。","respondent":"永尾障害者福祉課長","answer":"ただ、繰り返しになりますけれども、実際の利用の状況が今お子さんの体調の具合等もありますので、今後は小学生に広げまして、小学生であれば、多分こちらのほうの予想では、夏休みだとか冬休みとか、そういう利用もあるんじゃないかというふうに思っていますので。","voiceIndex":233,"id":"exchange-101"},{"speaker":"井上委員","kind":"質問・要望","question":"６７ページの地域密着型サービス施設整備費と認証保育所運営費助成が減額ということなので、どこの計画がそのような状況になったのかということと、それがどういう理由から、そしてまた、その計画は新年度にも継続されていくものなのか、廃案になってしまったものなのか教えてください。","respondent":"原高齢者福祉課長、伊崎待機児童対策担当課長","answer":"地域密着型の残の中身ですけれども、こちらのほうは、地域密着サービスということで、グループホームあるいは小規模多機能型居宅介護、こういったものを想定しておりまして、ここは区立ではなく、あるいは法人あるいは民間という。かわりにということではないんですが、認可保育園の開設が１園増ということで、待機児童解消としては１園減になった分は対応できていると考えております。","voiceIndex":235,"id":"exchange-102"},{"speaker":"井上委員","kind":"質問","question":"当初そういう芽があって、予算化をされてということだったと思うんですけれども、これから新年度予算のほうでは、子ども子育て支援事業計画を策定しなければならないということになっていて、待機児対策としても施設の問題なのか、総合的な取り組みを含めて検討していかれることだというふうに思うんですが、そこで横浜市が２００９年にプロジェクトを立ち上げて、２０１０年から待機児対策を開始して。","respondent":"伊崎待機児童対策担当課長","answer":"横浜市とは人口規模がかなり違いますので、同じ比較は当然できないと考えております。対策の進め方につきましては、それぞれの自治体の考え方ですので、あくまでも参考としながら、品川区なりのものをつくっていきたいと考えております。","voiceIndex":238,"id":"exchange-103"},{"speaker":"井上委員","kind":"質問・要望","question":"先ほどの、ちょっと時間があるので、乳がん検診のところでお伺いをしたいと思うんですけれども、先ほど減額に対しての答弁が向委員のことに対してありましたけれども、７１歳以上の方と４０歳未満の方に検査方法を変更したということで、これについて効果とか、１年目ですので、そのことについての評価というのはまだだというふうに思いますけれども、これについて新年度にどのような反省というか。","respondent":"江部健康課長","answer":"これはＰＲを含めて受診施設が少ないという部分はありますが、どういう効果で視触診から変えたのかという部分のＰＲをやはりしていく必要があるんだろうということは認識しております。","voiceIndex":240,"id":"exchange-104"},{"speaker":"井上委員","kind":"質問・要望","question":"この検査方法の改正というのは、品川区だけではなくて、東京都なのか、全国的なものなのか、その辺をちょっと確認させていただきたいと思います。","respondent":"江部健康課長","answer":"品川区につきましては、昭和５０年から視触診というのを広くずっとやってきていたという経緯がある中で、この基本計画が出たと。そこで、これについて精度管理、検査の効率性とか有効性につきまして検討会が行われて、その中で時間はかかりましたけれども、今回変更になったです。","voiceIndex":242,"id":"exchange-105"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"８５ページの都市防災不燃化促進事業、特定整備路線の沿道不燃化促進調査委託についてお聞かせいただきたいと思います。この特定整備路線というのはどこの路線をいうのかを教えてください。二つ目に、なぜ平成２５年度当初予算ではなくて今回の補正なのか、この点についてもお聞かせください。そして三つ目に、具体的にどんな調査を行うのか、この３点をお願いします。","respondent":"品川防災整備担当課長","answer":"特定整備路線ですが、木密不燃化１０年プロジェクトにおける密集、主に密集した地区、ここに通ります都市計画道路に対して特定整備路線としまして、道路の事業を行っていくという道路になっております。","voiceIndex":245,"id":"exchange-106"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"路線名を言われなかったんですけども、９月の補正予算で、沿道まちづくり調査検討と用途地域・容積率の見直し検討経費というのが１,２６０万円出ていますけれども、これとの関係でどんな調査になるのかということと、それからこの９月補正では、２９号線と放射２号線だったんですが、今回の路線は２８号線も含んでということなのか、その点もお聞かせください。","respondent":"藤田都市計画課長","answer":"９月の補正で行っている調査の関係ですけれども、９月の補正で行いましたのは、周辺のまちづくりをいかに進めていくか、それを進めるためにはどんなまちづくりを進めていくべきかということで、例えば用途地域を見直すべきではないか。","voiceIndex":247,"id":"exchange-107"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"９月補正が組まれ今回補正が組まれ、また木密１０年プロジェクトの不燃化特区、これを申請するに当たってもまた調査委託ということも組まれていくのかなと思うんですけれども、そもそも２９号線、また放射２号線や２８号線は説明会そのものもされていないうちに、こういう形でどんどんこの道路を前提とした予算が組まれるということそのものがどうなのかなというふうに思っているわけですけど。","respondent":"藤田都市計画課長","answer":"それからまちづくりの検討をですけれども、説明会の中でも申し上げましたとおり、説明会そのものが補助２９号線等の説明であり、周辺のまちづくりについては。","voiceIndex":249,"id":"exchange-108"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私はこの丁寧な説明というのは、わずか質問の時間を３０分しかとらないという、たくさん手を挙げていても、もう時間ですからということで打ち切るような、これではとても丁寧な説明というふうには言えないと思います。そして、「区はもっと丁寧な説明をすべきだ」という方は、賛成の方も反対の方も含めて１００％がこういうふうに答えています。こういう声もありました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":251,"id":"exchange-109"},{"speaker":"金野委員","kind":"質問","question":"当初予算では、３,９５０万円というところで、今回補正で５００万円減額ですけれども、この数字の見方をまずお聞きしたいと思うんですね。放置自転車の保管料ですから、当初の見込みより減額されるということは、単純に放置自転車が少なくなったと見るのか、それとも保管されている場所に所有者の方がとりにこられなかったケースだったのか、そこら辺の数字の捉え方というか、見方をまずお願いいたします。","respondent":"谷口交通安全担当課長","answer":"保管所における数が減っているということは、撤去活動が功を奏しているということで、放置が減っているという状況です。それで減っているです。","voiceIndex":254,"id":"exchange-110"},{"speaker":"金野委員","kind":"質問","question":"そこで、区民の生活の環境が阻害されると認められると、この阻害される幅、何というんでしょうかね、認められる何でもかんでもというような、何でもかんでもという表現じゃないですね。いわゆる阻害されるんですから、歩道の場所が狭くなったりというある程度のイメージはつくんですが、どれぐらいのいわゆる程度ですね、これはどれぐらいまで認められるんでしょうか。その点をお願いします。","respondent":"谷口交通安全担当課長","answer":"放置禁止区域外につきましては、警告をいたしまして、１週間程度の状況を見まして、まだ放置されていれば撤去するという手続をとっているところです。一般に歩くのに邪魔ということであれば、撤去に該当すると考えております。","voiceIndex":256,"id":"exchange-111"},{"speaker":"金野委員","kind":"確認","question":"取り組みの対策というか、そのように区域外としても阻害されるときには指導して１週間後、あるいはそのときに撤去していくというような取り組みをされているということを確認しました。ここはどのように、他区の管理区域ですけれども、区としてはどのようにされていこうとお考えでしょうか。","respondent":"谷口交通安全担当課長","answer":"大田区のほうにお願いをしまして、シルバー人材センターの方たちにお願いしまして整理誘導、または自転車駐車場の誘導等実施をしています。","voiceIndex":258,"id":"exchange-112"},{"speaker":"金野委員","kind":"質問","question":"そのようにしてくださっているというお話はわかりました。それで、大森駅の周辺のお店屋さんでは、大変に困っていらっしゃる。ですので、どうかここを大田区と協議をされているということであれば、やはりそれぞれの区のそういう場所には、やっぱり自分の区の担当として、意識としてやはりそこはしていかなければいけないんじゃないかなと、このように思いますけれども、もう一度ご答弁をお願いします。","respondent":"谷口交通安全担当課長","answer":"そこで、当区としましても、放置禁止区域のかかっていない場所について、前向きに検討してまいりたいということで考えております。は大田区と協議を引き続き進めまして、１台でも放置自転車を減らすということで積極的に取り組んでまいりたいと考えております。","voiceIndex":260,"id":"exchange-113"},{"speaker":"金野委員","kind":"確認","question":"法外援護事業が減額されたものではないということなんですね。そうですか、わかりました。そうすると、その補助金、ちょっと聞き取れなかったんですが、そこら辺のところが改正になった、それに伴って更正減額というところで、ごめんなさい、確認です。もう一度お願いします。","respondent":"竹田生活福祉課長","answer":"失礼しました。こちらの東京都の補助金の科目が変更になったものです。被保護者自立促進事業補助金でしたが、本年度から地域福祉包括補助金の一部に移行することになったため、財源更正のため、２４２万５,０００円補正したものです。","voiceIndex":264,"id":"exchange-114"},{"speaker":"松澤委員","kind":"質問・要望","question":"３点お聞きしたいと思います。１点目の７９ページの補助１６３号線整備ですけれども、東急大井町線交差部基本設計委託、減額２,２８０万円、事業認可取得業務等委託、減額１,１８０万円、これは午前中の説明のときに取り消しというような言葉を使われたというふうに思うんですが、どういうことなのか詳しく説明をしていただきたいと思います。","respondent":"稲田道路課長","answer":"そこで考えられますのが、私ども都市計画道路１６３号線の部分と耐震化事業ですね、これがどうしても複合工事となってしまうというところがございまして、東急電鉄の耐震化事業を注視しながら、平成２５年度の初め部分に予定していました事業認可取得なんですけれども。","voiceIndex":267,"id":"exchange-115"},{"speaker":"松澤委員","kind":"質問","question":"そうすると、この工事が１年、２年また遅れるということでしょうか。相当交通量があるわけですから、ここの工事が完成しないと２６号線が完成しても、大変なここがネックになってしまうということで、これは前々から言われていることで、こんなことが今年度予算を組んでいながら、また東急電鉄との話し合いで平成２５年度、平成２６年度と２年ずれるわけですから、こんなことではいつ完成するかわからない。","respondent":"稲田道路課長","answer":"そういう意味におきましては、完成年度、現在のところは平成３２年度程度を予定しておりますが、現在の設計の仕方、まず非常に土木的に言いまして、けたを、委員ご存じかも知れませんが、けたを架け替える非常に大きな工事でございまして。","voiceIndex":269,"id":"exchange-116"},{"speaker":"松澤委員","kind":"質問","question":"そうすると、近隣の立ち退き問題についても、やはりそれと同じように一、二年はまた全体的に遅れてくるよということでいいんでしょうか、そこだけ１点ちょっとお伺いしたいと思います。","respondent":"稲田道路課長、松代防災まちづくり事業部長","answer":"東急電鉄のガード下の動きにつきましては、東急電鉄のほうで今進めているですので、先ほどもちょっと申し上げましたが、私どもはその動きをよく注視しながら、今後もやっていきたいです。そういったことで、今回大井町線は耐震化を鉄道事業者としては最優先でやりたいというようなことで、若干私どもの工程が少し遅れざるを得なくなったですけれども、もう協定もめどがたち、詳細設計に入っておりますので。","voiceIndex":271,"id":"exchange-117"},{"speaker":"松澤委員","kind":"質問","question":"わかりました、これぐらいにしておきます。次、８３ページ、国文学研究資料館の跡地の工事の、これは三井文庫の補修工事３６７万４,０００円の減額ですけど、これは予算が２,５００万円でした。この減額というのは、契約落差ということでよろしいんでしょうか。その点お聞きしたいと思います。","respondent":"多並公園課長","answer":"三井文庫の予算との関係ですが、この内容は契約落差です。","voiceIndex":274,"id":"exchange-118"},{"speaker":"松澤委員","kind":"質問","question":"この三井文庫、私はちょっと勘違いしていたんですね。写真を見て、これははりだなと思ったのは書庫なんですね。そうすると、このかけたお金というのは一体どこを工事したのか、よく見ると基礎部分かもしれないけど、よくわからなかったので、工事内容をちょっと教えてください。","respondent":"多並公園課長","answer":"この建物につきましては、もともと委員の今のご案内のとおり大正時代に建てたものであり、関東大震災、また太平洋戦争の空襲にも耐えてきたという貴重な建物であり、構造的には今見た目はしっかりしたものに見えますが、平成２０年に耐震の調査を行った結果。","voiceIndex":276,"id":"exchange-119"},{"speaker":"松澤委員","kind":"質問","question":"大変に中を見て、これはすごいなというふうに感じたんですけど、あれは防災資機材倉庫ということで、いろんな乾パンなんかを入れるんでしょうか。そうすると、一旦入れてしまうと、あそこは公開されることがないのかな、こんないい建物なのに、年に１回ぐらい中を見せたいなという気がするんだけど、その辺、どうなんでしょう。","respondent":"多並公園課長","answer":"ただ、耐震性の問題等がありますので、なかなか日常では公開は難しいということで閉鎖していますけれども、今後の見ていただけることにつきましては、いろいろな観点から検討させていただきまして、考えさせていただきたいと考えています。","voiceIndex":278,"id":"exchange-120"},{"speaker":"松澤委員","kind":"質問","question":"最後の問題にいきます。話を聞くところによると、入札もなかなか不調でできないんですよなんていうお話も伺っているんですけれども、何でこれが延びたのか、実際に事故によって延びたのか、その辺のいきさつと今後の予定、しっかりとした予定をお聞きしたいと思います。","respondent":"小林施設整備課長","answer":"事故ではなくて、ちょっと外構工事の不調の関係で延びました。今後の予定は、平成２５年度３月をもって竣工するように外構工事を今発注している段階です。失礼いたしました。来年の平成２６年の３月です。失礼いたしました。","voiceIndex":280,"id":"exchange-121"},{"speaker":"松澤委員","kind":"質問・要望","question":"うっかり、よくわかりましたと言うところでした。１年先ということで、学校が開校してからの外構工事ということで、やはり子どもたちが、小中一貫校でたくさんの子どもたちが通う中での工事ですから、本当に気をつけていただきたいというふうに思います。その辺の決意を聞いて終わりたいと思います。","respondent":"松代防災まちづくり事業部長","answer":"どうしても道路整備が最後になってしまいますが、既に新入生、今度入ってこられます。そういった意味では、周辺の工事をしながら生徒の皆さん、また区民の皆さんが安全に通行、通学できるように万全の配置をしながら工事を進めたいと、このように思っているところです。","voiceIndex":282,"id":"exchange-122"},{"speaker":"西本委員","kind":"質問","question":"私からは９ページ、補正の経過全般にわたっての質問、それから１００ページから１０３ページにあります繰越明許費、それから債務負担行為補正について、それから７１ページの就学前乳幼児教育事業更正減額、この中の幼保一体施設運営費が減額になっております、それについて、７７ページの被災者雇用助成事業について、順不同ですけれども、お聞きしたいと思います。二つ一緒に。","respondent":"立川保育課長、福島ものづくり・経営支援課長","answer":"就学前乳幼児教育事業更正減額ですが、これは幼保一体施設における保育士の人材派遣の配置見込みの減による減額です。会社雇用助成事業について説明します。品川区内に本社事業所があります中小企業が被災者を雇いますと、国、ハローワークでの被災者雇用開発助成金というのが支給されます。","voiceIndex":285,"id":"exchange-123"},{"speaker":"西本委員","kind":"質問・要望","question":"幼保一体施設の件ですが、人材派遣の人数ですか、これが少なくなったという、これはどういう意味なのかということと、それから被災者雇用助成事業ですけれども、実際品川区内に被災者がどれだけの方がいらっしゃって、雇用が必要とされている方はこのぐらいでというようなことがもしもわかっていましたら教えていただきたいんですが、それに対して今後。","respondent":"立川保育課長、福島ものづくり・経営支援課長","answer":"中身ですが、人材派遣の活用としましては、病欠であるとか産休・育休代替であるとか、その辺で人材派遣の活用を図っているところですが、それが実際には見込みが少なかったです。国が終われば終わるのかですが、やはり国の事業にこちらが２分の１の上乗せ助成をするという形態ですし、また私どものほうで雇用形態を全て確認していくことは大変難しいと思いますので。","voiceIndex":288,"id":"exchange-124"},{"speaker":"西本委員","kind":"質問","question":"被災者については流れがわかりました。すみません。それで次に、繰越明許費についてですが、これを見ますと、１００ページからの理由ですね、説明のところ、完了が見込めないというのがほとんどなんですよね。これはなぜこういう状況になってしまうのか。これはいつまで続くのかについてはどういう考えを持っているんでしょうか。","respondent":"本城企画財政課長","answer":"繰越明許費ですが、概括的にはそれぞれの事情で年度内に完了が見込められないです。それで、それぞれの個々の状況によって翌年度に予算が回っているです。","voiceIndex":291,"id":"exchange-125"},{"speaker":"西本委員","kind":"質問","question":"ちょっとそれではよくわからないと思うんですね。年内の完了が見込めない、わかります。年内に見込めないから次の年に繰り越すというのはわかりますが、このままでいいんですかということです。いつまで続くんですか。その見通しとかはどういうふうに考えたらいいんですかということです。","respondent":"本城企画財政課長","answer":"基本的には繰越明許費、一つは国の地域の元気臨時交付金の関係、そういう意味のものが一つです。もう一つについては、それぞれの事情で年度内に見込めないですが、基本的には平成２５年度に持ち越されるということで、平成２５年度内の対応が基本です。","voiceIndex":293,"id":"exchange-126"},{"speaker":"西本委員","kind":"質問","question":"いろんな事情がわからないではないんですが、外部要因のものが入っているのか、それとも平成２５年度の予算書を見ても、ここはリンクしていないんですよね。それはどのように理解したらよろしいんでしょうか。","respondent":"本城企画財政課長","answer":"予算上の取り扱いといたしましては、今回の繰越明許費ということで、予算上は完結することになりまして、その結果については決算にのってくるということで、ただ繰越明許費で、その事情によって例外的になっているものですが、執行上は極力早期にできるようにということで。","voiceIndex":295,"id":"exchange-127"},{"speaker":"西本委員","kind":"質問","question":"決算書に出てくるという理解ですか。個々によって違うのかもしれないんですけれども、ここに繰越明許費というふうに出ているわけですから、次年度、もしかしたら次の次かもしれないという形になるので、これをどういうふうに組み立てていくのか、この執行をどういうふうな形で見えているのかというと、見えないんですよね。だから、その見通しをどういうふうにとっているのか。","respondent":"本城企画財政課長","answer":"全体につきましては、予算、決算上の取り扱いについては、平成２５年度の決算に出てくるということで、議会のほうでもご説明するところです。","voiceIndex":297,"id":"exchange-128"},{"speaker":"西本委員","kind":"質問・要望","question":"これは要望になりますけれども、いろんな事情で遅れたりというのはわかります。理解してはおりますけれども、しかしそれは透明性があるようにしていただきたいと思うんです。債務負担の相手方は未定となっているんですが、これの処理はどうされるのか、これも平成２５年度の予算書に出てくるものなのか、この仕組みについて教えてください。","respondent":"本城企画財政課長","answer":"債務負担行為につきましては、平成２４年度があくまでも債務負担行為ということなので、それは平成２５年度に歳入・歳出予算のほうに必ずのってくるものです。","voiceIndex":299,"id":"exchange-129"},{"speaker":"西本委員","kind":"確認","question":"そうすると、この項目ごとにあるという理解でよろしいですか、そこだけ確認します。","respondent":"本城企画財政課長","answer":"そのとおりです。","voiceIndex":301,"id":"exchange-130"},{"speaker":"西本委員","kind":"質問","question":"わかりました。それで、ここの内容を見ると、金額的に小さいものから大きいものまでいろいろあるんですけれども、この平成２４年の補正の中で見ますと、児童センター等、それから文化センター等の修理が多いんですね。それとあわせて全体改築になるのかも含めての計画等々については考えられていないのか、いかがでしょうか。","respondent":"本城企画財政課長","answer":"修繕全般として言えば、いろんなものがありますが、この緊急経済対策として位置づけているこれらの項目につきましては、比較的小規模な工事について区内の事業者に早期に発注できると、そういう趣旨で。","voiceIndex":303,"id":"exchange-131"},{"speaker":"西本委員","kind":"質問","question":"緊急対策という意味では、なるべく細かいところを出していきましょうと、それはわからないわけではないんですね。しかしながら、こうやってざっと一覧を見ていると、かなり老朽化、ほとんどの目的が老朽化したというところの項目になっています。かなり古い施設もあるわけですね。それについての兼ね合いはどう考えられているでしょうか。","respondent":"本城企画財政課長","answer":"改修全般につきましては、総合的に計画的にできるようにきちんと進行管理して、一方で、緊急経済対策として比較的小さな規模なものを発注するということで、両者がきちんと二重投資にならないように総合的な調整をする中で。","voiceIndex":305,"id":"exchange-132"},{"speaker":"西本委員","kind":"質問・要望","question":"二重投資にならないようにということ、これは本当にお願いしたいところです。最後に、補正の経過なんですけれども、政権が変わりました。昨年はかなり混沌とした国政だったと思うんですけれども、それによって今回の補正に対しての影響があるものがあったのか、影響は全くなかったと見るべきなのか、あとは震災対策なんかも含めて考えると、補正に関して影響の度合いはいかがだったでしょうか。","respondent":"本城企画財政課長","answer":"それが新政権になって直後のことで、直接的な影響があって、区としても対応したものです。それが一番大きいと考えているところです。","voiceIndex":307,"id":"exchange-133"},{"speaker":"西本委員","kind":"質問・要望","question":"やはり、いろいろ影響があった上での内容が入っているかなというふうには思ってはいたんですけれども、これからも安定していただきたいというふうには思っておりますが、こういう去年のような急に政権が変わって予算立てが変わってしまうということがあった場合の区の対応、それからそういうときの庁内の中でのやりとり、いろんな流れが出てくるかと思うんですけれども。","respondent":"本城企画財政課長","answer":"急になった場合、リスク管理的なものですが、今回も通常の予算編成のスケジュールの中では、なかなか間に合いかねるような状況がありましたので、急遽国のほうで一般的な発表をされた後に、各区の中の所管を通じまして個別に情報をとることによって。","voiceIndex":309,"id":"exchange-134"},{"speaker":"西本委員","kind":"質問・要望","question":"では最後に、先ほども基金の話がございました。いろいろ今までの議論を聞いていますと、財調等々がいつ来るかとか、その時期によって基金に、何というんでしょうか、余ったお金ではないんですけれども、基金が自然とたまるシステムになっているのかなというふうに私は非常に感じたんですよね。ちょっと言い過ぎかもしれませんけれども。","respondent":"本城企画財政課長","answer":"それで、今回の中では特にプラスの財源が余力として出てきましたので、それらも含めてプラスで積んでいくという形で全体として積み増しができたです。","voiceIndex":311,"id":"exchange-135"},{"speaker":"阿部委員","kind":"質問","question":"私からはまず補正予算全体についてお伺いしたいと思っています。逆に言えば、１回、２回、３回の補正予算と、この４回目の補正予算、何か性格あるいは位置づけというものが、違いがあってのことなんだろうか。１、２、３回というのは、それぞれ委員会に分けて審議をして、４回目だけはこういう形、４回目というのは何か特別な意味があるということなんでしょうか。その考えについて伺います。","respondent":"本城企画財政課長","answer":"６月、９月等につきましては、そのときの新たな状況変化によって、新たな施策をやるとか、それらを含めてですが、最終補正の段階につきましては、それらとはちょっと位置づけが違って、全体の締めくくりということになりますので、年度の最後の決算見込み的なものも踏まえて。","voiceIndex":314,"id":"exchange-136"},{"speaker":"阿部委員","kind":"質問","question":"それを踏まえて、今補正であるけれども、決算的な位置づけがあるということで、平成２４年度の全体の予算とその執行について、どのように全体として見ていらっしゃるのか、そろそろその評価ができ得るころなのかなと思いまして、今、区としてはこの平成２４年度全体のお金の動きについてどう評価しているかというのを伺いたいと思います。","respondent":"本城企画財政課長","answer":"最終補正の位置づけの関係で、最後の締めくくりということで、そういう言い方でご説明させていただきましたが、ただ年度の締めくくりについては正式に決算特別委員会できちんと考え方を含めてご報告させていただければと考えています。","voiceIndex":317,"id":"exchange-137"},{"speaker":"阿部委員","kind":"質問","question":"できるだけお金をつくっていくと。あるいはフェンスを３５万円で直しました。品川区としてお金をきちんと大切に使っていくというのはいいんですけれども、もうちょっと細かいところで、特に区民あるいは子どもに接するところで、もう少し使いやすいお金の使い方というのもあるんじゃないかなと思うんですけど、それはどのように切り分けていらっしゃるんでしょうか。","respondent":"本城企画財政課長","answer":"細々としたいろんな修繕等を含めて、工事につきましては計画的にこれまでも実施しています。","voiceIndex":319,"id":"exchange-138"},{"speaker":"阿部委員","kind":"質問・要望","question":"普通のスタンダードで区民が使う施設というのも、きちんと修繕などをしていくということ、大切にお金を使うのはいいんですけれども、やっぱり区民、特に子どもたちが接する場所というのは、使うべきところはもっと速やかに、しかもそんなに大きなお金じゃないわけですから、ぜひため方だけではなく、使い方ということにもぜひ細かく気を配っていただきたいなと思います。ここはこれでおしまいにします。","respondent":"堀越人事課長","answer":"職員給与費、保育園の部分ですが、先ほどからご説明しています。見積もり時点の差ということが一つあります。","voiceIndex":321,"id":"exchange-139"},{"speaker":"阿部委員","kind":"質問","question":"若返ると給与が下がる。それが５年先なのか、１０年先なのか、１５年先なのか。年齢バランスを平準化させるためにも、補充に若い人ばかりではなくて、できれば経験者層ですとか、年齢バランスというものを考えて入れているのかどうか、それを教えていただければと思います。","respondent":"堀越人事課長","answer":"保育士の採用についての考え方ですが、定員の拡大ですとか、それからいろいろ新規の開設などを踏まえまして、的確に対応するため、計画的に退職者数に即しながら採用してきているところです。","voiceIndex":323,"id":"exchange-140"},{"speaker":"阿部委員","kind":"質問","question":"お話を伺っていると、やはり送迎がないと行けないということですとか、あるいはちょっと不安が大きいので体験会のようなこと、それは足つきで体験会のようなことをしてもらったら行けるんだけれども、そうでないとなかなか一歩がというような声も聞いたりします。そういったことについて、区としてはやっていくおつもりがあるか、人数とあわせて伺いたいと思います。以上３点お願いします。","respondent":"永尾障害者福祉課長、齋藤庶務課長、多並公園課長","answer":"それで、送迎についてのご要望等もあるかとは思いますけれども、実際にどのぐらいの時間数で、どのぐらいの時間帯をご利用したいのかとか。教育事業指定寄附金ですが、毎年この４年間、同じ方から寄付をいただいております。篤志をいただいております。そういう意味では、三井文庫が一番の名前の由来ではありますが、やはり一般の方が文庫というと本というのが一つのかかわりも考えられるかと思いますので。","voiceIndex":325,"id":"exchange-141"},{"speaker":"阿部委員","kind":"質問・要望","question":"文庫の森のほうもぜひこの国文学資料館があって、文庫の森という名前で本にかかわる土地の記憶というのを生かした形でぜひ公園というのを活用していただきたいと思います。せっかく寄付をいただいたんだったら、プラスアルファして教育の充実に使っていただければいいんじゃないかなと思うんですけれども、間違いだったら教えてください。時間が短いですけど、何かご説明があれば教えてください。","respondent":"本城企画財政課長","answer":"趣旨といたしましては、歳出に見合った財源の関係のみの調整ということで、歳出の事業部分については必要なものに充て、それに対する財源のみ、いただいた寄付を活用してという調整で処理させていただいているものです。","voiceIndex":329,"id":"exchange-142"},{"speaker":"阿部委員","kind":"意見","question":"今のご説明で私はまだちょっとよくわからなかったんですけれども、私が言いたいことは、多分伝わっていると思いますので、ぜひいただいた分はプラスアルファで充実を図っていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":331,"id":"exchange-143"},{"speaker":"武内委員","kind":"質問・要望","question":"４年ぶりの最終補正増になったのかなというふうに思いますけれども、平成２０年のときの最終補正が約７.２億円規模で増になったみたいですが、最終補正で増になる、また減になるということに対する何か考え方というか、思いというか、あれば教えていただきたいのと、それから今回の増の補正の要因については、財調が増えた、区民税が伸びた。","respondent":"本城企画財政課長、竹田生活福祉課長、堀越人事課長","answer":"それと、財調の中身等につきましては、先ほどもちょっとご説明させていただきましたが、この間の平成２４年度当初に見込んだとき、住民税の法人分等。生活保護費の医療扶助費が減になっているというご質問ですが、さまざまな要因が考えられますけれども、確実に言えることは。その後、勧奨退職、自己都合退職の出た段階で対応させていただいておりまして、補正でお願いをしているというものです。","voiceIndex":333,"id":"exchange-144"},{"speaker":"武内委員","kind":"質問・要望","question":"補正全般については、そうするとやはりある程度抑えて、慎重なというか、着実な財調だとか、区民税の当初予算では見込んだということでの、だから、あまり景気がこれで上がってきたよというふうに思っちゃいけないということでよろしいのかどうか、それだけ確認したい。つかないものは使っていないよと、こういう判断だと思うんだけど、そこのところを教えていただきたいと思います。","respondent":"本城企画財政課長、間部国保医療年金課長、竹田生活福祉課長、堀越人事課長","answer":"区税収入等の見込みに関してですが、平成２４年度の当初予算を組んだときには経済状況が厳しかったという見込みがありましたので。ジェネリックにつきましては、現在次年度の実施に向けて検討しているところですが、生活習慣病対策の一環ということで。受給者ごとの個別の利用状況がわかり次第、特段の理由もなく先発医薬品の使用を継続している生活保護受給者に対しては。定年以外６２名で、例年この形で補正をお願いしているというものです。","voiceIndex":337,"id":"exchange-145"},{"speaker":"本多委員","kind":"確認","question":"７１ページの生活保護費更正減額、７３ページの各種がん検診更正減額について質問します。今全体の使用頻度、何パーセントかというのはまだ把握できていないということなんでしょうか。その辺のところを確認したい。それと住宅等その他の扶助費では、１億２,７４４万円で、世帯の増加ということなんですけれども、その辺の現在の区の見解を教えてください。","respondent":"竹田生活福祉課長","answer":"今後の見通しですが、薬剤師会等に協力を求めて個別に調査し、利用促進に向けて努めてまいりたいと考えています。それと、住宅等その他の扶助費が増えているですが、こちらは生活保護受給世帯が今年４％程度の増加をしておりますので、こちらに伴うものです。","voiceIndex":343,"id":"exchange-146"},{"speaker":"本多委員","kind":"質問・要望","question":"引き下げが行われたのは１９５０年の制度開始から２００３年、２００４年の２回、それ以降はデフレ傾向が続く中、基準が据え置かれてきたため、一般の低所得世帯に比べて生活保護費のほうが高いという指摘をされているため、適正化を進める方針で、特に住宅扶助は保護費全体の１５％を占め、見直しの必要性が指摘されておりますので、これは国の数値ですが、区としてその辺の住宅扶助の対策といいますか。","respondent":"竹田生活福祉課長","answer":"しかし、生活保護の制度自体は国からの受託事業ですので、全国で一律の制度で運営されるべきというふうにされております。ですので、ご質問の住宅扶助ですが、国で地域別に限度額を定められておりますので、そちらの限度額に沿って制度の運用をしていきたいと考えております。","voiceIndex":345,"id":"exchange-147"},{"speaker":"本多委員","kind":"質問","question":"昨今シェアハウスとか、ルームシェアリングについて大変世の中で普及されているんですが、この辺について、住宅扶助とのかかわり合い、それをどのように考えているんでしょうか。そのとおりだと思うんですね。ただ、一般の中ではそういったルームシェアリングなどが大変ニーズがあって、それとこの生活保護の住宅扶助とどう捉えるのか見解をお聞かせください。","respondent":"竹田生活福祉課長","answer":"ただ、生活保護を受給するということになると、生活保護を受給していない方と受給している方が１本の水道代で請求されて、あるいはガス代、電気代等を請求されて、全て生活保護費で負担するということになると。","voiceIndex":347,"id":"exchange-148"},{"speaker":"本多委員","kind":"質問・要望","question":"ただ、やはり税金が投入をされていて、そのお金の使われ方が適正かどうかというチェックの視点で医療費のことも質問させていただきましたし、住宅扶助のことも質問しています。その辺で受給者が複数で部屋を借りるということ、これを受給者の方たちが工夫をしているんだなと見るのか、それともやはり、ここはチェックをしなければいけないのか、その辺のところをはっきりお聞かせいただきたいと思います。","respondent":"竹田生活福祉課長","answer":"こちらの制度を誤解されないように、私どももまた適正な運営に努めていきたいところです。この制度は地域の住民の相互理解と民生委員をはじめとした地域社会の協力によって確保されているものですので、保護の適正実施に職員一同努めてまいりたいと考えています。","voiceIndex":349,"id":"exchange-149"},{"speaker":"本多委員","kind":"質問・要望","question":"アパートの部屋を共同で借りる場合と、一軒家を共同で借りる場合と、いろんなケースが、世の中でもニーズがあるわけですから、違うと思うんですが、複数での取り組みがどうなのかなというのをもう一度教えていただきたい。","respondent":"竹田生活福祉課長","answer":"すみません、言葉が足りませんでした。今現在受給されている方の中で、更生施設等で複数の部屋に住んでいらっしゃる受給者の方はいらっしゃいます。その場合は、一定額を４人であれば４分の１にしてそれぞれ支給しています。","voiceIndex":351,"id":"exchange-150"},{"speaker":"本多委員","kind":"質問・要望","question":"生活福祉課の中で、保護費返還・徴収に関する業務改善チームを立ち上げられたと「ふれあい」で読ませていただきました。就労支援や不正受給の対策など、課題への取り組みをされているということなんですが、現時点での状況などを教えていただきたいと思います。","respondent":"竹田生活福祉課長","answer":"３月中に議論の結果をまとめて、全職員で知恵を出し合って、新しい体制を今月中に立ち上げまして、４月から新体制で向かう予定です。具体的には債権管理の担当者を決めまして、そこで集中管理いたしまして、債権の適切な回収管理に努めていきたいと考えております。","voiceIndex":353,"id":"exchange-151"},{"speaker":"本多委員","kind":"質問","question":"乳がん、子宮がん検診については、個別通知偶数年という受診の性格上、個別通知の実施ですが、これは紙ベースによるものでお知らせをしているということなんですが、やはり受診して安心、または早期発見ということを目的にするのであれば、その紙ベースでのお知らせももちろん大事ですが。","respondent":"江部健康課長","answer":"ただいまございました人形を使ってのというところにつきましては、ちょっとすぐには答えにくい部分がありますが、どういう場合で使えるのかとか、有効か等々考えながら、研究させていただきたいと思います。","voiceIndex":355,"id":"exchange-152"},{"speaker":"本多委員","kind":"意見","question":"先ほどの質疑の中でも、乳がん検診の受診が落ちたということで、ＰＲを含めて取り組んでいきますという答弁を先ほどもいただきました。それで、国保基本健診の受診率アップのＰＲ事業には、民間企業へ委託し、各種の啓発活動を実施し、一定の成果を上げていると昨年決算特別委員会の総括質疑で答弁をいただきました。なぜこのような民間活力をがん検診には取り入れないのか、その点についてお聞かせください。","respondent":"江部健康課長","answer":"今後につきましては、民間活力という部分については、まだ明確な見解を持っておりませんので検討します。","voiceIndex":357,"id":"exchange-153"},{"speaker":"本多委員","kind":"質問・要望","question":"品川区が協働ということでうたわれておりますので、ぜひここについても民間活力を用いていただきたいと思います。要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":359,"id":"exchange-154"},{"speaker":"飯沼委員","kind":"質問・要望","question":"６８ページから７１ページにかけてなんですけれども、保育園運営費の更正減額のところをお伺いします。ちょっと具体的に数字を幾つかお伺いしたいと思います。職員給与費のところ、これが当初の人数と現在とどう変わっているのか両方教えていただきたい。その下の育児休業等代替人材派遣委託のところ、これはプラスになっていますが、ここも当初と現在が何人になっているのか具体的に数字で教えてください。","respondent":"堀越人事課長、立川保育課長","answer":"職員給与費、一番最初のご質問ですけれども、人数のところは、全体でこの給与の部分にかかる部分は。非常勤職員の配置見込み数と現在ですが、当初６１６名を見込みまして、現在５７３名、それから育児休業代替の人材派遣委託ですが。すみません。ちょっと数字を訂正します。１０月１日、７２４名で、今回の補正が７３２人です。７２４と７３２です。すみません、訂正します。","voiceIndex":361,"id":"exchange-155"},{"speaker":"飯沼委員","kind":"意見","question":"すみません、今の答弁、さっきの数字と全く同じなんですが、一つ疑問に思ったのが、なぜ１０月１日なのかなと。普通４月１日の当初でなくて、なぜ１０月１日なのか、ちょっとそこの疑問に答えてください。","respondent":"堀越人事課長","answer":"すみません、失礼いたしました。１０月１日、予算編成にかかる段階で、その後予算を組み立てていく上で、１０月１日という時期が、予算編成上一番適当な時期ということで、例年１０月１日という形で、その時点での現員現給で見積もりをしているというものです。","voiceIndex":365,"id":"exchange-156"},{"speaker":"飯沼委員","kind":"質問・要望","question":"非常勤のところとか、人材派遣のところの人員的には、比較はどうなんですか、ちょっとそこを１個後で教えてください。非正規職員を雇用する理由というか、その辺と、人材派遣を雇用する理由を、基本的なところを教えていただきたいのが一つです。","respondent":"立川保育課長","answer":"病欠が当初見込みから、やはり倍以上で、現在１４名の方です。特別支援保育を実施しておりますので、個別の対応が必要な場合等に活用させていただきまして、これが現在２７名入ってもらっております。保育園の定員の弾力化の部分です。","voiceIndex":367,"id":"exchange-157"},{"speaker":"飯沼委員","kind":"確認","question":"一番最初のところの１０月１日の人員なのかどうか、ちょっと後で、非常勤と育休の人材派遣のところが、比較が同じ１０月１日なのかどうか確認をさせてください。今、具体的に、特に人材派遣のところをこれからお伺いしますが、１０２名の内容を伺いました。品川区自身がこうやって人材派遣をどんどん導入しているわけですけれども、雇用を悪化させているという自覚があるのかどうか、この点もお伺いします。","respondent":"立川保育課長、堀越人事課長","answer":"特別支援を要するお子さんへの対応ということで、なぜ派遣なのかということですけれども、区の採用計画というのは、人事所管になりますけれども、特別支援児というのは毎年認定しておりまして、そういった意味で。雇用の悪化等のご質問ですけれども、人材派遣につきましては、今、保育課長が答弁させていただいた考え方で活用させていただいているということと、働く側の方のニーズですとか、そういった部分。","voiceIndex":369,"id":"exchange-158"},{"speaker":"飯沼委員","kind":"質問・要望","question":"弾力化ですよね。これは単純に計算して３１でいいんでしょうか。弾力化のところこそ待機児解消で、本来だったら新しい保育園をつくるべきところをつくらないで、既存のところで定数を拡大している、弾力化のところに派遣を充てるなんてとんでもないんじゃないでしょうか。正規職員をきちんと充てるべきであると思います。もう一回ここのところを答えてください。","respondent":"立川保育課長、伊崎待機児童対策担当課長、堀越人事課長","answer":"弾力化の部分につきましては、待機児童対策担当課長よりお答えします。当然弾力化で入れる子どもの数、あと面積等は保育所の設置基準に沿ってやっておりますので。私どもといたしましては、雇用形態の関係に関しましては、法制度にのっとって実際に活用しているというものです。","voiceIndex":372,"id":"exchange-159"},{"speaker":"須貝委員","kind":"質問・要望","question":"私は先ほど来質問が出ておりました基金の積み立てについてお聞きしたいと思います。そして、１００ページの地域の元気臨時交付金ついて質問させていただきたいと思います。先ほど来いろいろお話が出ていました。どこに振り分けてもいいと思うんですが、その辺についてちょっとご見解、いいんですよね、そういうことで、どうでしょうか。","respondent":"本城企画財政課長","answer":"最終補正の段階につきましては、基本的にはこれから新しい事業という形の展開はなかなか時期的には困難ですので、実際実績見合いの減額等とか、最終的な整理というものが中心となっておりまして。","voiceIndex":377,"id":"exchange-160"},{"speaker":"須貝委員","kind":"質問","question":"すみません、私の質問が悪かったんですね。この資金は、例えば余剰で残った場合は、別に一般財源のほうに入れて、要は事業化をしなくても繰越金として残してもいいわけですよね。それに対して別段問題点というのはあるんでしょうか。","respondent":"本城企画財政課長","answer":"年度末を向かえる際に、剰余金の関係の処理ですが、地方財政法の関係のルールの中で、剰余金の処理について規定されておりまして、２分の１以上のものについては基金に回すというような形で、一定部分を基金に回すという形の整理が法制上もなっているところです。","voiceIndex":379,"id":"exchange-161"},{"speaker":"須貝委員","kind":"質問","question":"実際、品川区の本当の収支はどうなんですかといったときに、いや基金に入れちゃいましたから、バランス上どこにも出てきません、わからない。それを基金に入れちゃうと、あれっ、３０億円しかありませんでしたということで、収支は３０億円で、手堅く区は発表して、公表していますが、その点についてちょっともう一回ご見解をお聞かせください。","respondent":"本城企画財政課長","answer":"ただ、委員おっしゃられるとおり、わかりやすさという観点からは、基金の意義を正確にお伝えする中で、財政全体の中で基金の役割も含めてきちんとわかりやすい説明はしていかなければならないということは確かだと考えているところです。","voiceIndex":381,"id":"exchange-162"},{"speaker":"須貝委員","kind":"質問","question":"一般の企業でも、皆さん区民でも預貯金はどこかに入れています。定期でも何でも。そうすると、品川区の施設一体型小中一貫校、間もなく６校完成しますが、しかし、この施設一体型小中一貫校は、法律の定めがないという話をこの間しましたけど、まだ法的根拠がないまま、なぜ建設を進められるんですか。高さはどうですかとか、廊下の高さ、部屋の広さはどうですか、そういうのが全部あります。","respondent":"日下部企画部長、齋藤庶務課長","answer":"あのときに教育委員会のほうからお答えを申し上げました。まさしくあの答弁に区としての基本的な考え方、これが端的にあらわされていると、このように考えております。教育次長からご答弁申し上げましたとおり教育基本法ではなくて、特区、新しい法律に基づいて設置しております。許可をいただいております。「特別法は一般法を破る」と、こういう法格言があります。","voiceIndex":383,"id":"exchange-163"},{"speaker":"須貝委員","kind":"質問","question":"今、違法ということは言っていないんですが、なぜ進められるのかというと、普通、区の施設でも、何でも法律に基づいて建てていますよね。次に、国の地域の元気臨時交付金についてお聞かせ願いたいと思います。今回国の臨時経済対策として、地域の元気臨時交付金が今年の１月１６日に出動されました。","respondent":"本城企画財政課長","answer":"事業名ですが、全部で五つあります。道路擁壁調査の調査委託について、それから道路下空洞調査について、それから橋梁点検委託について、それが２件です。それから耐火建築物等建築助成についてです。それが補助対象となるものです。","voiceIndex":386,"id":"exchange-164"},{"speaker":"須貝委員","kind":"質問","question":"今の５点ということですが、これらは、先ほどもそちらでお話ししておりましたが、従来から計画されてきたもので、これは財源のいわば振り替えじゃないんですかと、端的に申し上げれば。その名称にふさわしい活用なのかどうか、この事業は景気刺激の効果が発揮されるんですか。その点についてちょっとお聞かせください。","respondent":"本城企画財政課長","answer":"こちらの地域の元気臨時交付金につきましては、今度の緊急経済対策の一環といたしまして、国が対策としてつくったものの中で、市町村の負担が大きくなるですので、そういう状況のもとで市町村の負担を軽減して事業を円滑にするという趣旨ですので、そういう趣旨に即しまして。","voiceIndex":388,"id":"exchange-165"},{"speaker":"須貝委員","kind":"質問","question":"もう一度申し上げますけど、地域経済活性化のためにこのお金というのは、緊急経済対策として出たんじゃないんですか。名称も地域の元気臨時交付金と出ています。全然ちょっと中身が違うんじゃないんですか。元気になってほしいんだ。地域経済活性化のために使ってほしい。ところが、現実は違うんじゃないんですか。これがどうしてこの名称と折り合いがつくんですか。ちょっとご見解をお聞かせください。","respondent":"本城企画財政課長","answer":"緊急経済対策の一環として出てきまして、現在その事業の中でどういった形の事業がこの中に取り込まれているということで、防災等が中心となっておりますので、事業の内容に即して言えばそのような形で区の事業も展開しているです。","voiceIndex":390,"id":"exchange-166"},{"speaker":"須貝委員","kind":"質問","question":"防災のほうはちゃんと出ていますよね、防災のほうで、きちんと、今回。これは地域経済活性化ですよね。すみません、ちょっと一般の区民から見て、地域活性化と景気の拡大が、このお金、この事業というのはわかりますか。一般の区民にとってわかると思われますか。ちょっとそれだけね、わからない。今の予算が来たから、これに振り当てた、それはわかる。だが、一般の人はこれがわかるんですか。","respondent":"本城企画財政課長","answer":"区といたしましても、そういう形で国の財源が組み立てられているところを、当初予定していた事業について有効活用して、それを行っていくということで今回取り組んでいるところです。","voiceIndex":392,"id":"exchange-167"},{"speaker":"須貝委員","kind":"意見","question":"これには確かに雇用創出というのもあると思います。ですけど、雇用を創出しても、やっぱり一過性の事業ですよね。一応平成２５年度にやろうかなというものを前に出した。それは区としては交付金が来るんだから有効に使う。そういうやり方で品川区のために使う。そういう予算をとってきてきちんと使う。ですけど、ちょっと区民にわかりにくいんじゃないかなと思うんですが、もう一度だけお話しください。","respondent":"本城企画財政課長","answer":"仕事の中身等につきましては、繰り返しになりますが、そういう事業を通じて今回も区からこういう形で事業をそれぞれに発注することになりますので、それを通じて雇用創出等を含めた対策の一環にはなっているのではないかと考えているところです。","voiceIndex":394,"id":"exchange-168"},{"speaker":"若林委員","kind":"意見","question":"私は７３ページの乳がん検診と、９８ページの職員給与費明細書の２点です。乳がん検診です。この受診率がなかなか１回ぐっと３割程度まで上がったのに、この２年連続、平成２４年も含めると、２年連続になるのか、下がっていくというこの現状について、どういう認識でおられるのかというのをまず聞いておきたい。","respondent":"江部健康課長","answer":"平成２３年度につきまして、我々ももう少し１万数千人という数字を見込んで予算を計上し、平成２４年も引き続いているですが、平成２３年度につきましては、先ほどの二つの検診方法の変更によりまして。","voiceIndex":397,"id":"exchange-169"},{"speaker":"若林委員","kind":"提案","question":"この状態というのは、今日は乳がん検診だけの話ですけども、どの事業にも言えるのかなということで、やはりしっかりといま一度、年度途中で評価をする体制というのを、例えば今計画を立てて実行して、そして年度途中で評価をして、率が計画どおりに、目標どおりにいっていないなというときに、健康課は乳がん検診についてはどのようにこのＰＤＣＡのサイクルを回しているのかというのを確認したい。","respondent":"江部健康課長","answer":"委員ご指摘の向上に向けた取り組みという部分については、やはり今のところ受診者については、手はかなり尽くしているなというところは思っておりますけれども、実施機関の整理といいますか、もう少し細やかなＰＲであったり、各実施機関に少し拡大を要請する等々については。","voiceIndex":399,"id":"exchange-170"},{"speaker":"若林委員","kind":"質問・要望","question":"大体こういう答弁になるわけですが、一つ一つ、いわゆる実行していく中には、さっきの検診体制の充実も含めてＰＲという話もありました、またいろんな器具を使えという話もありましたけれども、一つ一つの実行策をしっかりその都度チェックをして、例えば今、病院が広がっていますけれども、一つ一つの病院と年度途中にどういう連携を今、とられておりますか、いわゆる評価をする中で。","respondent":"江部健康課長","answer":"そういったことで、医療機関の情報は随時やっております。それからあと、年度が終わりました段階で、全体の担当者のほうへの年度の報告をし、評価をしたものを１回お渡しして、また来年改善できるかどうかをチェックする検討会というのを設けてやっているところです。","voiceIndex":401,"id":"exchange-171"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"鮫洲入江は、入札率をちょっと教えていただきたいのと、これはわかっていてあえて言っているんだけど、やけに低くて、うちの幹事長が代表質問でもやったんだけれども、こういう低いときに、やっぱりずっと自民党も二、三年見てきて、大分いろんな施設もでき上がったのを見たときに、安かろう悪かろうというのが最近目につき過ぎるんじゃないかと思っている我々もいる部分があるので。","respondent":"本城企画財政課長、多並公園課長、平澤経理課長","answer":"いろんな関係等の情報のとり方については、国、都も含めてですが、それぞれの所管のほうで日々の通知等を中心に情報収集を得たものも含めて。あり方の検討の件ですが、平成２３年度あり方の検討委員会を設置いたしまして、５年先、１０年先の水族館の将来のあり方について検討してまいりました。二つ目に、総合評価、それから最低制限価格制度の導入についてですが、一般質問でご答弁させていただきましたとおり、総合評価につきましても。","voiceIndex":405,"id":"exchange-172"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"すみません、最低制限価格はぜひ導入していただきたいと思います。後で、違うところでやります。だから、そこら辺の感覚を教えていただきたいのと、宝くじ等助成の等というのを、今言った企業も含めてあるんだけど、企業なんかは専門家を置いて、慣れている人間がいろんなところを調べて、それで商売もしているぐらいで、私は行政にそういう人を１人置くべきだと言っているわけ。それを答えていただきたい。","respondent":"本城企画財政課長","answer":"補正予算と当初予算との関係ですが、手続的にということでちょっと前段で申し上げてしまいましたが、今委員がおっしゃるところを踏まえると、当然最終補正の段階では時期的に新たな事業の展開が難しいということで、実績見合いの減等を中心になっている面もありますが。","voiceIndex":409,"id":"exchange-173"},{"speaker":"石田（秀）委員","kind":"質問","question":"やっぱり、そういうのというのは、例えば我々も多分いろんな一般質問でも何でも、例えばイオンマネーを一緒にやろうといって、検討しますとなるじゃない、自民党で質問したとしても。私はそういうことをしてもらいたいなと思うので、そこだけはもう１個考えをお願いしたいのと、事業部、私は事業部長に、誰かでもいいけど、手を挙げて聞きたいけれども、じゃあ、目間流用しました。","respondent":"日下部企画部長","answer":"その場合にどこが責任を持って対応するかというと、これはやっぱり企画部ですね。所管も事業部制をベースにして、情報に関するアンテナをしっかり張る。一方で、私どもはそれをしっかりと束ねて、それを財政にもきっちり反映できるようにする。","voiceIndex":411,"id":"exchange-174"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=982#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":123881,"voices":416}},{"id":"h25-20130305-3","meetingId":"h25-c-budget","date":"2013年3月5日","dateIso":"2013-03-05","committee":"予算特別委員会","time":"午前１０時００分～午後６時００分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を175件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２５年度品川区一般会計予算","agenda":"平成２５年度品川区一般会計予算","exchanges":[{"speaker":"渡部委員","kind":"質問","question":"私は、今日は、使用料、さまざまな使用料のところでお伺いをしていくのですが、まず初めに、例えば５６ページから始まります使用料及び手数料の使用料で、集会所使用料ですとか、さまざまな使用料につきまして回数を示されております。全部書き方として、あくまでも減免団体、いわゆるゼロです、１００％免除が、これは含まれているのか、含まれていないのかをまずちょっと教えてください。全体の話です。","respondent":"本城企画財政課長","answer":"使用料につきましては、実際の歳入額ということなので、免除だとかは含まれていないものです。","voiceIndex":4,"id":"exchange-001"},{"speaker":"渡部委員","kind":"質問","question":"荏原第三地域センターで事務を取り扱っていて、でも、実はあそこが仮になくなったと考えたら、荏原第二地域センターが歩いて５分ぐらいのところにありますので、そちらも使い勝手がいいとは思うのですが、ここを使われていた団体、いわゆる９０回で反映されている団体のほかに、もしかしたらあの辺の地域町会等がここの数字に反映されていないと思うのですが、どのような使い方をされていたのかというのと。","respondent":"久保田地域活動課長","answer":"利用者の方からの反応ですけれども、確かにこちら、ずっと定期的に利用してまいりましたので、非常に残念という声は町会を通じて聞いてありますけれども、私ども、町会を通じまして、周辺の施設の状況等、また、スクエア荏原が開設したり、荏原第三地域センターが開設して。","voiceIndex":6,"id":"exchange-002"},{"speaker":"渡部委員","kind":"質問","question":"その件はわかりました。次が、６４ページ、児童センター使用料で、たしか目的外使用を認めるということで、夜間でしょうか、貸出を始められて、何年か前の質問だったと思いますが、児童センターというのか、実は独立して建っている場所があったりして、その地域の方々にとっては、そこが使えるとなりますと非常に便がいいというようなところもあるのかというような意味合いで質問させていただいています。","respondent":"安井子育て支援課長","answer":"社会教育登録団体がこちらをご利用になるというようなケースもございまして、こちらは気功であるとか、太極拳であるとか、運動系のサークル団体がご利用になるケースが約３０団体ほど登録されてご使用になっているというようなところはあります。","voiceIndex":8,"id":"exchange-003"},{"speaker":"渡部委員","kind":"質問・要望","question":"意外と、先ほど冒頭に聞いた、これはあくまでも予算審議ですから使用回数というのは、お金をお支払いしている方のみの回数提示がされていて、今伺っていると、いろいろ地域要望はあるなと。この学校のプールというのを１年間使うと考えたときに、どういうふうに授業といいますか、どのタイミングで、どういうふうに利用の割振りをしていっているのかというのをちょっと教えていただけますでしょうか。","respondent":"太田指導課長","answer":"学校の予定ももちろん前年の夏ごろには教育課程の編成に入りますので、まずは学校の使用を優先していただいて、それ以外のところにその希望の団体の使用を入れていただくというような形で、学校の使用についてそごといいますか。","voiceIndex":10,"id":"exchange-004"},{"speaker":"渡部委員","kind":"質問","question":"そういった場合、この辺が、ちょっともう時間がないですけれども、しっかりと教育活動に影響がないように、そして一般開放の方々がしっかりとわかりやすく使えるような仕組みを築いていってほしいという思いで質問させていただきました。時間がないのでもう１個だけ聞きたいことがあります。これ、場合によってはスポレクとそういう調整会議というものを一旦まとめてやるというのはいかがでしょうか。","respondent":"安藤文化スポーツ振興課長","answer":"しかし、ご指摘のとおり、今後、スポーツも文化もまとめて地域の輪をつくっていきたいというふうに考えています。","voiceIndex":12,"id":"exchange-005"},{"speaker":"渡部委員","kind":"質問","question":"一貫してこの使用料というところでお話をさせていただきましたが、地域の活動団体は、数をお伺いしても結構な数あります。もっともっと活動しやすいように、どこと決まることなくさまざまな施設をより有効に活用していただける仕組みづくりが必要かと思いますので、これからもよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-006"},{"speaker":"阿久津委員","kind":"質問","question":"質問する順番からお知らせします。１３５ページ、諸収入からマイガーデン運営費負担金、１２７ページ、これも同じく諸収入から資源持ち去り防止過料、時間があれば、７１ページ、使用料及び手数料から公園占用料、ロケーション・写真撮影等というところで質問します。１月に来年度の募集があったと思いますけれども、その応募数、大体の倍率を教えていただければと思います。","respondent":"多並公園課長","answer":"予算のほうでは２７区画、一月２,０００円で１１カ月ということで予算計上させていただきましたが、実際には今年度、マイガーデンの国道側の道路予定地の工事をやっておりまして、その中で今の区画をもう一度見直しまして、いろいろ募集の倍率がある中で。","voiceIndex":16,"id":"exchange-007"},{"speaker":"阿久津委員","kind":"質問・要望","question":"当初、６３区画あったのが、増やしていただいて３２区画ということで、この質問をさせていただいたのは、最近立て続けにこういった農業体験、農作業へのご要望というのを区民の方から伺いました。先ほど応募率、倍率を教えていただきましたけれども、全国の応募率が１２９％に対し、東京都特別区では２６２％と高倍率になっている。","respondent":"多並公園課長","answer":"そのアンケート等ですが、アンケートを特にとっているところではございませんが、今までの倍率、先ほどご紹介させていただきましたが、近年で言えば５倍程度であったところからすれば、一定程度のニーズはあるもの、そのように認識しています。","voiceIndex":20,"id":"exchange-008"},{"speaker":"阿久津委員","kind":"提案","question":"例えば、ここを区民農園として一部開放していただく。提案というか、私の勝手な思いですけれども、逆にそういう災害時の食料ともなるわけで、これは一つの考えですが、このような農作業に対する区民ニーズに対して、品川区として今後どのようにお考えなのかお聞かせいただければと思います。","respondent":"多並公園課長","answer":"もう一つのＪＴの件ですが、ＪＴ跡地につきましては、しながわ中央公園と一体となった防災拠点の整備ということを大きな目的としてございまして、防災機能または防災活動等、その活動する中の来年度基本設計をする中で。","voiceIndex":22,"id":"exchange-009"},{"speaker":"阿久津委員","kind":"提案","question":"提案というよりは、要するに、土地がないという中で、大きな土地ということで考えた私の突拍子もない提案と先ほど言いましたけれども、こういうことも含めて遊休地のさらなる拡大というか、利用、そういうものを進めていっていただきたいというのが趣旨ですので、この辺はご理解いただきたいと思います。これ、同じ業者がやっているのかどうか、これについても教えていただければと思います。","respondent":"太田品川区清掃事務所長","answer":"私のほうからご答弁します。平成２４年度の実績ですけれども、現在、荏原地域、それから品川地域、毎日二人一組でパトロールをしています。４月から２月末まで２８４日出動をしています。うち指導が４３３件、大体月４０件前後です。そういう実態です。","voiceIndex":24,"id":"exchange-010"},{"speaker":"阿久津委員","kind":"質問・要望","question":"よろしいでしょうか。エコスポットです。例えば、こうした実例に対して品川区としてはどういうお考えなのかというのをお伺いしたかったのですが、例えば足立区も品川区以上にこういう資源ごみの持ち去りに関しては非常に悩みを持っていて、パブリックコメント等で一定の施策をとっておりますけれども、今、足立区がやっているのは、資源ごみ買取市というのをやっています。","respondent":"太田品川区清掃事務所長","answer":"それと、現実に３月１日から３月１５日、２週間ですけれども、警察との区内４署との行動のパトロールも現在実施をしています。こうしたことを通じて、少しでも抜き取り防止に努力をしていきたいというふうに思ってあります。","voiceIndex":26,"id":"exchange-011"},{"speaker":"阿久津委員","kind":"質問","question":"ご努力をされていると重々承知しておりますけれども、その上での重ねてのお願いになりました。本当に集団での回収等も今、一生懸命やっていただいているということで、またさらなる工夫、ご努力はいただいていることはわかっておりますけれども、また今後ともその推進をよろしくお願いいたします。最後の質問については、またほかのところでやらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-012"},{"speaker":"藤原委員","kind":"質問","question":"５０ページ、特別区財政調整交付金、６１ページ、こみゅにてぃぷらざ八潮、１２０ページ、財産貸付収入の賃貸料、３５６ページが公債費で、まず、財調を伺いますが、企画部が出している委員会資料の中で、財調のところで、括弧書きで（フレーム対比）とありますが、改めてこのことについてお伺いします。","respondent":"本城企画財政課長","answer":"現在の段階で、東京都の条例におきまして、全体の見通しを、全体の枠をまず算定してから、それに基づいて８月ごろに各算定になります。その前段の全体として財調の規模がどれぐらいになるかという意味でのフレームということで、今、提示しているものです。","voiceIndex":30,"id":"exchange-013"},{"speaker":"藤原委員","kind":"質問","question":"ですよね。それで、財調については平成２５年度の当初予算と、平成２４年度の当初予算と同額ですよね。で、このフレーム対比ですけれども、この資料で４.２％増となっていますよね。同額なのにフレーム対比だと同じ４.２％増になっていないではないですか。その辺がよくわからないのですけれども、説明してください。","respondent":"本城企画財政課長","answer":"それとあと、その基礎となる財調の４.２％の伸びについても、実際、経済の先行きはちょっと不透明なところもありますから、より確実に見込むということ、その両面で品川区では同額という形に算定しています。","voiceIndex":32,"id":"exchange-014"},{"speaker":"藤原委員","kind":"質問","question":"毎回こういうときの答弁で、固くという形でおっしゃるではないですか。その経済状況等もあると思いますけれども、今回こういう形で見込んでいるけれども、この見込みの甘さというのが出てくると、これはもう大変なことになってしまうと思うので、この辺の企画財政課としての見込みということに関しては、どういうふうに考えていらっしゃるのか、改めてお伺いしたいと思います。","respondent":"本城企画財政課長","answer":"それで、一つは、確実な線で見込まないと結果的に穴があいてきてしまうという面もありますから、より慎重に見込んだという面がありますが、それと、繰り返しになりますが、そういった経済状況の反映を区なりに判断するもう一つ大きなことは、先ほど平成２４年度の財調。","voiceIndex":34,"id":"exchange-015"},{"speaker":"藤原委員","kind":"質問","question":"わかりました。次、公債費ですけれども、今、平成２４年度末の公債費の残高は幾らでしょうか。","respondent":"本城企画財政課長","answer":"平成２４年度末ということでよろしいでしょうか。２４３億８,１００万円です。","voiceIndex":36,"id":"exchange-016"},{"speaker":"藤原委員","kind":"質問","question":"これから上大崎のみやこ荘跡地と、あと、下神明のＪＴ跡地の購入になっていくと思いますけれども、よくこういう購入というときに、財調で措置をされますという形でお話を受けるのですけれども、それを含めて今後の公債費の負担と、その見通しについて、どのように区としては考えているか教えてください。","respondent":"本城企画財政課長","answer":"今の起債の残高の推移ですが、現在は、今お話させていただいたような残高ですが、今後の見通しといたしましては、順調に償還していくと、平成４８年には残高ゼロという、そのような形で見込んでいるところです。","voiceIndex":38,"id":"exchange-017"},{"speaker":"藤原委員","kind":"質問","question":"借金ですから、ないに越したことはないですけれども、施策をしている中において、やはり今、いわゆる購入するという形をとっても、この購入したことによって区民の方々が、子どもとかという形でご負担をいただくという性質というか、性格というか、そういうこともあると思いますけれども、今、課長がゼロになりますと言うと、ゼロはいいですけれども、そういうものではない性質だと思うので。","respondent":"本城企画財政課長","answer":"それで、基本的には起債の基本的な考え方ですが、施設の整備等につきまして、現役世代と将来世代が公平に負担を分かち合うというものがありますので、そのようなものの起債の利点も基本的によくよく認識しながら、ただ起債に当たっては。","voiceIndex":40,"id":"exchange-018"},{"speaker":"向委員","kind":"質問","question":"よろしくお願いします。私からは、ページ順で申し上げますと、５６ページ、５７ページ当たりでしょうか、総務使用料のところ、区有施設使用料全般ということで、公衆無線ＬＡＮの設置状況と、それに関連する使用料、あと、６８ページ、６９ページの武蔵小山創業支援センターの産業振興施設使用料ですか、１５室となっていますが、そのあたりに関連してお尋ねしたいと思います。お願いします。","respondent":"福島ものづくり・経営支援課長","answer":"武蔵小山創業支援センター１５室の内訳ですが、こちらは１階に３室、チャレンジショップがあります。２階、３階に、１室とカウントしていますけれども、認証保育所があります。５階に会議室が３室、大１室、小２室です。","voiceIndex":43,"id":"exchange-019"},{"speaker":"向委員","kind":"質問","question":"この中で貸会議室、大小あるということでしたが、貸会議室の稼働率についてと、あと、今回、１,３７２万円ほど予算額ということで書いてありますが、これについてはどのように区として捉えていらっしゃるか教えてください。","respondent":"福島ものづくり・経営支援課長","answer":"貸会議室の利用率ですけれども、まず、平成２４年度１月までですけれども、第一会議室につきましてが、午前が３２％、午後が５４％、夜間が３４％というような形で、一番大きいところで、第三会議室ですと、午前が３５％、午後が５３％、夜間が４０％、そのような状態です。","voiceIndex":45,"id":"exchange-020"},{"speaker":"向委員","kind":"質問・要望","question":"このあたりの稼働率についても、おいおい区としてのご所見を伺いながらお答えいただきたいのですが、これに関連して、先日、２回目のウーマンズビジネスグランプリがありまして、区長はじめ理事者の方も、私も出席させていただいて拝見しました。","respondent":"福島ものづくり・経営支援課長","answer":"今回、申し込まれ、実際に案件を出された方が８７人ぐらいだったと思いますけれども、それらの方を審査しまして、ファイナルに進んだ８人、さらにはグランプリをとった方、そういった方々に品川区内での起業を誘導していきたいというふうに考えてあります。","voiceIndex":47,"id":"exchange-021"},{"speaker":"向委員","kind":"質問・要望","question":"この審査の内容等々についてお尋ねしたいのですが、去年、今年と２年間続けて観覧してみて、出席された方、隣で見ていらっしゃった方ともちょっとお話をしましたけれども、審査の基準が見ているほうにちょっとわかりにくい、今後、起業したいということで見に行かれた方も結構いらっしゃったようですが、どうしてこの方が選ばれたのかとか、例えば、皆さんの中にも起業されている方。","respondent":"福島ものづくり・経営支援課長","answer":"これが終わった後、応募していただいた方へのフォロー、そういったことも重要だと思ってありますので、その辺も含めて行っていきたいというふうに考えてあります。","voiceIndex":49,"id":"exchange-022"},{"speaker":"向委員","kind":"意見","question":"最後に一つだけ。今回、応募された方の中で、区民の方の割合とか、今後、日常的に武蔵小山創業支援センターを利用された方の割合が高かったのか、低かったのか、わりと区外の方が多いとか、今年の予算で区内での起業支援の新しい予算がついているので、できればその中から区内でもちょっとずつでも定着してほしいという区のお考えは重々わかるのですが、そのあたりの現状を最後にお知らせください。","respondent":"福島ものづくり・経営支援課長","answer":"ゆくゆくは、先ほど言いましたように、区内での起業を誘導していくという考えはかわりございません。","voiceIndex":51,"id":"exchange-023"},{"speaker":"向委員","kind":"質問・要望","question":"とてもよくわかりました。５分ほどありますので、５６ページ、５７ページあたりの区有施設の中の公衆無線ＬＡＮについてですが、昨年、私の一般質問でも、公衆無線ＬＡＮの設置はどうですかということでお尋ねをしました。それ以外のところでも、今、公衆無線ＬＡＮを新たに設置の状況が進んでいるということを伺っていますので、そのあたりの進捗状況も踏まえて教えてください。","respondent":"中元品川図書館長、秋山情報システム課長","answer":"品川図書館と大崎図書館における公衆無線ＬＡＮの設置ですが、相手方の企業からの申し出により設置をしておりまして歳入が発生しています。今後とも特に相手方の企業側の状況が変わらない限りは継続していくつもりです。入れることによって、セキュリティーとか運用面、どのような方が使われるのかとか、どういう使われ方をするのか、どんな影響が出てくるのかというのを検証して、今後については検討させていただきたいと考えています。","voiceIndex":53,"id":"exchange-024"},{"speaker":"向委員","kind":"質問","question":"具体的に区内、新しく設置予定の区有施設の名前とか、もし今、わかる範囲で教えてください。","respondent":"秋山情報システム課長","answer":"今のところ、事業者のほうに、どこでできるのかというところもありますので、きゅりあんとスクエア荏原、総合体育館、総合庁舎について、事業者とできるかどうかということで調整をしています。","voiceIndex":57,"id":"exchange-025"},{"speaker":"向委員","kind":"意見","question":"去年の第２回の定例会だったので、大分時間はたちましたが、着々と進んでいるということで安心をしております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":59,"id":"exchange-026"},{"speaker":"中塚委員","kind":"質問・要望","question":"財調のことですけれども、先ほども質疑がありましたが、私も同様の疑問がありまして、財調の普通交付金について、なぜ前年同額の３３０億円なのかということを伺いたいと思います。国や東京都の補助金を差し引いた一般財源部分がその対象となると伺っているのですけれども、そこからどういう割合で、要するに、どういうふうに算定をするのか、仕組みをご説明いただきたいと思います。","respondent":"本城企画財政課長","answer":"財調の見込みについてですが、先ほどの説明と重なりますが、フレームの中では都全体ではある程度増が見込まれているところですが、一つは、今は総額４％余というのは、フレームということで、全体の枠組みです。","voiceIndex":61,"id":"exchange-027"},{"speaker":"中塚委員","kind":"質問","question":"当初、厳しい、厳しいというわりには、随分余裕というのが率直な意見ですけれども、改めて伺いたいと思います。あわせて、この財調の目的がよく自治体間の財政の均衡化という話は伺うのですけれども、つまり、都市計画、再開発に熱心な区ほど財調や都市計画交付金がどんどん入ってくる、そういう関係が生まれてしまうのではないかと思いますけれども、その点についてはどうお考えなのか伺いたいと思います。","respondent":"本城企画財政課長","answer":"当初の見込みですが、財調の交付金の見込みにつきましては、全体のフレームの中で各区がそれぞれ見込まなければいけないですので、今回は、例えば、いわゆる態容補正で見られているところ、さっき、国文学資料館等を言いましたけれども、それらを含めて。","voiceIndex":63,"id":"exchange-028"},{"speaker":"中塚委員","kind":"質問・要望","question":"それと、先ほど伺ったのは、要するに、土木費といいますか、都市計画の対象が、当初２５％交付金で、あと７５％財調で戻ってくるわけですけれども、ということは、こういう再開発をやればやるほど増えてくるという関係にあるのか、そうすると、自治体間の均衡化というところからずれてしまうのではないかと思いますけれども、そこについて先ほど伺ったのですけれども。","respondent":"本城企画財政課長","answer":"それらについては、今年度、財調が措置されるという、そのような関係です。それから、あとは、平成２５年度の見込みについてですが、先ほどは国文学資料館関係でお話いたしましたが、このほか平成２４年度についても、都市計画関係の種々の増減がありました。","voiceIndex":67,"id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"だから、よく先ほどの説明はわかりませんでした。昨年は１２５億円取り崩して、基金残高が９９億円減ると。厳しい、厳しいと当初は言いますけれども、結果的には随分余裕があると、私は思うのですけれども、仕組みはなぞですけれども、何らかの方法で上手にやっていると、全国一の健全財政というのを『東洋経済』という雑誌で紹介されておりましたけれども、どういうことなのか改めて伺いたいと思います。","respondent":"本城企画財政課長","answer":"そういう趣旨ですが、ただ、経済変動の状況の中で、先行きもなかなか厳しい状況が見込まれる中、２３区全体の中でも、まだ品川区の財調資金はかなり低い水準にあります。","voiceIndex":69,"id":"exchange-030"},{"speaker":"塚本委員","kind":"質問・要望","question":"私は、初めに、１０８ページの地域連携環境政策推進補助金、それから続きまして、１３６ページのリサイクル資源売払収入、あと、戻りまして１０４ページの放課後子ども教室等補助金、この３点についてお伺いをしたいと思います。","respondent":"野呂瀬環境課長","answer":"この補助金の内容です。これはカラス・外来種対策となっておりますが、実際は外来種対策、いわゆるハクビシンとか、アライグマ、これらの被害に対応することで補助金をつけて、その補助金に対して区のほうで対応していく、こういうものです。","voiceIndex":74,"id":"exchange-031"},{"speaker":"塚本委員","kind":"質問","question":"一方では、決してこれは駆除したりそういうことをしてはいけないということで、長年いろいろな陳情なりご相談をいただいて悩んできた問題ですけれども、最近、去勢という一つの手段によって両者が折り合えるということで、非常に一つの解決策が見出されたような印象がありまして、町会が、かつては個人に対して助成ということで、１人１０匹まででしたか、１０万円でしたか。","respondent":"野呂瀬環境課長、工藤生活衛生課長","answer":"この補助金というのは、実際、東京都地域と連携した環境政策推進のための区市町村補助制度、これが正式名称でございまして、今委員おっしゃいました猫等というのは、基本的にはやはりそれは飼い主だとかの責任。この中に飼い主のいない猫対策という部分で補助金をいただいておりまして、いわゆる２０６万円上限で、２分の１の補助ということになってありますので、実質的には１０３万円の補助が来ているです。","voiceIndex":78,"id":"exchange-032"},{"speaker":"塚本委員","kind":"質問・要望","question":"わかりました。続きまして、１３６ページのリサイクル資源売払収入ですけれども、平成２５年度の１０月から品川区といたしましても、小型家電の拠点回収ということを開始するということで伺っております。この件につきまして、１０月からですけれども、どの程度収入として見込んでいるのか、また、拠点回収ということですが、回収の方法についてお伺いしたいと思います。","respondent":"太田品川区清掃事務所長","answer":"したがって、市町村がそこの認定事業者へ処理依頼をしたときに、市町村の負担がないと、こういう形で実施されるのが基本です。","voiceIndex":81,"id":"exchange-033"},{"speaker":"塚本委員","kind":"質問・要望","question":"収入については、今のご説明よくわかりました。もう一つは、先ほど持ち去りですね、ちょっとほかの委員からもありましたけれども、持ち去りの問題、施錠つきのボックスでですけれども、物を見ていないのでちょっとわかりませんが、その辺の対策、どのようになっているのかお伺いしたいと思います。","respondent":"太田品川区清掃事務所長","answer":"私どもも、当然実施するに当たっては、委員ご指摘のとおり、個人情報の保護と、それから一定の量が集まりますので、持ち去り防止、この点から回収方法を考えさせていただきました。","voiceIndex":83,"id":"exchange-034"},{"speaker":"塚本委員","kind":"質問","question":"これはすまいるスクールの所管が教育委員会から子ども未来事業部に移管されたということに伴うものと、このように理解いたしておりますけれども、この間、この補助金が教育費補助金から民生費補助金に移るに当たって、この移管というのがスムーズになされたのか、都とのこの間のやりとりや話し合い、こういったものがどのようなものであったのかお伺いしたいというふうに思います。","respondent":"齋藤庶務課長","answer":"この３月まで教育委員会が所管しております。都とのやりとりですが、特段のものはございません。よその区では、子ども関連の所管でやっておりまして、民生費補助金になっている区もあります。教育費補助金か、民生費補助金にするかは大きな問題ではないです。","voiceIndex":85,"id":"exchange-035"},{"speaker":"塚本委員","kind":"質問・要望","question":"今のご答弁で問題はないと思いますけれども、一応確認のためにお伺いしますが、今まですまいるスクールでやってきたさまざまな活動、例えば、教員の方が手伝いをするような形で、いわゆる授業の補習みたいなことをやっているところもあるかと思いますけれども、さまざまなそういったことについて、特段制限なく継続できると、このように捉えてよいのかどうか、確認だけさせていただきたいと思います。","respondent":"安井子育て支援課長","answer":"授業の補習というのは勉強会のことだと思いますけれども、こちらについては、教師のほうで手伝うということではなくて、専門にそちらを教える方を雇ってやっているです。それはそのままこちらのほうに来ても同じように対応するということになっております。","voiceIndex":87,"id":"exchange-036"},{"speaker":"塚本委員","kind":"質問","question":"わかりました。ちょっと時間があるので、済みません、最初に言ってはいなかったのですけれども、１２２ページの財産売払収入の株式売払収入について、これは６億１,０００万円ですが、これがケーブルテレビの保有株の収入ということだと思いますけれども、地域振興基金の積立金に充てるということになっておりますが、これはどういう考え方かということだけ最後にお伺いしたいと思います。","respondent":"本城企画財政課長","answer":"このケーブルテレビの売却収入ですが、それにつきましては、ケーブルテレビが地域メディアとして大きな役割を果たしてきたところですが、それに対する売却益も、それにかなった地域メディアというので地域振興的なものが一番それの趣旨にかなうのではないかということで。","voiceIndex":89,"id":"exchange-037"},{"speaker":"鈴木（博）委員","kind":"質問","question":"８２ページの衛生費負担金、公害健康被害補償事務費と、衛生費負担金、感染症予防費と、８６ページの衛生費補助金の感染症予防費についてお伺いいたします。最初に、公害健康被害補償制度について、簡単にご説明をお願いします。","respondent":"江部健康課長","answer":"公害健康被害補償制度についてご説明いたしますが、これは、国の法律に基づく制度でございまして、公害による健康被害を受けたという認定を受けた方につきまして、医療費の助成を行う制度です。","voiceIndex":92,"id":"exchange-038"},{"speaker":"鈴木（博）委員","kind":"意見","question":"公害健康被害補償は、昭和４０年代の煤煙、排ガス等による硫黄酸化物、窒素酸化物、元素状炭素などの大気汚染、環境汚染に対して、四日市公害訴訟を契機に、公害健康被害の補償等に関する法律が制定され、補償が行われてきました。平成２０年８月には気管支喘息の助成が全年齢まで拡大されております。同じ粒子状物質のＰＭ１０や浮遊粒子状物質ＳＰＭとの違いについてもご説明をお願いいたします。","respondent":"野呂瀬環境課長","answer":"その中でも粒径が１０マイクログラム以下のものが、これ、ＰＭ１０、粒径が２.５マイクログラム以下のものがＰＭ２.５と言って、これは微小粒子状物質と、このように分類されているところです。","voiceIndex":94,"id":"exchange-039"},{"speaker":"鈴木（博）委員","kind":"質問","question":"出足は非常によかったのですが、中途半端なようなので、ちょっと補足して、ついでに質問します。ＰＭ１０はアメリカで１９８７年から測定されている大気中を浮遊する径がおおむね１０マイクロメートルの粒子で、大気汚染の指標としてアメリカで用いられてきました。このＰＭ２.５の健康被害について、どのようなものがあるかと、その基準値について、簡単にご説明をお願いします。","respondent":"江部健康課長","answer":"ちょっと詳しい病名等については言及できませんが、大気汚染の被害に対する医療費助成制度と申しますのは、基本的には気管支喘息という認定を受けた方に対して、東京都が独自で助成する制度ですので、基本的には気管支喘息という種類の診断だと思います。","voiceIndex":96,"id":"exchange-040"},{"speaker":"鈴木（博）委員","kind":"質問","question":"補足してまた質問します。病気、症状ですが、ＰＭ２.５は非常に微小粒子なので、肺腑へ到達するので、喘息、気管支炎、肺がんの原因になるということが今心配されております。品川区では、現在、ＰＭ２.５の測定は行われているのでしょうか。測定されているとすると、その数値はいかがなのでしょうか。それを質問いたします。","respondent":"野呂瀬環境課長","answer":"その測定値は、平成２３年度のデータですけれども、環境基準を超過した日数が１２日で、年平均が大体１６.３日ということで、環境基準は達成されておりません。ちなみに、この環境基準を達成されているところは、今のところ、２３区内どこにもないと、このように聞いております。","voiceIndex":100,"id":"exchange-041"},{"speaker":"鈴木（博）委員","kind":"質問","question":"環境省の大気汚染物質広域監視システム「そらまめ君」というのがありまして、品川区の測定局は２カ所ありまして、一つが八潮で、一つが豊町です。その値自身は今現在あまり問題になっていないようです。ご説明ありがとうございました。品川区でもホームページでＰＭ２.５について十分な情報を提供し、区民の不安に答えることが必要と考えますが、区のご見解はいかがでしょうか。","respondent":"野呂瀬環境課長","answer":"環境課としましても、今、東京都のほうと情報を詰めておりまして、実際に区のホームページから東京都の測定値にリンクするような形で、ホームページを見て、ＰＭ２.５がどういうものなのかというのも含めて、ホームページに近日中にアップするような形で今進めているところです。","voiceIndex":102,"id":"exchange-042"},{"speaker":"伊藤委員","kind":"確認","question":"私からは、先ほどあった財政調整交付金についての確認と、それから、７１ページ、自転車駐車場利用について、それから５５ページのしながわ観光協会に関連して、まず三つお伺いします。財調ですけれども、これは平成２５年度１年間の品川区の全事業を算定して、なぜこれが今年は前年度、先ほど出ていたのですけれども、なぜ前年度と同額なのかということ。しかも、２８億円の補正までしていますよね。","respondent":"本城企画財政課長","answer":"一方で、先ほど、態容補正ということで、区の個別事情についてご説明させていただきましたが、その減を約１８億円見込んでおります。","voiceIndex":106,"id":"exchange-043"},{"speaker":"伊藤委員","kind":"質問","question":"だから、それは一定のさまざまな戦略もあるかもしれないし、あるいは公の場で言えない部分もあるかもしれないと私は推測するのだけれども、そういうことをしながら、でも、結果として品川区の財政がプラスになっていくということであれば、それは議会として一定評価する場合があるのだけれども、同時に、そういう事細かい部分については、もう少し議会に対して丁寧な説明があるべきと思いますが。","respondent":"本城企画財政課長","answer":"ちなみに、なかなか財調の推移、見るのが難しい面もありまして、平成２３年度は逆に逆転、マイナスになったり、そのあたりを含めて慎重に見極めて、今年度は同額とさせていただいた経緯です。","voiceIndex":108,"id":"exchange-044"},{"speaker":"伊藤委員","kind":"質問","question":"私たち自民党の勉強会でさまざまな方々に意見を聞きました。品川区はもっとお金を使うべきという話も聞いています。非常にある。このことは、過日、課長に指摘をさせていただいて、すぐ違法のビラを張っていただいたのですけれども、でも、これ、大田区と品川区の区界のことでこういうことがあるとするならば、やはり品川区もそういうことを考えるべきではないですか。答弁をお願いいたします。","respondent":"谷口交通安全担当課長","answer":"ただ、区界、あと道路法の関係、自転車法の関係で、放置禁止区域の指定の関係もございまして、近い将来、すぐとはなかなかいかないですけれども、放置禁止区域の指定ならびに自転車駐輪場も視野に入れながら検討を進めているところです。","voiceIndex":110,"id":"exchange-045"},{"speaker":"伊藤委員","kind":"質問","question":"それは理解はしますけれども、私たちが思うのは、これは何も大森駅だけの問題ではないと思いますよ。例えば、目黒駅は目黒区との区界があります。だから、おそらくどちらかの区がはっきりとした違法の自転車対策をすると、その余波が隣の区に来るということがあるわけですから、今の答弁は納得しますけれども、でも、大田区はああいう実績を出しました。だけれども、それがなぜ品川区に来るか。","respondent":"谷口交通安全担当課長","answer":"全く委員ご指摘のとおりだと思いますので、さらに大田区と協議を進めてまいりまして、ご希望に沿えるように何とか努力してまいりたいと思います。その辺のご理解をよろしくお願いいたします。","voiceIndex":112,"id":"exchange-046"},{"speaker":"伊藤委員","kind":"確認","question":"そうすると、おそらくこれはもう少し話を発展させていくと、区界の駅というのはもっとありますよね。それから、しながわ観光協会についてです。だから、それはたまたまアートホテルが大井にあるからなのかと思ったのだけれども、でも、表は品川と書いてあるだけだから、やはり品川であるならばもっと全域の情報を載せて、外国からのお客さんに対応すべきと思いますが、いかがでしょうか、お答えください。","respondent":"米田商業・観光課長","answer":"今回、そのお手元にお持ちのものにつきましては、ある程度、地域も絞らざるを得ないだろうということで、まず品川の町で一番外国の方が興味を持たれるということであれば、それは東海道筋ではないかというようなことで、そちらのほうを記載したものですが、改めてもう１回。","voiceIndex":114,"id":"exchange-047"},{"speaker":"伊藤委員","kind":"確認","question":"わかりました。そうすると、ほかの荏原、五反田地域等も特集を組むということを確認できました。羽田空港からお客さんを呼ぶ、そのことは正しい。だけれども、世界に通用する品川区の観光資源をどういうふうに磨き出して、探し出して、それを根づかせていくかということの総体的なグランドデザインと言ったらいいのか、そういうものが非常に少ない感じがするのです。","respondent":"米田商業・観光課長","answer":"いわゆる全体的なグランドデザインにつきましても、しかるべき一定の時期でそれぞれの役割をある程度果たしていったというような段階で。","voiceIndex":116,"id":"exchange-048"},{"speaker":"伊藤委員","kind":"意見","question":"観光に対する思いは私たちも非常に強いものがありますので、お願いをしておきます。それから、６１ページのこみゅにてぃぷらざ八潮に関連してであります。これはいろいろなところで聞きますけれども、利用率が非常に低いということを聞いています。この利用率を向上させるために、まず品川区がこれからどういうことを考えて企画をしていくのかということについてお聞かせください。お願いいたします。","respondent":"安藤文化スポーツ振興課長","answer":"こみゅにてぃぷらざ、２月で丸２年が過ぎました。やっと今、３年目になったところです。当初から、利用率の問題ですが、私ども、まずこのこみゅにてぃぷらざ八潮を人の集まるにぎわいのある場所にしていこうといろいろ工夫をしてまいりました。","voiceIndex":118,"id":"exchange-049"},{"speaker":"大倉委員","kind":"質問","question":"私からは、７０ページ、自転車駐車場使用料、そして１２０ページの財産貸付収入、あと、１３６ページの放置自転車等保管料に関係して伺いたいと思います。","respondent":"平澤経理課長","answer":"私から、財産貸付収入の主立った貸付先についてご答弁します。初めに、きゅりあんの駐車場、それから、劇団四季、イトーヨーカドー、それから荏原複合施設、こういったところが１,０００万円を超えるような主立った賃貸借料をいただいているところです。","voiceIndex":122,"id":"exchange-050"},{"speaker":"大倉委員","kind":"質問","question":"ほかにもＴＯＣとか、荏原複合施設の賃貸料とか、１,０００万円を超えるものがあると思うのですが、それを書かない、ここに明記しない理由は何でしょうか。","respondent":"本城企画財政課長","answer":"こちらのところにつきましては、どこまで書くかというのはあるかもしれませんが、一応、地所賃貸料という節の中の細目ということで、一番主立ったものだけ書かせていただいているです。","voiceIndex":124,"id":"exchange-051"},{"speaker":"大倉委員","kind":"意見","question":"要は、１,０００万円を超えるものが、私の手元で見ると、９個近くあるわけですよね。その中でしっかりとこういうところを明記しないといけないのかというふうに、わかりやすくしてほしいということですが、もう一度、書かない理由についてご答弁を詳しくいただければと思います。","respondent":"本城企画財政課長","answer":"いずれにしても、これからも全体の予算書のボリュームはありますが、その中でどのあたりを重点に書いていくかとか、さまざまな工夫はしていかなければいけないと考えているところです。","voiceIndex":126,"id":"exchange-052"},{"speaker":"大倉委員","kind":"質問・要望","question":"わかりました。私たちも審査する中で、よりわかりやすくつくっていただいたほうがいいと思いますので、これはぜひこういうふうにしていただきたいという要望をさせていただきたいと思います。その中に四季株式会社があると思いますが、この歳入予算事項別明細書では、劇団四季への貸付が９月分と表記されているのですが、その理由を教えてください。","respondent":"平澤経理課長","answer":"劇団四季につきましては、９カ月分ということで、こちらから歳入が発生するということでの契約でこういう書き方になっているところです。","voiceIndex":128,"id":"exchange-053"},{"speaker":"大倉委員","kind":"質問","question":"安定した経営ができるというのが、ちょっとよくわからないですが、わかりました。〔「本当にわかったのかよ」と呼ぶ者あり〕 続けて、次に行きます。自転車駐車場使用料について行きたいと思います。７１ページのこの定期利用と一時利用について、稼働率を教えていただければと思います。","respondent":"谷口交通安全担当課長","answer":"定期利用と当日利用の利用率です。区営自転車駐車場の利用率、全体的には８２％です。定期利用につきましては、定期の自転車が７６％、バイクが７４％、当日利用の自転車ですが９２％、バイクは１１１％という結果です。","voiceIndex":130,"id":"exchange-054"},{"speaker":"大倉委員","kind":"確認","question":"確認ですけれども、利用率というのを、１回使ったら利用なのか、１日使われないと利用率にならないのか、ちょっとそこを教えていただければと思います。","respondent":"谷口交通安全担当課長","answer":"全体の台数を使った回数、利用者数で割返している数字です。","voiceIndex":132,"id":"exchange-055"},{"speaker":"大倉委員","kind":"質問","question":"全体の利用台数を割ったということですが、ちょっとそこがわからなかったのですが、それで１日、一時利用のほうが９０％というふうで、ちょっと利用率が高いような気がするのですが、利用率ではなくて、この定期利用、ずっと借り続けている人は１００％なのか、要は、借りているけれども使っていないのか、借りていて使っていて１００％になっているのか、その考え方を教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":134,"id":"exchange-056"},{"speaker":"大倉委員","kind":"質問","question":"私もよく駐輪場を利用するのですが、定期利用のところはあいているけれども、一般、その日の借りる駐輪場というのがあいていないという思いがあったので、ちょっとそこを伺ったのですが、今後、多少入れ替えて、一般利用を増やしていくということなので、ぜひその辺をしっかりやっていただければ、その地域のニーズとか利用率を見ながら取り組んでいただければと思います。","respondent":"谷口交通安全担当課長","answer":"ただ、五反田はいまだに放置台数が多い状況がありますので、引き続き、駐車の設置場所も含めて検討してまいりたいと考えておるところです。","voiceIndex":137,"id":"exchange-057"},{"speaker":"大倉委員","kind":"質問・要望","question":"そういう利用率というのが、今聞いていても１００％ということなので、そこも多分、定期利用ではなくて一般利用だと思うので、そういった部分で言うと、一般利用をもう少し増やしていってもいいのかという思いも今聞いてまたさらに強くなったところです。放置自転車はまだまだこれからも課題になっていくと思いますので、ぜひさまざまな施策、取り組みをしながら取り組んでいっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":139,"id":"exchange-058"},{"speaker":"山元委員","kind":"質問・要望","question":"よろしくお願いします。そこでご質問させていただきたいのは、危機管理アドバイザーの山村武彦氏によりますと、この健康被害が２０３０年から２０３４年の５年間で死亡者数をピークを迎えると、そういう予測をされているわけですけれども、それに対して品川区としては、このアスベスト対策というのでしょうか、どのように対応なさっているのか、その辺を教えていただきたいと思います。","respondent":"野呂瀬環境課長","answer":"いずれにしても、アスベスト対策につきましては、今、委員がおっしゃったとおり、健康被害があるものなので、区としてもこういう形でいろいろな対策を講じながら、根絶に向けて取り組んでいく、こういうふうに考えているところです。","voiceIndex":141,"id":"exchange-059"},{"speaker":"山元委員","kind":"質問・要望","question":"本当にこのアスベスト、耐熱性とか、耐薬品性等々あって、また安価な工場材料ということで、９割以上が建材製品に使用されていたと。そういう人に対して周知といいますか、今まで区としてどのような周知をなさっていたのか、また、改めて品川区としてアスベスト対策をどのように思われているのか、その辺も教えていただきたいと思います。","respondent":"野呂瀬環境課長","answer":"ですから、飛散被害、いわゆる除去するときには東京都環境確保条例および大気汚染防止法に基づいて、特定建設作業の範疇にはなりますので、必ずどういう養生をして、どういう形で対策をとっているのか、これは環境課の職員も実地で検査しておりますし、逆に周知につきましても。","voiceIndex":143,"id":"exchange-060"},{"speaker":"山元委員","kind":"質問・要望","question":"最後に一つお伺いしたいのは、実は先日、商店のご主人から、アスベストの調査助成を受けたいというお話がありました。確かに年をとっていくと、そういう資料を集めたり書いたりするのは大変なのですが、少しでも簡素化といいますか、そんなことはできないのかどうかということを教えていただきたいと思います。","respondent":"野呂瀬環境課長","answer":"ただ、これ、申しわけございません、国からの補助金ということがありまして、国に対する補助を受けるための条件といいますか、いわゆる添付書類でこれとこれとこれというふうに決まっているものでございまして、ですから、説明のときにもそれはご説明しているのですけれども。","voiceIndex":145,"id":"exchange-061"},{"speaker":"山元委員","kind":"質問・要望","question":"どうかよろしくお願いいたします。その後に鶴委員も決算特別委員会でも質問させていただいたわけですけれども、なかなか品川シェルター、数的に厳しいと言いながらも、品川シェルターが８件、それから一般シェルターは４件とお伺いいたしましたけれども、その中にまた品川シェルターがどなたでも設計できるソフトを配布し、業者にマニュアルの登録を２０から３０、業者が登録なさったと聞きました。","respondent":"品川防災整備担当課長","answer":"品川シェルターの登録業者ですけれども、正確な数字はちょっと今把握はしていないですが、ほとんどは品川区内の業者になっております。","voiceIndex":147,"id":"exchange-062"},{"speaker":"山元委員","kind":"質問","question":"実際、始まったばかりなのであれですが、この８件、また一般シェルター４件という方たちの中には、登録なさった方たちというのは、実際携わったというか、そういう方というのはいらっしゃるのですか。","respondent":"品川防災整備担当課長","answer":"これは、今現在のところ、９件まで品川シェルターは実績がありますけれども、まだ業者登録したのが非常に直近の関係で、品川シェルターのほう、今現在、９件ある実績のほうは、当初、開発のほうに携わっていただいた業者のほうでつくっているというような状況です。","voiceIndex":149,"id":"exchange-063"},{"speaker":"山元委員","kind":"質問・要望","question":"そういうことを言っては大変失礼ですが、この品川シェルター、何かごつごつしていて、それは生命の安全が第一なのはもちろんのことですが、変な言い方ですが、ちょっと牢屋に入っているような、とってもこの、そういう意味で、もう少し何か発想の転換といいますか、何か若い方とか、そういうアイデアをいただいてと、もうちょっと工夫してもらえたらと思うのですが。","respondent":"品川防災整備担当課長","answer":"今回、区内の業者はじめまして２０から３０の業者が入りました。こういった業者からいろいろなアイデアを聞きまして、デザインとかそういったところも検討してまいりたいというふうに思っております。","voiceIndex":151,"id":"exchange-064"},{"speaker":"飯沼委員","kind":"確認","question":"よろしくお願いします。財調から一般財源として３４億８,０９６万円余ということで、国の補助金、都の補助金、そして一般財源、トータルが８４億６,６０５万円余になっていますが、この額が平成２５年度、５事業の予算額になっているということで、ここにこれだけ８４億６,６０５万円余の税金が５事業に使われているという理解でいいのか、まず先に確認をします。","respondent":"溝口都市開発課長","answer":"委員ご確認のとおりの財源構成になっているものです。","voiceIndex":154,"id":"exchange-065"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ここからが質問ですが、補助金の算定の仕組みの基本的なところを教えていただけたらと思うのが１点と、あと、品川区、再開発事業費が突出していると思います。なぜ国や都からこのように高額な税金が品川区のほうに投入されているのか、このなぜに答えていただきたいと思います。","respondent":"溝口都市開発課長","answer":"国費の状況ですが、当然事業を行っているものに対して予算要望等を行っていく中でついていくものですので、各区ばらばらになってくるというのは当然のことだというふうに考えているものです。","voiceIndex":156,"id":"exchange-066"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった面では、まちづくり、特に区民の皆さんに広く意見を求めていく方向がなくては、やはり公共性と言っても理解を得られないと思うので、その辺はいかがでしょうか。","respondent":"溝口都市開発課長","answer":"再開発の公共性ということですが、住民等に十分に説明をということですが、これまでも再開発事業による事前説明ですとか、また、法に基づく事前説明等、適正な段階でそれぞれ地域の方々に説明を尽くしながら事業を進めてきておりますので。","voiceIndex":160,"id":"exchange-067"},{"speaker":"飯沼委員","kind":"質問・要望","question":"代表質問のときにも紹介しましたけれども、品川区の世論調査の中で、区の重点施策の中で紹介されていましたが、区民の皆さんが再開発による地域の整備というのが、この調査が始まった昭和６１年、１６％の支持があったのが、実際にはもう５.６％に下がっている、私は区民の支持がない再開発はもうやめるべきであると思っていますが、いかがでしょうか。","respondent":"溝口都市開発課長","answer":"世論調査の結果ですが、これにつきましては、年々下がっているというお話でしたが、これまで着実に品川区が拠点開発等のまちづくりを進めていく中で、区民の皆さまから一定の理解をいただいていく中での評価。","voiceIndex":162,"id":"exchange-068"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった中で大崎を中心として、区内本当にあちこちに開発が広がっている、さらにどこまで広がるのだろうか、地域の人はぐるっと見回して、もうこれ以上の高層化は要らないと、こう言っている声がある中で、私はこの世論調査を見たら本当にどんどん下がっている、こういった意味では、品川区は改めて自信を持ってこれを示すのではなくて、再び要望をしっかり聞いて、方針を改め直すべきであると思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":164,"id":"exchange-069"},{"speaker":"本多委員","kind":"質問","question":"４２ページの滞納繰越分、５６ページの使用料について、１２０ページの財産貸付収入について、３点お聞きします。最初に滞納繰越分ですが、収入見込額について２８％の収入率ということで、この算定についてお知らせください。","respondent":"高森税務課長","answer":"そういうような状況はありますけれども、経済状況等も勘案しながら、平成２５年度におきましては、２８％の徴収率ということで算定をさせていただいているところです。","voiceIndex":166,"id":"exchange-070"},{"speaker":"本多委員","kind":"質問・要望","question":"よろしくお願いします。それで、いろいろな税の滞納というときに、国とか都で滞納者に動産類を、例えば宝石ですとか毛皮、ブランド物のバッグですとか、競り、ネットオークション等を活用しているよというのが最近すごく取り沙汰されていると思いますけれども、区の状況ですと、この３年ぐらい取り組みがあるということですが、その状況を詳しく教えてください。件数などわかったら教えてください。","respondent":"高森税務課長","answer":"平成２３年度については２回、平成２２年度についても２回ということでございまして、落札した動産につきましては、平成２４年度が４万５,０００円あまり、平成２３年度が３１万円あまり、平成２２年度２７０万円あまりということになってあります。","voiceIndex":168,"id":"exchange-071"},{"speaker":"本多委員","kind":"質問","question":"状況はわかりました。このインターネットでの公売ということで、額が仮に債権の分を超えたときとか、いろいろなケースがあると思います。物によっても、動産の中にも本当に数多く種類があると思いますので、その辺の額を超えた分は返還というようなことになると思いますが、その辺の状況とか手続きとか、こういうケースがあるよとか、なるべく詳しく教えていただければと思います。","respondent":"高森税務課長","answer":"そのような形に応じていただけない滞納者の方もいらっしゃいますので、そのような場合につきましては、法務局のほうに供託ということで手続きを完了しています。","voiceIndex":172,"id":"exchange-072"},{"speaker":"本多委員","kind":"質問","question":"このネット公売、オークションのあり方ですけれども、これだけ区も取り上げてやっているということで、自治体によってＰＲの濃淡がすごくあるという感じを受けるのですが、その辺についてはＰＲとか、どういうふうな考え方、取り組みを考えているか教えてください。","respondent":"高森税務課長","answer":"通常、インターネットオークションに参画する場合については、広報しながわ等でこういうふうなインターネットオークションによる動産の公売を実施するというような形で区民の方に周知をさせていただきまして、また、申し込みに際しては、下見会という形で。","voiceIndex":174,"id":"exchange-073"},{"speaker":"本多委員","kind":"質問","question":"下見会がどの程度手応えがあるかというか、例えば、この税に関する滞納のネットオークションですけれども、例えば全然違うもの、リサイクルのものもリボンとかで値段を決めて売ったりもしていますし、また、民間のところでもネットオークションでいろいろ競売といいますか、競りをやっていますけれども、その充実面、その辺、下見会がどこまで充実すると思われるか、その辺のことをちょっと教えてください。","respondent":"高森税務課長","answer":"これは実際にインターネットオークションのほうに参加するだけではなく、多くの区民の方に、やはり税に対する公平性を追求して、滞納処分をしっかりした形で行っているというふうないわゆる抑止力みたいな形での。","voiceIndex":176,"id":"exchange-074"},{"speaker":"本多委員","kind":"質問・要望","question":"幾らで買って、その価値を売るというところ、売る金額はこの予算書でわかりますけれども、その取り扱いというのでしょうか、幾らで買って、その価値を幾らで売るというような、その辺のところをあわせてお聞かせください。","respondent":"平澤経理課長、柏原行財政改革担当課長","answer":"そういったところがありますので、それをいろいろ検討した上で、今後どうしていくかということを研究してまいりたいと思っているところです。今回、予算で計上させていただいていますのは、あくまで予算上ですが、１株６万１,０００円ということで１万株、６億１,０００万円というふうに計上させていただいてありますので。","voiceIndex":178,"id":"exchange-075"},{"speaker":"本多委員","kind":"質問","question":"５６ページの使用料についてですが、今定例会で出されています議案の中で、きゅりあんの件ですとか、また、きゅりあんに準じたスクエア荏原の料金設定など示されていまして、安く使いやすいということで、区民委員会の審議ではよしということで可決をされておりますので、その料金設定、きゅりあんですとか、スクエア荏原ですとか、仮に今までも使っている五反田文化センターの音楽ホールですとか。","respondent":"本城企画財政課長","answer":"そのようなことで、今、委員からご指摘いただいたことも含めて、受益者負担のあり方の全般について、これから長期基本計画の見直しを行う中で、受益者負担の再整理を改めてきちんとしていきたいと考えております。その中で全般的な検討をしていく予定と考えているところです。","voiceIndex":181,"id":"exchange-076"},{"speaker":"本多委員","kind":"質問・要望","question":"１２０ページの財産貸付収入ですけれども、地所賃貸料というところで、学校法人青蘭学院等というところで出ていますけれども、品川区との青蘭学院などとのつながりということで、歳入の視点で、区の保養所が、今、品川荘、光林荘が貸付制度に変わって利用率が非常に下がっているというところで、区民委員会でもいろいろ議論をしているのですが、ここも歳入という視点で、企画財政課にお聞きしますが。","respondent":"本城企画財政課長、久保田地域活動課長","answer":"今、委員からご指摘いただいたことも含めて、所管のほうで幅広く検討していますので、今後のあり方について、その中で整理していきたいと考えているところです。前回、区民委員会でもそういうご意見をいただきましたので、私ども、早速ケータリングの事業者、運営事業者に対して、そういうご提案があったということを投げかけて。","voiceIndex":183,"id":"exchange-077"},{"speaker":"稲川委員","kind":"質問","question":"全体、この埋設を見ると、平成２４年度予算に比べて、額とかメートルというのですか、それが増えているのは単純にこの埋設物が増えたから収入が増えているのか、あと、公園の地下埋設物が平成２４年度も４５０メートルで、今回も４５０メートルになっているけれども、額が少なくなっておりますが、これは何か３年に一度の占用料の見直しとかがあったからこうなったのかどうかというのをお聞かせください。","respondent":"小林土木管理課長","answer":"土木占用料関係の種々のお尋ねです。順にご説明したいと思います。全体を通じて占用料が道路、公園、あるいは法定外公共物とありますけれども、それによって表示が違うというご指摘、おっしゃるとおりです。","voiceIndex":187,"id":"exchange-078"},{"speaker":"稲川委員","kind":"質問","question":"区道を差し替えたというか回して、もともと区道が抜けていたところに、そこをホームをつくったわけですから、ちょうど線路の上というのは、ある意味、占用料が発生するものではないかと、そういう感覚でいるのです。これは以前、課長に聞いたときには、公共交通機関に関しては、そういうものがなかなかとれないという話だったのですが、この鉄道および軌道に関して詳しい内容を、ご説明願います。","respondent":"小林土木管理課長","answer":"ただ、この占用料につきましては、経過として公共交通機関の接続促進等の理由から、全て免除と、鉄道が持っている敷地を使うときも区は免除だが、区が持っている土地を鉄道を通したときも免除という形で、この間、実質的な負担がないという状況にあります。","voiceIndex":189,"id":"exchange-079"},{"speaker":"稲川委員","kind":"質問","question":"時間がないので１点。例えば、バス停、長時間バスを停車するところも僕は占用料が発生すると考えているのですが、今後そういう部分で区は研究とかしていくお考えはあるかどうか、やはりバスがいるということは、車体が重たいのでアスファルトも劣化していくと思いますので、それが何かしら負担をかけていかなければいけないのではないかと思うのですが、いかがお考えか教えてください。もう結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":191,"id":"exchange-080"},{"speaker":"浅野委員","kind":"質問","question":"申請の予定件数は３件ということになっていますけれども、この３件を超えて申請があった場合には、どのように対処するのか、お断りをするのか、または補正を組んででも受け入れていくのか、この考え方について一つお伺いしたいのと、調査の助成事業につきましては、平成２３年度の補助金が２５０万円の予算でした。平成２４年度は１２５万円に下がっております。平成２５年度も１２５万円だったと思います。","respondent":"野呂瀬環境課長","answer":"それと２点目の１６万円、これは助成ですけれども、これについては全額国庫補助金ということで対応、いわゆる１０分の１０、全部補助がつくです。","voiceIndex":193,"id":"exchange-081"},{"speaker":"浅野委員","kind":"質問・要望","question":"平成２４年度の実績件数もちょっとその後で教えていただきたいと思いますけれども、先に質問します。万全な体制で臨んでいかなければならないということになりますので、まずは区がしっかりとこのアスベスト対策をしていっていただきたいと思います。これらについてもこれから区として取り組む予定があるのか、平成２５年度増やしましたけれども、その方向性について教えていただきたいと思います。","respondent":"野呂瀬環境課長","answer":"これは思っているところですけれども、今現時点でその件数の把握はしていないです。それと、あと２件というのは、環境課として私のほうでつかんでいるのは、先ほど言った調査助成、それと除去についての助成を今年度から始めた、この助成を環境課として実施しているものです。","voiceIndex":195,"id":"exchange-082"},{"speaker":"浅野委員","kind":"質問・要望","question":"続きまして、公害保健福祉事業ですが、これは歳入が平成２４年度が５７万４,０００円ですか、平成２５年度が１５５万２,０００円になっていまして、３倍ぐらいになっています。先ほど、この件についての質問もあったかと思いますが、ちょっとよく聞こえなかった部分もありますが、これはなぜ３倍近く増えているのか、認定者が増えたのかどうか、そこも含めて教えていただければと思います。","respondent":"江部健康課長","answer":"５５ページの公害保健福祉事業ということだと思いますが、これは認定を受けている方がインフルエンザの予防接種をすることに対する助成金です。","voiceIndex":197,"id":"exchange-083"},{"speaker":"浅野委員","kind":"質問・要望","question":"平成２５年度の予算で、ちょっと款は違いますけれども、防災情報など一斉に一度に配信できるようなシステムを組むということなので、このような情報もしっかりとその中に入れていくように、環境課から働きかけをしていただきたいと、そのように思いますが、いかがでしょうか。","respondent":"野呂瀬環境課長","answer":"その基準を満たしながら、当然そういうことで光化学スモッグみたいな形でやっていくようであれば、検討して区民の皆さんの不安を解消する形に万全を努めてまいりたい、このように考えておるところです。","voiceIndex":201,"id":"exchange-084"},{"speaker":"原委員","kind":"質問・要望","question":"これは五反田文化センターですけれども、スタジオとか専門的な分野でかなりそういう中規模、小規模的なところの専門家には非常にいいというふうに言われておりますので、特に私が聞きたいのは、その中のプラネタリウムについて使用料を含めてその人数、１万７１０人ですか、その辺をちょっとご説明いただきたいというのと、あと、７４ページ、これが外国人登録ですけれども、もう登録法が変わっておりまして。","respondent":"安藤文化スポーツ振興課長、井浦戸籍住民課長、白鳥高齢者いきがい課長","answer":"私のほうからは、五反田文化センターのプラネタリウムの概要についてご説明します。プラネタリウム、私どものものは、直径１２メートルのドームです。外国人登録についての制度変更等々のお尋ねです。私のほうからは、西五反田のサービス付高齢者住宅の計画につきましてご説明をします。","voiceIndex":204,"id":"exchange-085"},{"speaker":"原委員","kind":"質問","question":"プラネタリウムは、非常に丁寧に説明いただきました。それで、使用料ということだけではなくて、教育的な見地から一言お考えをいただければと。外人登録につきましては、わかりました。それとあと、高齢者住宅、今伺ったのが大体プレスの説明かと思いますけれども、その次の段階で、国と都と我が区との、その辺の助成の割合を説明願えればと思います。","respondent":"原高齢者福祉課長、白鳥高齢者いきがい課長、安藤文化スポーツ振興課長","answer":"機能として住宅、それから小規模多機能とグループホーム、こういったものが入ってありますので、グループホームと小規模多機能。私のほうからは、高齢者住宅のほうの整備助成のほうの補助金ですけれども、国のほうでこちらに書いてあるとおり、５４３万６,０００円。今後とも子どもたちに夢を与えるようなものを企画しまして映し出していきたいと思ってあります。","voiceIndex":208,"id":"exchange-086"},{"speaker":"原委員","kind":"質問","question":"これからもプラネタリウムよろしくお願いします。それから、午前中問題になっているＳＰＭとか、ＰＭ２.５、これ、場所、地理的には、高速の出口、それから煙突、それの真ん中にあるのですね。そのようなものですから、その辺のところの面積的なものと、先ほどもちょっと１回、この前の質問で聞きましたけれども、区の今後のかかわり、先々ですけれども、お考えがありましたら、よろしくお願いいたします。","respondent":"原高齢者福祉課長","answer":"そういった中で、西五反田のこういった施設については、区としても必要な施設ということで、これからも連携をしながら進めていきたいというふうに考えているところです。","voiceIndex":212,"id":"exchange-087"},{"speaker":"原委員","kind":"質問","question":"そうしましたら、今後の将来的な展開ですけれども、まず品川区民がこういった施設を優先的と言っていいのか、民間ですからそれはなかなか難しいのかもわかりませんけれども、やはりプレス発表にもあるように、区民が使えるような形でお願いをできればと思いますので、そこでもう一言いただければと。","respondent":"原高齢者福祉課長","answer":"どこまで可能かというところはありますけれども、区との連携というところはまさしくそういった部分を含めて考えているところです。","voiceIndex":214,"id":"exchange-088"},{"speaker":"松澤委員","kind":"確認","question":"何点かお聞きしたいと思います。国庫支出金が２分の１、都支出金が４分の１、残りの４分の１が財調ということで、防災広場を買う場合には、品川区の持ち出し財源はないということの確認をまずしておきたいと思います。","respondent":"品川防災整備担当課長","answer":"防災広場に関しましてですけれども、委員のおっしゃるとおり、国費のほうは２分の１、それから都費のほうで４分の１の負担、区費のほうで４分の１の負担としますが、こちらのほうを防災関係で財調のほうが適用というふうになります。","voiceIndex":217,"id":"exchange-089"},{"speaker":"松澤委員","kind":"確認","question":"品川区の持ち出しがなくて防災広場が買えますよということを確認させていただきました。そんな意味で、荏原の火災危険地域、荏原消防団は充足率１００％、今、大いに士気が上がっておりますので、何とかしてそこに欲しいということで、その防災広場そのものも区の費用がかかっていないということから、いかがですでしょうかということをまずお聞きしたいと思います。","respondent":"品川防災整備担当課長","answer":"こういったところを解消するための用地として使っていきたいというふうに考えておりますので、少しその辺のところがまだ未定な段階もありますので、その時点でまた考えていきたいというふうに思っております。","voiceIndex":219,"id":"exchange-090"},{"speaker":"松澤委員","kind":"意見","question":"いろいろ答弁の仕方はありますけれども、今、私はつくるというふうに聞こえましたので、ひとつよろしくお願い申し上げます。その反対側には２９号線が延焼遮断帯ということでできますので、この辺を含んでの特区申請を将来的に考えていくのか、あるいは研究していけるのかということについて、ちょっと長いスパンになるかもしれませんけれども、しっかりとした考えを聞きたいと思います。","respondent":"品川防災整備担当課長","answer":"こういった地区を中心に今回の不燃化特区、本格実施地区を挙げていきたいというふうに考えております。","voiceIndex":221,"id":"exchange-091"},{"speaker":"松澤委員","kind":"意見","question":"もう１点聞きたいと思いますが、あの地域にＪＴの跡地が２カ所ありまして、品川区で買っております。１カ所は防災広場、子どもたちの公園を拡幅するというような形で大変に子どもたちが喜んで遊んでいる広場ができましたけれども、もう一つは手つかずになっているのですね。あの跡地はどう活用していくのか、しばらくそのままになっていますので、この活用についてもちょっと聞きたいと思います。","respondent":"品川防災整備担当課長","answer":"逆に、この南側の用地につきましては、密集事業の代替地区として今置いてあるところです。今後、不燃化１０年プロジェクト等も検討しております。そういった中でこの用地を活用していきたいというふうに考えております。","voiceIndex":223,"id":"exchange-092"},{"speaker":"松澤委員","kind":"質問・要望","question":"いろいろと用地を確保しながら、これから研究していくということですので、あの地域は本当に危険地域ですので、延焼遮断帯ともどもしっかりと整備をしていっていただきたいと思います。次に移ります。このカラオケの使用に関して、どのような規則で、これが全体で決めているのか、各館で決めているのか、その辺をお聞きしたいと思います。","respondent":"白鳥高齢者いきがい課長","answer":"目的外、こちらにつきましては、平日の５時以降、そして日曜日の利用ですけれども、こちらにつきましては、目的外利用ということで、このようなカラオケ装置のご利用は当初からお断りをしています。","voiceIndex":225,"id":"exchange-093"},{"speaker":"松澤委員","kind":"質問・要望","question":"近隣に対する配慮と言いますけれども、夜はともかく日曜日の昼間、これ、お年寄りたちが楽しみにして歌を歌うものを、それをだめですよというのは、これはおかしい。それなりの設備をしているわけですから、設備をし直すなり、あるいは近隣と話をしてもらうなりして、これは使えるようにしなかったらおかしいですよ。これは絶対におかしい。この辺しっかりともう一度答弁いただきたいと思います。","respondent":"白鳥高齢者いきがい課長","answer":"このようなことをこれからどうするかというようなことも含めまして、これから検討してまいりたいというふうに思っております。","voiceIndex":227,"id":"exchange-094"},{"speaker":"松澤委員","kind":"質問・要望","question":"今の答弁で可としますけれども、その音が本当にうるさい音なのか、その辺もしっかり調査してください。その辺のことをしっかりと調査していただきたいというふうに思います。最後の質問。５３ページの庁舎管理費負担金１億３,２２６万４,０００円、これが前年度から比べて相当多くなっておりますけれども、これ、電気代か何かなのでしょうか。この辺ちょっとお聞きしたいと思います。","respondent":"平澤経理課長","answer":"前年と比べまして、委員ご指摘のとおり、相当数上がっているわけですが、こちらにつきましては、総合庁舎は区分所有しています。来年度ですけれども、大規模な例えば外壁の改修工事とか、屋上の防水工事をやらせていただきます。その負担金が増えたです。","voiceIndex":229,"id":"exchange-095"},{"speaker":"松澤委員","kind":"質問","question":"わかりました。そうすると、工事をするので、その分お金をいただきましたということですね。実は、この５３ページ、いろいろと東京都品川都税事務所から職員団体、品川区友好協会、ここまでいろいろ貸しているのです。当然ながら、部屋を貸している家賃というのですか、これもとっていると思いますが、これの負担割合がどれぐらいになっているのかを聞きたいと思います。","respondent":"平澤経理課長","answer":"こちらにつきましては、例えば職員互助会は、一番大きなところで行きますと食堂があります。こちらが５６０平方メートルほどございまして、ちょっと細かな数字で恐縮ですけれども、０.０４９１％のところを範囲といたしまして、家賃をいただいているところです。","voiceIndex":231,"id":"exchange-096"},{"speaker":"松澤委員","kind":"確認","question":"時間がないのであれですけれども、そうすると、ほかの職員互助会、みずほ銀行、職員団体、それぞれ応分にいただいて、それはしっかりと精査していますということでよろしいですか。確認しておきます。","respondent":"平澤経理課長","answer":"それぞれの団体ごとに区分がございまして、それぞれの団体ごとに金額を設定しているですので、一律ということではございません。","voiceIndex":233,"id":"exchange-097"},{"speaker":"井上委員","kind":"質問","question":"私は、１２款使用料及び手数料で、５６ページの集会所使用料、６４ページの障害者住宅使用料、１４款都支出金で、１０４ページの放課後子ども教室等補助金、あと、１０８ページ、子宮頸がん等予防接種助成補助金についてお伺いしたいと思います。ほかにもこういったバランスの悪い施設というのはあるのでしょうか。どのように把握をされているのかお伺いしたいと思います。","respondent":"久保田地域活動課長","answer":"そういう施設ですけれども、済みません、私のほうでスクリーンが使いづらいとか、明るさの問題とか、カーテンでという話は、今のところ私のところには届いていません。","voiceIndex":236,"id":"exchange-098"},{"speaker":"井上委員","kind":"質問・要望","question":"それについていかがですかということで、少しお考えと、もう一つ質問ですが、区民サービスで区民集会所が２カ月前から利用予約ができるということで大変評価をされているかと思うのですが、それでもお金を払ったら予定の変更、講師の変更などで変えたいと思ったときに、もうその２カ月前で１週間たったとしても、キャンセル料を払って、もう一度。","respondent":"久保田地域活動課長","answer":"利用の状況が変更等されますと、キャンセル料をいただいて、半分お返しをしているという状況でございまして、これについては、私どももそのような声があるというのは聞いてあります。","voiceIndex":238,"id":"exchange-099"},{"speaker":"井上委員","kind":"質問・要望","question":"これは何回かほかのところでも要望していますので、ぜひ検討をお願いしたいと思います。次は、子宮頸がん等予防接種助成金についてですけれども、今年度、平成２５年度は全額補助と対象者の拡大ということで予算措置がされていると思いますが、改めて昨年の対象者人数と接種率を教えてください。","respondent":"伊津野保健予防課長","answer":"平成２２年度から始まりまして、今年度は中学１年生を対象としております。実施対象者としましては１,１１８人で、接種率としましては、今のところは３５％ほどであります。","voiceIndex":240,"id":"exchange-100"},{"speaker":"井上委員","kind":"質問","question":"予防接種の副作用についてですけれども、子宮頸がん予防ワクチンで、現在、重篤な状況である方が出ているという報告はありますけれども、区内ではそのようなケースがあるのか、実態がどうなのか教えてください。","respondent":"伊津野保健予防課長","answer":"子宮頸がん予防ワクチンにおいて、そういう重篤な副作用が起きているということは聞いておりません。","voiceIndex":242,"id":"exchange-101"},{"speaker":"井上委員","kind":"質問","question":"定期予防接種化に向けて、これについては慎重にというような声もある中で、閣議決定がされたという報道がありましたけれども、これによってどういうスケジュールになっていくのかということと、区の準備というものがどんなことが必要になっていくのか教えてください。","respondent":"伊津野保健予防課長","answer":"今のところ、４月１日に定期接種化という形でスケジュールは進んでおります。区のほうとしましても、医師会等との単価の設定とか、契約を今準備している段階であります。","voiceIndex":244,"id":"exchange-102"},{"speaker":"井上委員","kind":"質問","question":"今、区内では重篤なケースというのが報告されていないということだったのですけれども、今いろいろなところで声を聞く中では、副作用についての情報を知らなかったという保護者が安易に予防接種をしてしまったということを悔いているとか、そういうブログとか、そういう情報とかあるので、十分に理解をした上で注意をしなければいけないということも含めて。","respondent":"伊津野保健予防課長","answer":"これにつきましては、十分な接種後の時間を置くとか、十分な対応をすることで防げると考えていますので、これは医師会等、あるいは接種の案内等におきまして十分な周知をしていきたいと考えています。","voiceIndex":246,"id":"exchange-103"},{"speaker":"井上委員","kind":"意見","question":"ちょっと済みません、使用料で飛んでしまったので障害者住宅の使用料のところに行きたいと思うのですが、６４ページの使用料では、障害者住宅が２戸ということになっておりますけれども、これは何年前から２戸の状態が続いているのかということと、現在、入居の方は何年ぐらい入居されている方なのか、その状況をお知らせください。","respondent":"永尾障害者福祉課長","answer":"こちらは平塚希望荘といいまして、家庭あんしんセンターの中にある住宅です。現在、２戸ですけれども、平成８年４月に設置されておりまして、今、２戸とも埋まっていますけれども、いつから入居というのは、ちょっと手元に資料は今ございません。","voiceIndex":248,"id":"exchange-104"},{"speaker":"井上委員","kind":"質問","question":"障害者住宅が品川区には２戸しかないという、その状況に対して品川区はどのようにこれを評価をされているのか伺いたいと思います。それから、施設整備というところのほかに、障害者住宅拡充に向けて何かほかに私が知らないだけかもしれません、取り組まれていることがあったら教えてください。","respondent":"永尾障害者福祉課長、白鳥高齢者いきがい課長","answer":"ただ、障害者住宅あっせん事業というのもやっております。こちらにつきまして、平成２３年度に１件あっただけで、過去５年間、１件も申請がないような状況になっています。障害者の方の住宅ですけれども、高齢者住宅の枠の中で２カ所あります。一つは東品川のわかくさ荘、こちらは戸数２戸です。そして、民間借上型のグレースマンション、こちらのほうの戸数も２戸、合計で４戸です。","voiceIndex":250,"id":"exchange-105"},{"speaker":"井上委員","kind":"提案","question":"この自炊ということは、資料の中にもそういう表記がありまして、当事者の方から、これは外してほしいという要望は出ていたかと思います。ですから、そういうことを総合的に考えながら改修を呼びかけて、それに手を挙げていただいた民間賃貸住宅の方にもお願いをするということも検討してもいいのではないかというふうに思いますけれども、いかがでしょうか。","respondent":"永尾障害者福祉課長","answer":"障害者の住宅に関してですけれども、やはりある程度自立をしていないと、なかなかご近所の方もそこまでの目配りはできないというのがあると思います。","voiceIndex":253,"id":"exchange-106"},{"speaker":"井上委員","kind":"質問・要望","question":"障害者の方たちがある程度自立したければ、そういったところに住めないということではなくて、居宅サービスもありますし、障害者差別禁止法では、その障壁を取り除くということが決められて、新しい法律もできてきましたので、やはりそこは人権侵害にならないように区は取り組んでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":255,"id":"exchange-107"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"８０ページの生活保護費についてお伺いしたいと思います。保護率ですが、品川区の品川の福祉では、平成２３年度まで書かれていまして、品川区が１.４９％、それから東京都が２.１３％、国が１.６３％ということになっておりますが、平成２４年度の保護率がわかったら、それぞれ品川区と東京都と、そして国、教えていただきたいと思います。","respondent":"竹田生活福祉課長","answer":"４％ですね、４０‰、大変失礼いたしました。台東区のお話です。品川区のほうは約１５‰、そうなっておりますが、地域差が非常にございまして、上野あるいは新宿のようなターミナル駅があるところが多くなるとか、それぞれ地域による影響が出ているものです。","voiceIndex":257,"id":"exchange-108"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１月から３月までの３カ月でも１１件ぐらい報道された分だけでもあるわけですけれども、その中でも働ける年齢層、かつ２人以上の世帯でこういう事態が起こっているというのは、今までにないことではないかと言われているわけですけれども、品川区ではこういう餓死で発見されたような事態というのは今までになかったかということを１点お聞かせいただきたいのと、それから。","respondent":"竹田生活福祉課長","answer":"生活に困窮して餓死した人が品川区にいるのかというご質問ですが、そういったことは聞いておりませんので、ないというふうに考えております。それからもう１点ですが。","voiceIndex":261,"id":"exchange-109"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そのライフラインの電気、ガス、水道との連携というのは、とても大事なことだと思いますが、そこに対して実際にそれが案内をしてくださいということでお願いの文書を出しているということは議事録でも読みましたが、それが実際に機能しているのかどうか、その点について確認をさせていただきたいと思います。","respondent":"竹田生活福祉課長","answer":"相談者が一旦帰るのかというご質問ですが、生活に困窮していらっしゃる方については、職権で保護をかけるということもできますので、窓口に相談にいらっしゃった方で緊急性がある方につきましては、書類がなくても職権で保護をかけさせて保護支援しています。","voiceIndex":265,"id":"exchange-110"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ライフラインの件については、水道局は東京都の関係ですので、そこは一番できると思いますけれども、私は具体的に生活保護制度などの紹介のチラシをつくって、そういう滞納しているところには届くようにするですとか、そういうところ、また、業者といろいろと話し合いをする中で、それを具体的に機能するような。","respondent":"竹田生活福祉課長","answer":"ご相談にいらした方には、基本的には申請の意思があるというふうに捉えまして、お一人お一人に丁寧な対応をさせていただいているところです。","voiceIndex":267,"id":"exchange-111"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もう一つ、生活保護の引き下げというのが今回の自民党政権になってから出てきたわけですけれども、これは平均で６.５％、９６％が減額されるだろうということで、かなりの大きな影響を受けることになると思いますけれども、その点についてはどういうふうな検討がされているのかもお聞かせください。","respondent":"竹田生活福祉課長","answer":"私どもも社会保障審議会の資料でどういった議論が進んでいるかというのを把握しているにとどまっているものです。ただ、こちらの制度、憲法の生存権に関する大事な事項ですので、憲法第２５条生存権の趣旨にのっとって決まっていくものというふうに考えております。","voiceIndex":269,"id":"exchange-112"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"生活保護のしおりは、ぜひ、ぜひ区の施設の中に置いていただくということで強くお願いしたいと思います。そして、引き下げの問題ですけれども、この生活保護制度というのは最後のセーフティーネットです。ぜひとも区としても引き下げないように国に対して要望をしていただきたいと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":271,"id":"exchange-113"},{"speaker":"高橋委員","kind":"確認","question":"平成２５年度予算で納税義務者数を見てみると、平成２４年度が２２万７,１００人のところ、平成２５年度では２２万８,３００人、０.２６％ですけれども増えているというようなところで、昨日もお話がありましたけれども、補正予算では３％増えている、そのような中でもうちょっと特別区民税の計上というのを、言葉が適切かどうかわかりませんが、強気というか。","respondent":"高森税務課長","answer":"結果といたしまして、確かに前年度より０.２％マイナスですが、これにつきましては、歳入欠陥等生じないために、安全率というものも実は若干含ませていただいて算定をさせていただいているというところでご理解をいただきたいと思います。","voiceIndex":274,"id":"exchange-114"},{"speaker":"高橋委員","kind":"質問","question":"そうすると、さまざまほかの要素も含めてこのような特別区民税という形になっているのかと思いますが、平成２４年度の最終補正が昨日のような形でプラスになってきているという状況と平成２５年度とのかかわり、昨日もお話いただいた部分もあるかと思いますが、その点での平成２５年度に反映する、もう１年たたなければ反映されないのではないかというふうなお話もありましたけれども。","respondent":"高森税務課長","answer":"平成２５年度の予算を調整するに当たりましては、去年の段階でございましたので、過日申し上げましたとおり、ここのところの円安だとか、または株価の上昇につきましては、平成２６年度の住民税のほうに反映するということでございまして。","voiceIndex":276,"id":"exchange-115"},{"speaker":"高橋委員","kind":"質問・要望","question":"もう少しこれからは厳密に見るということで成長も考えながら見ることによって、昨日の話にまた戻ってしまいますけれども、繰入という形ではなくて、基金を取り崩していくという予算を組まなくても済むのではないか、この点についてはまた別の機会ですが、予算の特別区民税については、もう少し余裕を持って多く見ていただければと思ったのですが、では、その特別区民税を徴収するときに、特別徴収のほう。","respondent":"高森税務課長","answer":"確かに委員のお話のとおり、１００％で組めればこれは最高なわけですけれども、現実には特別徴収と言っても、中身の話になりますけれども、大きな企業もありますれば、個人経営をされているみなし法人等の特別徴収義務者もいらっしゃいまして。","voiceIndex":278,"id":"exchange-116"},{"speaker":"高橋委員","kind":"質問","question":"滞納繰越分の収入見込みについてお伺いいたします。平成２４年度は２０億円あったのですね。先ほどお話あったのですが、滞納繰越分の収入率が平成２３年度は当初の予算で２５％ですが、決算では３６％という形で職員の方々のご努力によってそのように数字が出ているという、そのような日々の働きかけを想像するのですが、それとこの現年課税分の徴収率の数字はいかがでしょうか。","respondent":"高森税務課長","answer":"これに対しての徴収率ということになりますので、収入額というのは平成２４年度をちょっと下回る状況で今算定しています。","voiceIndex":280,"id":"exchange-117"},{"speaker":"高橋委員","kind":"質問・要望","question":"納税者たる区民の方々の声、そして、税を納めているすべての方の思いとして断固たる態度で臨んでいただきたいのですが、具体的にどのような形で以前と変えて徴収の方法をされて、そして実績といいますか、こういったところがこうだったけれども、こうなったというようなことをお教えいただき、さらに今後、徴収努力、決意のほどをお話いただければと思います。","respondent":"高森税務課長","answer":"平成２４年度におきましては、現年度に対する電話催告等を、実は月に１回ですけれども、徴収率向上、徴収強化に向けた新たな取り組みも開始させていただいておりまして、さまざまな形のものが今回徴収率に反映されているというふうに理解しております。","voiceIndex":282,"id":"exchange-118"},{"speaker":"高橋委員","kind":"質問・要望","question":"はい、わかりました。本当に重要な自主財源の柱ですので、今後とも徴収努力、そして予算上の中でも詳細に厳密に計上していっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":284,"id":"exchange-119"},{"speaker":"金野委員","kind":"質問","question":"私からは、８９ページと１１３ページ、同じところに出ておりますやさしいまちづくり整備費、それから１０１ページの防犯設備整備助成金、この２点をお伺いいたします。やさしいまちづくり整備費ですけれども、国からと都から、合わせて１,６０６万円余、補助金が出ております。この補助金の内容と、それから金額に対しての内訳をお知らせください。","respondent":"山崎マスタープラン担当課長","answer":"やさしいまちづくり整備費の歳入の内訳です。幾つか項目が分かれておりまして、まずハード整備の関係では、下神明のエレベーター整備の関係の補助金です。それから、大井町周辺のバリアフリー計画に基づく、こちらのほうの経費。それから、しながわお休み石の関係です。","voiceIndex":286,"id":"exchange-120"},{"speaker":"金野委員","kind":"質問・要望","question":"いろいろな事業に使われていくということで、質問の本題に入る前に、恐縮ですが、この補助金の金額について確認をさせていただきたいのですが、予算書に載っている補助金額と、委員会資料を配られましたこちらの１１ページを照合してみると、私の見間違いでしたらご指摘ください。ここら辺のところをまず確認をさせていただきたいと思います。","respondent":"山崎マスタープラン担当課長","answer":"それで、土木費のほうにかかる金額のほうの表示と、それから、民生費のほうは、例えばソフト関係でおたがいさま運動の推進に関して４００万円の委託料に関して２分の１補助金が当たるというような都の福祉の包括補助金の関係があって、そちらのほうが参入されていたり。","voiceIndex":288,"id":"exchange-121"},{"speaker":"金野委員","kind":"質問","question":"ということは、２点目の推進費の２００万円というのも、それに加わっている話なのでしょうか。","respondent":"原高齢者福祉課長","answer":"そういった意味で予算特別委員会の資料の６ページのほうには、その旨の２００万円を計上させていただいた、こういったものです。","voiceIndex":290,"id":"exchange-122"},{"speaker":"金野委員","kind":"確認","question":"ご説明により、確認がとれました。本題のこのやさしいまちづくりの整備費の、いわゆる補助金を申請するに当たって、事業内容の規制というか、基準というか、この補助金を使うに当たっての使い道の規準とかあるのでしょうか。法令に基づいて多分これはされていくものだろうというふうに思いますけれども、どのようになっていますでしょうか、お知らせください。","respondent":"山崎マスタープラン担当課長","answer":"やさしいまちづくりの補助金の根拠です。一番もとになっているのは、平成１８年の新バリアフリー法で、いろいろ高齢者あるいは障害者の方の移動円滑化のための整備の項目が載っております。","voiceIndex":292,"id":"exchange-123"},{"speaker":"金野委員","kind":"質問","question":"そうなると、このバリアフリー化というのは、点から面へというふうに随分進んできたという形が見受けられますけれども、もっともっと、今、マスタープランのほうでも策定をされた、その中でも今後実現に向けて取り組まれていくことと思いますけれども、徐々に徐々に進んでいるこのバリアフリー化の点から面へというところでは。","respondent":"山崎マスタープラン担当課長","answer":"そうしたところの観点、バリアフリーの観点で重点整備地区というものを設けて、そこで委員おっしゃられた一定面的な整備を行うようなことになってあります。区としましても、来年度、そうした検討に入らせていただくような予定ということになってあります。","voiceIndex":294,"id":"exchange-124"},{"speaker":"金野委員","kind":"質問・要望","question":"ぜひその重点整備が全部のこの区内の重点整備をすることによって区内全体がバリアフリー化されることを願っております。どこかの時点でまたこれはお聞きさせていただきたいと考えています。予告をします。これは大変に評価をいたしております。そこで、こちらもこの申請に当たって、助成を受けるに当たって、条件があるのか、そこら辺のところをまず教えてください。","respondent":"川崎生活安全担当課長","answer":"防犯カメラの申請にあたり、条件についての質問です。条件については、５年以上継続して防犯に関する地域活動を実施することと、実施以後の翌年度以降５年間、年度末に活動報告書を提出すること等々が挙げられております。","voiceIndex":296,"id":"exchange-125"},{"speaker":"金野委員","kind":"質問","question":"５年以上の活動をされている、継続されている、あるいは、その目標を立てることをしているところということで、そうなると、今、町会等で手を挙げられる方、地域でつけられるというふうに思いますが、この防犯カメラの設置という考え方で、まちの安全・安心につながるというところでは、通学路あるいはスクールゾーン、こういったところへの設置というのは、どのようにお考えでしょうか。","respondent":"川崎生活安全担当課長","answer":"通学路やスクールゾーンへの防犯カメラの設置についてでありますが、既に設置されているところもあります。今後、町会のほうでそういうところも選定して設置していくという方向が出ております。","voiceIndex":298,"id":"exchange-126"},{"speaker":"阿部委員","kind":"質問","question":"よろしくお願いします。私のほうからは、６１ページのこみゅにてぃぷらざ八潮、それから８３ページの、先ほどもお話に出ました公害健康被害認定給付事業についてお伺いしたいと思います。先にＰＭ２.５の話でお伺いしたいのですけれども、先ほどのやりとりの中で、都でホームページ上に数値を公開しているので、区のホームページのほうでもリンクしてというお考えを伺いました。ご答弁ください。","respondent":"野呂瀬環境課長","answer":"東京都のほうで今、計測では、基準値以内ですということの情報をまず前面に出して、ＰＭ２.５はどういうものなのかと、最終的に今ある環境を測定している東京都の測定値はこういうものですとか、そういう何段階の説明を加えながら工夫して掲載してまいりたい。","voiceIndex":301,"id":"exchange-127"},{"speaker":"阿部委員","kind":"意見","question":"安心しました。ぜひわかりやすく安心できる情報提供をお願いしたいと思います。それで、ただ、詳しく見ると、例えば部屋の中身などによっても随分利用率が見込みととても少ないものと、期待にだんだん近づいているもの、いろいろあるかと思いますけれども、ちょっとその詳しい評価をお願いしたいと思います。","respondent":"安藤文化スポーツ振興課長","answer":"それと、第二音楽室も５７.６％と高こうあります。そしてあと、１階にあります地域交流室というのもあります。そこも非常に高くて５７.４％です。低いところというのは、こうやって見ますと、第二多目的室が６.２％というような形になってあります。","voiceIndex":303,"id":"exchange-128"},{"speaker":"阿部委員","kind":"質問","question":"私も過去の議事録などを見ておりますけれども、やはりこれがどのような中身にしていくかということをかなり質問をさせていただきました。その中身がどのような形で展開されるかによって、地域の中でこの施設が生きてくるかどうかが大きく変わってくる。品川区としては、このこみゅにてぃぷらざ八潮、にぎわい創出、そのコンセプトを十分にそれは検討をされ、期待された成果を得ているとお考えでしょうか。","respondent":"日下部企画部長","answer":"確かに今の現状、実績から参りますと、私どもが当初想定していたような利用の実績が上がっていないということについては、いろいろな面で反省をすべき点もあるでしょうし、また、いろいろな検証をしっかりやって、もっともっと地域の方々。","voiceIndex":305,"id":"exchange-129"},{"speaker":"阿部委員","kind":"質問・要望","question":"ただ、それをきちんと検討を全区あるいは区外にまでそれを波及させるような形でそれをきちんと検討していくような部署というのがどこになっていくのか、ぜひこういったことはやっていただきたいと考えていますけれども、まずは八潮について、改めてそういう検討をするお考えはあるか、あるいは、それをするとなると、どこかというのは次の質問になりますけれども、そういうお考えはありますでしょうか。","respondent":"安藤文化スポーツ振興課長","answer":"私どもも八潮のこみゅにてぃぷらざをもっと活力のあるものにするということで、今言った周りの自然だとか、そういうものを十分認識しています。今後も利用率を上げていきたいと思っています。","voiceIndex":307,"id":"exchange-130"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私は、８０ページぐらいからあります国庫補助金とか負担金、都の補助金、負担金というところ。申請をこれからするとかというと、ざっくりこれぐらいでこれから財調に対して、それを財調算定してもらう、需要額でもしてもらう、どういうふうに算定してもらおうかという作戦を練っていると思いますけれども、そこら辺の見込み、これも金額を出していると思いますけれども、そこら辺も教えてほしいと思います。","respondent":"本城企画財政課長、柏原行財政改革担当課長、原高齢者福祉課長、大串住宅担当課長、白鳥高齢者いきがい課長","answer":"補助金の幾つか今日ご説明した中で皆減の理由の中で権限委譲の関係ということで幾つかご説明させていただいた点があります。いろいろ行政需要であるとか、それから、その地域の実情であるとか、いろいろなところを考えながらではありますけれども。一方、区で建設費を出しておりますので、その部分の一定部分を事業者に負担してもらうということで、この負担金は捉えているところです。これは昨年１１月に初めて行いましたけれども、今後の２０年経過したものにつきましては。","voiceIndex":310,"id":"exchange-131"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"最初の話は、もう一度聞きます。それは何度も言っておりますけれども、意識は今違いますけれども、だけど、市町村民税ですから、その分はこういう権限委譲もあってやると、財調算定でというのだったら、都区制度をどうするのか、そのパーセント。ここら辺まで話をしてほしいのですけれども、そこら辺の見解があれば教えていただきたい。それから、これ、負担金の介護保険へ一般財源を出すわけだよね。","respondent":"日下部企画部長、柏原行財政改革担当課長、原高齢者福祉課長","answer":"結局、最後の一つの着地点といいますか、これは区長会としてしっかりと、この権限委譲のためにはぜひとも財源の措置が必要だと。そういったところもありますので、区といたしましては、地域の実情であるとか、それから、防災の面でも重要な拠点になりますので。区立はそういったところはございませんので、一定、整備にかかった一部分を根拠に負担をしていただく。","voiceIndex":316,"id":"exchange-132"},{"speaker":"石田（秀）委員","kind":"質問","question":"最後の負担金の部分は、もう一度私も勉強させてください。それと、地代の部分は、そこの部分は、今、学校というのもあったけれども、ぜひここだけはこれから御殿山小学校も、例えば土木事務所の跡も出てきたりいろいろすると思うので、ここだけは全部、ある程度、そういうことも踏まえて、貸すこと、そういうことも考えてやっていくというところだけ、もう１回答弁をお願いします。","respondent":"柏原行財政改革担当課長","answer":"委員おっしゃったとおりでございまして、そういったところを踏まえながら検討していきたいというふうに考えてあります。","voiceIndex":320,"id":"exchange-133"},{"speaker":"西本委員","kind":"質問","question":"順不同になりますけれども、まず、マイガーデンです。屋上菜園もいいのではないかという話がありましたけれども、私はかねてから、この屋上菜園という視点を加えていただけないかということを言っておりまして、既に学校の屋上を使用した屋上菜園は非常に効果が上がっているという実績ももう既にあると思いますけれども、その状況については、公園課等々はご存じでしょうか。そこを聞きたいと思います。","respondent":"多並公園課長","answer":"それがあまりにもならない場合には、浅いものということで、なかなか野菜というのは難しいかと、そういうところです。","voiceIndex":323,"id":"exchange-134"},{"speaker":"西本委員","kind":"質問・要望","question":"もう少し状況を把握してください。屋上菜園のほうは、既に幾つかの学校でやっておりまして、非常にいろいろな食物を使って子どもたちの食育も含めて、それからＰＴＡも、それから地域の方たちも非常にいい関係を持ちながらマイガーデンという形でやっておりますので、そこをしっかりと学んでいただいて応用していただきたいと思いますが、それについてもう一度お答えをお願いします。","respondent":"多並公園課長","answer":"先ほどの学校の屋上を利用してということであれば、例えば伊藤学園で屋上を使って先ほどの品川蕪やトマトであったりとか、そういうところで把握しているところはありますが、その一つのつくる際に上を利用することを前提に設計したものであれば。","voiceIndex":325,"id":"exchange-135"},{"speaker":"西本委員","kind":"質問","question":"午前中もありましたけれども、これの行き先をどうするのかというところが非常に気になるところでした。これをこの後もフォローしていきますよというお話だったのですが、これに対してどういうフォローをしていくのか、今回残念ながらグランプリにならなかった方では、もうすぐ商業ベースに乗せられるものがあったというふうに感じておりますけれども、それに関しての区の考え方を教えてください。","respondent":"福島ものづくり・経営支援課長","answer":"フォローですけれども、ファイナルに残った８人、またそれ以外のプレファイナルで１７人ほどいます。","voiceIndex":327,"id":"exchange-136"},{"speaker":"西本委員","kind":"質問・要望","question":"すぐ区商連等々にお話をしたりして、非常に商売が展開できるのではないかというふうに感じたものもあるのですね。ですので、そういう連携を品川区内の中でのいろいろな団体もいらっしゃいますので、そことつないであげて、すぐ達成できるようにして、品川区の中で起業がスムーズにできるような環境づくりをぜひ進めていただきたいというふうに思っておりますので、これは要望という形でお願いいたします。","respondent":"安藤文化スポーツ振興課長","answer":"貸し出しする際にも区内の伝統文化の利用団体だとか、そういう方々にお貸しするです。それから、茶室については、これも既にご案内のとおり、昭和初期に建てられたもので非常に価値ある建造物です。それも残しつつも、皆さんに貸していこうというような形です。","voiceIndex":329,"id":"exchange-137"},{"speaker":"西本委員","kind":"質問・要望","question":"確かに茶室がいろいろなところにできるというのは非常にいいことでありますし、また、歴史館そのものはすばらしいものですので、ＰＲのほうはやはりしっかりとしていただきたいというところです。もう一つ、シルバーセンターです。非常に場所によっての回数のばらつきがあります。これはどういうふうに考えられているのかをお聞きしたいと思います。","respondent":"安藤文化スポーツ振興課長、白鳥高齢者いきがい課長","answer":"そこではお花だとか、そういうものもつくっております。それから、こみゅにてぃぷらざにつきましては、我々も既に検討に入っていますので、期待していただきたいと思います。シルバーセンターのほうの目的外使用におけます回数の各施設のばらつきのご質問です。こちらにつきましては、各施設ごとに部屋数も異なるということもございましたので、このようなばらついた数字ということになってあります。","voiceIndex":333,"id":"exchange-138"},{"speaker":"西本委員","kind":"意見","question":"この老朽化によっても、新しいところもあれば、そこは多分利用者数が多いのではないかとは思いますけれども、シルバーセンターは地域に非常に愛されている施設でもありますので、計画的な改築等々の話があるのかどうか、ちょっとここはあれですけれども、それらのこれからのシルバーセンターの考え方についてお答えをお願いします。","respondent":"白鳥高齢者いきがい課長","answer":"ＰＲも継続していきたいと、こういうふうに考えております。","voiceIndex":336,"id":"exchange-139"},{"speaker":"西本委員","kind":"質問・要望","question":"シルバーセンター、非常に高齢の方、地域の方たちに愛されているというように思いますので、改築等々も着々と進めていきながら役割も広げていただきたいというふうに思っております。それからもう１点、近隣とのトラブルが非常に多いと思うのです。それらの最近の傾向と対策についてお答えください。","respondent":"多並公園課長、安藤文化スポーツ振興課長","answer":"今後、そこにつきましては、今もいろいろな新しいスポーツ等のご相談がありますので、そこの一つ一つ、利用等をお聞きしながらお貸しする、そのような感じで考えております。体育館だとか、学校体育館の件につきましては、スポ・レク推進委員会がありますので、そこでお話し合いをしながら、近隣とのよい関係をつくっていきたいというように考えております。","voiceIndex":338,"id":"exchange-140"},{"speaker":"武内委員","kind":"質問","question":"地所賃貸料については、この学校法人青蘭学院の賃貸料は幾らになるかということと、あと、４月から青稜高校があそこの豊葉の杜中の跡を借りて、１年半ですか、借りられるということですけれども、ここで地域開放でグラウンドと体育館を使っていた方々が、使えなくなるということで聞いておりますけれども、何団体ぐらい、グラウンドが幾つ、体育館が幾つぐらいの団体に影響が出るのか教えてください。","respondent":"平澤経理課長、柏原行財政改革担当課長","answer":"私からは、賃貸料についてのご質問についてお答えいたします。こちらの賃貸料ですが、合計で毎月の賃貸料が１,１００万円強になります。年間の今年度の分が１億３,２００万円となっております。地域開放の部分については、体育館の部分につきましては、５団体、バレーボールであったりとか、トリム体操であったりとか、いろいろ分かれてあります。","voiceIndex":342,"id":"exchange-141"},{"speaker":"武内委員","kind":"質問・要望","question":"賃貸料については、そうすると、年間で１億３,２００万円ということで、ここからプレハブを借りている分はそれは区が持っているので、その分が１６１ページですか、ここに出てきているのかと、この分を差し引いてと、３,５３５万円ですか、それを差し引いたものが実質の区の収入というふうに考えていいのでしょうか。それで、交渉した結果使えなくなった理由というのがあれば教えていただきたいと思います。","respondent":"平澤経理課長、柏原行財政改革担当課長","answer":"賃料につきましては、委員ご指摘のとおりです。端的に使えないというよりは、青稜高校の高校の部分が全部やってくるということで、平日も７時ぐらい、もう少し時間、部活動も含めて利用する。","voiceIndex":345,"id":"exchange-142"},{"speaker":"武内委員","kind":"質問","question":"そうすると、スポレクの関係ですけれども、スポレクでいろいろ調整しているということは今お話いただいて、私も聞いておりますけれども、そうすると、これは区の政策において青稜高校に貸すという中で、今まで使っていた地域の方が使えなくなっているという中で、スポレクに任せるというか、スポレクで調整してもらうしかないとは思いますけれども、そこで区の意向なり。","respondent":"柏原行財政改革担当課長","answer":"青稜高校も借りるに当たっては、地域の貢献といいますか、そういったところも踏まえて借りていきたいというところもありますので、引き続きそういった部分については青稜高校に我々のほうも話をしていって、いい方向に向かうようにということで考えております。","voiceIndex":348,"id":"exchange-143"},{"speaker":"武内委員","kind":"質問","question":"ただ、当初聞いていたのは、そういう部分ではなくて、いわゆる管理の部分で、例えば６時、７時に終わって、その後、地域に貸すに当たっても、管理をだれがするのかという部分で、何かそういう制度はできないよというような話があったらしいことも聞いているのですが、それは実際はどうなのですか。","respondent":"柏原行財政改革担当課長","answer":"それからあと、管理の部分については、若干鍵の扱いをどうするとか、いろいろ交渉の部分ではありますけれども、地域開放の部分についてですけれども、例えば、地域の防災訓練であるとか、それからあと、ちょっと小さなあれですけれども、地元で使うような防災の関係だとか。","voiceIndex":350,"id":"exchange-144"},{"speaker":"武内委員","kind":"質問・要望","question":"地域の部分は当初からそういうお話も地域からあったと思うので、ちょっとその中に地域開放のものがあったかどうか、ちょっと私、確認していないのでわからないですけれども、だから、そういう部分で、区がある程度積極的に理解をしていただくような方策に努力をしていただかないといけないのではないかと、スポレクに任せていますよというのではいけないのではないかと私は思います。","respondent":"柏原行財政改革担当課長","answer":"例えば、大きな年間の地域のイベントであるとか、そういったところ等とも調整させていただいて、なるべく青稜高校のほうも地域に貢献したいということは話に聞いてありますので、そういったところでなるべく話を進められるようにというふうに交渉しています。","voiceIndex":352,"id":"exchange-145"},{"speaker":"武内委員","kind":"質問・要望","question":"時間がまだ少しだけあるので、次のところで、この地域振興基金の株式売払が積立金が約６億円出ますけれども、これについての考え方、どういうふうに使っていくか、いわゆる果実運用型でやっていくのか、何かこれを取り崩していくのかというのがあれば教えてください。","respondent":"本城企画財政課長","answer":"これについては、今回、６億円ということで原資で積むことになりますので、その運用益を活用して、現在、地域の団体等に対して、区民活動助成金ということでこの基金を活用してやっていますので、それを充実させることを果実を運用しながらやっていくという。","voiceIndex":354,"id":"exchange-146"},{"speaker":"南委員","kind":"質問","question":"４２ページの特別区民税について伺います。国の状況について触れたいと思います。景気がよかった２００５年から２００７年は、物価はほとんど上がらないかマイナスだったという、こういう状況が過去にあります。そこで、こういう国の対策が景気回復に効果があって、品川区の場合の税収上につながる、こういうふうに考えているかどうか、そのあたりのことをまず伺いたいと思います。","respondent":"本城企画財政課長","answer":"この政策自体は、今お話がありましたように、デフレからの脱却と、日本経済の再生を目的としたということで位置づけられていると思いますが、ただ、新しい政策ですので、その効果がどのような形で具体的に波及していくかは、区政にとっても大きな問題ですので。","voiceIndex":357,"id":"exchange-147"},{"speaker":"南委員","kind":"質問・要望","question":"したがって、この問題は非常に区にとっても大事な関心事だというふうに思うわけです。それで、昨年との比較で、普通徴収を見た場合に、均等割、所得割でそれぞれ数字が示してありますけれども、この数字がどうなのか、どのくらい増えているのか、特別徴収についても、昨年との比較で何人増えているか減っているか、この数字を教えていただきたいと思います。","respondent":"高森税務課長","answer":"均等割・所得割の方につきましても１,０００人増えるというふうに見込んでいるところです。","voiceIndex":359,"id":"exchange-148"},{"speaker":"南委員","kind":"質問・要望","question":"それと同時に、納税義務者が２００万円以下、あるいは２００万円から７００万円まで、そして７００万円以上という、こういうことでそれぞれカウントをしているわけでありますけれども、これについても数字を教えていただきたいのと、そしてその数字の状況についての区の認識、それも伺いたいと思います。","respondent":"高森税務課長","answer":"今、２００万円以下、７００万円以下等々のお話がございましたけれども、これにつきましては、平成２４年度の当初賦課の状況ですが、課税標準額ということで、さまざまな控除額を引いた額ですので、これは所得額ではございませんけれども。","voiceIndex":361,"id":"exchange-149"},{"speaker":"南委員","kind":"質問・要望","question":"それと、納税義務者のところで２００万円以下の数字を示していただいて、増減の数も教えていただきましたけれども、私の記憶というか、聞き違いであればあれですが、ここは昨年と比べると３,５６６人増えているのではないかと私は思ったのですけれども、そうではなかったのでしょうか。改めてもう一度ここについて教えていただきたいと思います。","respondent":"高森税務課長","answer":"今、数字が違っている、増えているというふうなお話をいただきました。これは毎年６月に行われている当初課税の資料に基づいて今申し上げているところですので、ご理解いただきたいというふうに思います。","voiceIndex":363,"id":"exchange-150"},{"speaker":"南委員","kind":"質問・要望","question":"そういう状況の中では、収入の部分では基幹的な部分でありますので、できるだけ払っていただけるようにしなければいけないけれども、その背景の景気の状況を上向かせていかなければ、これは払いたいけれども払えない、こういう状況になるわけで、必要な意見、国等々への必要な意見を区長会あるいは課長会等々でぜひ上げていただきたい、そういうことをお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":365,"id":"exchange-151"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"初めに、補助金の考え方ですが、この補助金は、例えば区がこれはやりたい、その中で国や都がそういった事業に対して補助金制度があるから、その補助金を活用していくというのと、もともとそういった補助金の制度があるから、区としては、この事業もやろうかというような、ある意味、二通りの補助金の制度があると思いますが、その辺の区の補助金に対する考え方をお知らせいただきたいのと、あと、補助金等の。","respondent":"本城企画財政課長、伊津野保健予防課長、太田指導課長","answer":"補助金についての考え方の関係ですが、国のほう、種々補助金があることが前提で、ただ、基本的な考え方としては、あくまでも政策を実施する。感染症対策費でありますが、結核に対する血液検査でありますＱＦＴ検査というものと、性感染症対策、ＨＩＶの検査の対策費であります。それとあと、理科指導力向上事業実施委託金です。","voiceIndex":367,"id":"exchange-152"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"これは要望で終わります。特色ある教育活動、これはまだたしか１年か２年で、３年目ですか、すぐに成果が出るのかというのは非常に難しいものだと思いますが、せっかくこういった一つのことに対して一つの学校で集中的にやられているものに関しては、都の委託金ではありますが、区内の小・中学校でやっているものなので、ぜひその成果をしっかりと検証していただきたいと思います。これも要望で終わります。","respondent":"伊津野保健予防課長","answer":"委員ご指摘のように、風疹は今年になって爆発的に流行しております。流行の中心は２０代から４０代の男性でありまして、もともとワクチンを接種していない世代でありますので、こういう方に対してのワクチンの接種を勧奨していくことが必要であると考えております。","voiceIndex":371,"id":"exchange-153"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"区のそうしたときの危機感というか、そういったもの、緊急的にでもそういった対策をぜひこういった場合には検討していただいて、そして緊急的にも措置を行っていただきたいと思います。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":373,"id":"exchange-154"},{"speaker":"須貝委員","kind":"質問","question":"４１ページの歳入の中で、特別区税と特別区交付金、財調について、そして５６ページ、施設使用料についてお聞きします。もし数字が間違っていたら教えてください。平成２４年度当初予算が３４０億円で、決算時３６８億円、この数字は合っていますでしょうか。","respondent":"高森税務課長、本城企画財政課長","answer":"特別区税のほうにつきましては、合ってあります。財調交付金のほうもご指摘のとおりです。","voiceIndex":375,"id":"exchange-155"},{"speaker":"須貝委員","kind":"質問","question":"ここでお聞きしたいのですが、さっき特別区税、要は、当初予算３７９億円で決算時３９１億円、平成２３年度決算で３９５億円、平成２４年度で３９６億円という、大体安定しているのですね。それがやはり平成２５年度は３８６億円、これ、どうなのかというふうにちょっと思いますね。何かその辺について、ちょっと単純に見たらおかしいと思いますけれども、どのようにお考えでしょうか。","respondent":"本城企画財政課長、高森税務課長","answer":"来年度の平成２５年度の見込みにつきましては、先ほどの繰り返しになりますが、そういう経済動向の中で、一つでは、財調の調整三税の動きのベースを全体として見ながら、品川区の個別算定の中で、さっき、態容補正ということで。当初予算の概要ですけれども、平成２４年１月と平成２５年１月を比較しておりまして、品川区の生産人口というのが１,０００人弱増加している状況にありますけれども、普通徴収におきましては、平成２４年度上半期。","voiceIndex":378,"id":"exchange-156"},{"speaker":"須貝委員","kind":"意見","question":"ここでおもしろいのは、平成２２年度、基金から戻した額が約３２億円、そして平成２３年度２２億円、そして平成２４年度２１億円戻しています。ですが、決算のときに大体見ていると、毎年約３０億円、収支が黒字ということを公表しています。毎年なぜきちんと３０億円出るのだと。ここまで操作できる品川区の企画財政課は大したものとも思いますが、その辺についてちょっとご見解をお聞かせください。","respondent":"本城企画財政課長","answer":"最後の決算時に最終的な見込みを正確に立てられる状況で、そのときの財源の余裕を見ながら、それと実績に見合った基金を取り崩しつつ、基金を下ろさなくても一般財源で調整できるものであれば、それで対応するということで、結果として、全体の財政運営の中で最終的な決算は。","voiceIndex":381,"id":"exchange-157"},{"speaker":"須貝委員","kind":"意見","question":"だけど、何かあたかも最初低めに設定してやっているのはどうも、先ほどお話したとおり、やはり平均値というのを見た場合に、そんなに差が出ていないと私は思うのですが、最後にもし何かありましたら一言。","respondent":"本城企画財政課長","answer":"繰り返しになりますので、特に追加ではあるものではございません。申しわけありませんが、繰り返しになるので控えします。","voiceIndex":383,"id":"exchange-158"},{"speaker":"若林委員","kind":"質問・要望","question":"最後に、８７ページのアスベスト対策事業ですが、先ほど、浅野委員からもありました、これはもう１回確認をさせていただきたいと思いますが、国のほうの社会資本整備総合交付金の中で、このアスベストの回収除去等に関する補助事業が四つあって、そのうちの二つの事業を今回のこの８７ページの予算書に載せてある、その国の四つの補助事業と、また。","respondent":"高森税務課長、永尾障害者福祉課長、和氣学務課長、野呂瀬環境課長","answer":"滞納繰越分の３％上げて２８％になった理由ですけれども、ここ数年、滞納繰越分の徴収率は３３％、３４％等、また今年も少しよろしいのですけれども。平成２６年については、まだ詳細がほとんど決まっていませんけれども、障害程度区分から障害支援区分に見直しだとか、あと。私からは、就学援助費についてお答えいたします。済みません、今、手元にないので、具体的な名称はお答えできないですけれども、考え方としましては、先ほど言ったとおり。","voiceIndex":386,"id":"exchange-159"},{"speaker":"若林委員","kind":"質問・要望","question":"区民税の滞納繰越分ですが、本当に課長おっしゃったように、近年、３０％を超える、また去年、平成２３年度は３５％を超えたという、もう既にそういう滞納繰越分についての収入率、それだけの収入率を上げるためだけのベースを既に税務のほうはお持ちだということだと思いますので、なぜ３％なのですかと、もっとそれを倍ぐらいにすると、対前年度５,０００万円から１億円まで行ってしまうわけですよね。","respondent":"高森税務課長","answer":"そういう状況でありますので、これ以上徴収率を上げるというのも、３５％だとか３６％だとかという形で予算計上するのは、ちょっと私どものほうからはかなり厳しい状況になってございましたので、平成２５年度については３％上げさせていただいて２８％。","voiceIndex":391,"id":"exchange-160"},{"speaker":"若林委員","kind":"確認","question":"よろしくお願いいたします。そこら辺の国とか都と品川区行政の補助金に関する連携というか、キャッチをするやり方というのは、どういうふうにやられているのか確認させてください。","respondent":"本城企画財政課長","answer":"ただ、それにはなかなか外郭的に書いてあったり、必ずしも現時点では不明なところもありますので、それについてはそれをもとにして東京都に積極的に働きかけて、いろいろ情報をとっていくというのが基本です。","voiceIndex":393,"id":"exchange-161"},{"speaker":"大沢委員","kind":"意見","question":"お願いします。最後になりました。４１ページ、歳入、６５ページ、しながわ中央公園、そして１３２ページ、競馬組合配分金、順番をちょっと変えてやらせていただきます。一体的なということで整備が行われているということで聞いておりますけれども、平成２５年暫定に開くということでお話いただいていますけれども、このタイムスケジュールといいますか、今後の進め方、進捗についてお聞かせください。","respondent":"多並公園課長","answer":"来年度につきましては、今予定していますのが、基本設計委託といういわゆる公園の配置計画等を基本的な考え方を整理する設計を行おうと考えています。","voiceIndex":396,"id":"exchange-162"},{"speaker":"大沢委員","kind":"確認","question":"済みません、「です」と言ったのかちょっと聞こえなかったのですけれども、「です」とおっしゃった前触れがあったら、何か「です、です」とおっしゃっていたので、ちょっと聞き取れなかったので、ないですか。暫定でということで、平成２５年度中に暫定開放ということで、もう１回聞きます。隣で平成２６年ということがいわれていますが、平成２５年で確認をさせてください。","respondent":"多並公園課長","answer":"平成２５年度暫定整備工事を予定しています。","voiceIndex":398,"id":"exchange-163"},{"speaker":"大沢委員","kind":"質問","question":"そうしますと、平成２５年度ですから、今年の４月から来年の３月３１日までにということで、どのような形状で、どのあたりまで暫定開放に向けて整理をされるのか教えてください。","respondent":"多並公園課長","answer":"内容につきましては、今後、最終的にはその設計、先ほど申しました中で整理をする予定ですが、基本的な考え方といたしましては、今あるところ、いわゆる広場になっている草地になっていますが、そこが開放できる状態の最低限な形で、整備というか、そのまま開放するような考え方。","voiceIndex":400,"id":"exchange-164"},{"speaker":"大沢委員","kind":"質問・要望","question":"小学校の生徒ということですから、アップダウンが激しいところですので、そこらのしっかりとした見聞をされて、安全を確保しながらということで暫定整理を行っていただきたいと思いますが、今度、将来に向けての話をしますけれども、ご存じのように、あそこの地形は非常に密集をしていて、下神明というあの土地柄がありますけれども、近い将来というのは、今後はあそこのところを整備をするに当たって、今。","respondent":"多並公園課長","answer":"現時点におきましては、ＪＴの跡地を取得し、ここを広場として活用できる、このようなところで、内容といたしましては、手法としては公園として整備をすることで考えてあります。","voiceIndex":402,"id":"exchange-165"},{"speaker":"大沢委員","kind":"意見","question":"しながわ中央公園と、ということではなくて、下神明の駅周辺とも一体的に何か整備をすることができないのかという思いの中で、いろいろと用地買収いろいろな大変な部分がありますけれども、いわゆるまちづくりという部分で考えた場合に、そのようなことは一つ考えられる案ですけれども、それはサンキューなのか、それともノーサンキューなのか、ちょっとお答えください。","respondent":"多並公園課長","answer":"今の現時点におきましては、ＪＴの公園整備のところで描いて考えているところです。","voiceIndex":404,"id":"exchange-166"},{"speaker":"大沢委員","kind":"質問","question":"競馬組合に行かせていただきます。１３２ページになりましょうか。平成２３年度は３億６,０００万円、平成２４年度が３億５,９００万円、平成２５年度３億４,５００万円、年々下がっています。この連結収支の中でここの収支が悪いと、連結ベースの数字にも響いてくるのではないかと思いますけれども、そこのところはどういうふうにお考えになって策を講じていくのか教えてください。","respondent":"本城企画財政課長","answer":"連結ベースの財政状況を見る中では、競馬組合も含めたということになってきますので、そちらの状況の推移が全体としての連結にはかかわってくるという形です。","voiceIndex":406,"id":"exchange-167"},{"speaker":"大沢委員","kind":"質問","question":"今、かかわってくることをお話させていただいたので、かかわってきますというご答弁をいただきたかったのではなくて、かかわってくるのだから、ここのところで配分金が年々落ちていることに関して、連結収支の計算をするときにここの部分にも数字として響いてくるのではないですか、これに対してどういうふうに措置を講ずる、とういうふうに考えていらっしゃいますかということを今問うたのでありまして。","respondent":"濱野区長","answer":"ありませんが、こういう形で、要するに、配分金が少なくなるとか、あるいは極端な話が解散をするというようなときには、今、積み立ててある金額だけでは足りないとすれば、２３区が拠出をして、そして解散をするというような、これはもうあくまで仮定の話ですけれども。","voiceIndex":408,"id":"exchange-168"},{"speaker":"大沢委員","kind":"提案","question":"この配分金の低下に関することで、これは低下するということは収入が少ないから配分金が減ってきているということだと私は考えておりますけれども、では、一体とめるにはどうすればいいかということ、さまざま議長からも区長からも競馬組合の取り組みについてはそれぞれお伺いをしてありますけれども、私は一つの提案として、例えば、品川区で、大井競馬場は品川区内にあります。","respondent":"武内総務課長","answer":"従来から特別区競馬組合の主催におきましては、２３区長杯というのがありまして、それで、その開催ごとに、例えば品川区でしたら１１月２３日に品川区長杯ということが行われておりまして、それには、各区それぞれ対応の仕方が、温度差があるわけですけれども。","voiceIndex":410,"id":"exchange-169"},{"speaker":"大沢委員","kind":"質問・要望","question":"１１月２３日、品川区長杯、それは議長からも伺っていましたが、地元の利があるということで、やはり地元の土地を提供してやっている、これは本当に品川区の強みですので、１１月２３日１回とは言わずに、年に最低でも３回ぐらい品川区長杯ということで、この配分金の減をとめるための何か策を講じないと、今後の若者の年代、どんどんこういうギャンブルから離れていくような文化の気風すらありますので。","respondent":"武内総務課長","answer":"確かに品川区内に大井競馬場があるということでかかわりは非常に強いかとは思いますけれども、何分にも主催のその辺のＰＲだとか、考え方というのは、競馬組合の中で考えることでありまして、オブザーバー的に私ども区の職員がかかわるということは当然あるわけですけれども。","voiceIndex":412,"id":"exchange-170"},{"speaker":"大沢委員","kind":"質問・要望","question":"そこで、過日、補正予算が国で成立いたしましたけれども、この本予算の中で、歳入に占める、期間は非常に短いですけれども、国からの補正がこの予算の中にどのような形で反映されているのか、期間は短い、私、調べたところによりますと、やはり減災防災対策、あるいはその対策の一環として耐震、そして橋梁の補強改修とかというのは存じておりますけれども、区の中でこの４１ページの歳入の中で。","respondent":"本城企画財政課長","answer":"今回の国のほうからの緊急対策の一環で来たものにつきましては、平成２４年度の補正のほうを受け皿として活用して、そして補正の中で繰越しという形にしておりますので、そのものに関しては、事業費規模で約１億７,０００万円ということになるのですが。","voiceIndex":414,"id":"exchange-171"},{"speaker":"大沢委員","kind":"確認","question":"補正ということで、緊急経済対策あるいは防災対策でということで、補正も過日、最終補正ということで確認させていただきましたので、そこらのところは知識が稚拙だと思ったので確認させていただきました。権限委譲の中で地域主権というような文言が出てきましたけれども、一体この地域主権、地方分権、何が違うのか教えてください。","respondent":"本城企画財政課長","answer":"ただ、実際に法制の名称の中では地域主権という形ではなくて、地方分権ということでやっているところです。今の範囲で一応お答えします。","voiceIndex":416,"id":"exchange-172"},{"speaker":"大沢委員","kind":"質問","question":"改めて地域主権とか地方分権とかではなくて、主権とは何ですか。","respondent":"日下部企画部長","answer":"先ほどの企画財政課長の答弁を若干補足しますと、地方分権というのは、今まで国で持っていた権限を地方にいわば分割をすると、配分替えをするということが中心でありまして、一方で、地域主権というのは、どちらかというと、地域側にとった地域から見た言い方になっておりまして。","voiceIndex":418,"id":"exchange-173"},{"speaker":"大沢委員","kind":"質問・要望","question":"ですから、そこのところ、地域主権改革の一環として云々なる文言は結構たくさん出てきますけれども、去年の１２月２６日に劇的な政権交代を果たしました。そこのところでどういうふうに、いや、政府のことですから、私は区には問いませんが、どのように考えていらっしゃるのかということで、私、今聞いているわけで、そこのところをちょっと部長のお考えを聞かせていただきたいと思います。","respondent":"日下部企画部長","answer":"ただ、今確かに政権は変わりましたけれども、先般もいろいろ国のほうが総務大臣のいろいろな談話等を見ましても、今後とも引き続き、この間の地方分権、それから地域主権、いろいろな言い方は変わってきた経緯はありますが。","voiceIndex":420,"id":"exchange-174"},{"speaker":"大沢委員","kind":"質問","question":"もう非常にいいご答弁をいただいたので、お話はもうこれでやめにしますけれども、いずれにしても、言葉というのは非常に大事なことだと思うのですね。ですから、地域主権なる言葉をもう１回考え直してみる必要が私はあるのではないかという疑問を投げかけて、１分２１秒を残して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":422,"id":"exchange-175"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=984#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":122692,"voices":423}}]);
